1	// `document` is absent when this file is loaded from Node for tests; the
2	// DOM is only ever touched from render/bind functions, which tests do not call.
3	const app = typeof document !== "undefined" && document.querySelector ? document.querySelector("#app") : null;
4	let quizData = null;
5	let themes = [];
6	let state = { theme: null, quiz: null, index: 0, answers: [] };
7	
8	/* -------------------------------------------------- one test, one URL ----
9	   每个测试产品有自己的网址 /t/<product_id>；本页从 URL 解析当前产品，
10	   只载入该产品的主题。单主题产品直接进封面页（标题 + 开始），
11	   多主题产品（未来的 bundle）才显示该产品内的主题列表。
12	   URL 本身不承载解锁状态：解锁凭证在 localStorage + 服务端绑定里。  */
13	const DEFAULT_TEST_ID = "greek_goddess";
14	
15	function currentTestId() {
16	  try {
17	    const match = String(location.pathname || "").match(/^\/t\/([a-z0-9_-]+)/i);
18	    if (match) return match[1].toLowerCase();
19	    const query = new URLSearchParams(location.search || "").get("test_id");
20	    if (query) return String(query).toLowerCase();
21	  } catch (error) { /* no location in some environments */ }
22	  return DEFAULT_TEST_ID;
23	}
24	
25	/* ------------------------------------------------------- license gate ----
26	   付费兑换码 + 设备绑定。浏览器只保存 {code, secret}（localStorage）；
27	   评分与判定全部在服务端完成，前端拿到的内容不含任何权重矩阵，
28	   结果数据也只在答完后才返回、且只返回命中的那一条。
29	   门还做产品匹配：A 测试的码在 B 测试页面激活时提示归属，不解绑。    */
30	const LICENSE_KEY = "[REDACTED:SECRET_ASSIGNMENT]";
31	
32	function getLicense() {
33	  try { return JSON.parse(localStorage.getItem(LICENSE_KEY) || "null"); } catch (error) { return null; }
34	}
35	function saveLicense(license) {
36	  try { localStorage.setItem(LICENSE_KEY, JSON.stringify(license)); } catch (error) { /* private mode */ }
37	}
38	function clearLicense() {
39	  try { localStorage.removeItem(LICENSE_KEY); } catch (error) { /* ignore */ }
40	}
41	
42	// 辅助指纹：只用于服务端记录不一致次数，从不作为拦截条件。
43	function deviceFingerprint() {
44	  const parts = [
45	    typeof navigator !== "undefined" ? navigator.userAgent || "" : "",
46	    typeof navigator !== "undefined" ? navigator.language || "" : "",
47	    typeof screen !== "undefined" && screen ? `${screen.width}x${screen.height}x${screen.colorDepth}` : "",
48	    typeof Intl !== "undefined" && Intl.DateTimeFormat ? Intl.DateTimeFormat().resolvedOptions().timeZone || "" : "",
49	    typeof navigator !== "undefined" ? navigator.platform || "" : "",
50	  ];
51	  return parts.join("|");
52	}
53	
54	async function api(path, body) {
55	  const response = await fetch(path, {
56	    method: "POST",
57	    headers: { "Content-Type": "application/json" },
58	    body: JSON.stringify(body || {})
59	  });
60	  let data = {};
61	  try { data = await response.json(); } catch (error) { /* non-json error body */ }
62	  return { ok: response.ok, status: response.status, data };
63	}
64	
65	async function initApp() {
66	  state.testId = currentTestId();
67	  const stored = getLicense();
68	  if (stored && stored.code && stored.secret) {
69	    const verified = await api("/api/verify-license", {
70	      code: stored.code, secret: stored.secret, fingerprint: deviceFingerprint()
71	    });
72	    if (verified.ok && verified.data.ok) {
73	      // 绑定有效，但码属于另一个测试：保留凭证，本页仍上锁并说明归属。
74	      if (verified.data.product_id !== state.testId) {
75	        return renderGate(`该兑换码属于《${verified.data.product_name || verified.data.product_id}》测试，请打开对应网址使用。`);
76	      }
77	      return loadContent();
78	    }
79	    clearLicense();
80	  }
81	  renderGate();
82	}
83	
84	function renderGate(message) {
85	  shell(`<section class="hero gate-hero"><div class="eyebrow">Redeem</div><h1>输入兑换码</h1><p class="lead">激活后与当前浏览器绑定，之后打开页面即可直接进入。</p><div class="gate-form"><input id="gate-code" class="gate-input" type="text" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码"><button class="primary" id="gate-submit">激活</button></div><p class="gate-error" id="gate-error" role="alert">${message || ""}</p><p class="notice">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需要重新激活，届时可联系卖家重置绑定。</p></section>`, "Redeem");
86	  const input = document.querySelector("#gate-code");
87	  const submit = document.querySelector("#gate-submit");
88	  const showError = (text) => { const el = document.querySelector("#gate-error"); if (el) el.textContent = text; };
89	  const run = async () => {
90	    const code = (input.value || "").trim();
91	    if (!code) { showError("请输入兑换码。"); return; }
92	    submit.disabled = true;
93	    submit.textContent = "验证中…";
94	    const stored = getLicense();
95	    const result = await api("/api/redeem", { code, secret: stored ? stored.secret : null, fingerprint: deviceFingerprint() });
96	    submit.disabled = false;
97	    submit.textContent = "激活";
98	    if (result.ok && result.data.ok && result.data.secret) {
99	      saveLicense({ code, secret: result.data.secret });
100	      if (result.data.product_id !== state.testId) {
101	        return showError(`该兑换码属于《${result.data.product_name || result.data.product_id}》测试，已在本浏览器激活；请打开对应网址使用。`);
102	      }
103	      return loadContent();
104	    }
105	    if (result.data.error === "already_bound") showError("该兑换码已在其他设备激活。如需换设备，请联系卖家重置绑定。");
106	    else if (result.data.error === "rate_limited") showError("尝试过于频繁，请一分钟后再试。");
107	    else showError("兑换码无效，请检查后重新输入。");
108	  };
109	  submit.onclick = run;
110	  input.onkeydown = (event) => { if (event.key === "Enter") { event.preventDefault(); run(); } };
111	}
112	
113	async function loadContent() {
114	  try {
115	    const response = await fetch(`/api/content?test_id=${encodeURIComponent(state.testId)}`);
116	    if (response.status === 404) {
117	      shell(`<section class="hero"><h2>测试不存在</h2><p class="lead">这个网址没有对应的测试，可能已下线或拼写有误。</p></section>`);
118	      return;
119	    }
120	    if (!response.ok) throw new Error(`content ${response.status}`);
121	    quizData = await response.json();
122	    state.productName = (quizData.product && quizData.product.name) || state.testId;
123	    themes = (quizData.themes || []).map((t) => ({
124	      id: t.id,
125	      title: t.title,
126	      subtitle: t.subtitle || t.description || "",
127	      source: "/api/content"
128	    }));
129	    home();
