136	function shell(content, right = "原创互动测试") {
137	  const theme = state.theme || "";
138	  app.innerHTML = `<div class="topbar"><span class="brand">MYTHIC / 01</span><span>${right}</span></div><div class="shell" data-theme="${theme}">${content}</div>`;
139	  // Apply theme to body for CSS variable scope
140	  document.body.setAttribute("data-theme", theme);
