147	  shell(`<section class="hero"><div class="eyebrow">A small ritual for self-discovery</div><h1>选择一个<br>故事主题。</h1><p class="lead">${state.productName || "本合集"}内包含 ${themes.length} 个测试。</p></section><section class="grid">${themes.map((t, i) => `<button class="theme-card" data-theme="${t.id}"><span class="count">0${String(i + 1).padStart(2, "0")}</span><div class="eyebrow">choose</div><h3>${t.title}</h3><p>${t.subtitle}</p></button>`).join("")}</section><p class="notice">这些测试是原创的象征性娱乐内容，不是心理诊断。</p>`);
148	  document.querySelectorAll(".theme-card[data-theme]").forEach((el) => {
149	    el.addEventListener("click", (event) => {
150	      event.stopPropagation();
151	      start(el.dataset.theme);
