157	  shell(`<section class="hero cover-hero"><div class="eyebrow">${state.productName || "MYTHIC TEST"}</div><h1>${theme.title}</h1><p class="lead">${theme.subtitle}</p><div class="cover-actions"><button class="primary" id="cover-start">开始测试</button></div><p class="notice">这是原创的象征性娱乐内容，不是心理诊断。完成后可翻面查看结果卡的另一刻。</p></section>`, state.productName || "MYTHIC TEST");
158	  document.querySelector("#cover-start").onclick = () => start(theme.id);
