169	    id: themeData.id,
170	    title: themeData.title,
171	    subtitle: themeData.subtitle || "",
172	    description: themeData.description || "",
173	    disclaimer: themeData.disclaimer || "这是一份象征性的娱乐测试。",
174	    questions: themeData.questions || [],
175	    results: themeData.results || [],
176	    scoring: themeData.scoring || null
177	  };
178	  
