192	    `<button class="option${selectedAnswer === i ? " selected" : ""}" data-answer="${i}" aria-pressed="${selectedAnswer === i}"><b>${String.fromCharCode(65 + i)}</b><span>${o.text}</span></button>`
193	  ).join("");
