195	  shell(`<div class="progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${state.quiz.questions.length}" aria-valuenow="${state.index + 1}"><i style="width:${progress}%"></i></div><div class="question-number">QUESTION ${String(state.index + 1).padStart(2, "0")} / ${state.quiz.questions.length}</div><div class="question">${q.question}</div><div class="options">${optionsHtml}</div><div class="question-actions"><button class="secondary icon-button" id="previous"${state.index === 0 ? " disabled" : ""} aria-label="上一题" title="上一题">←</button><button class="primary icon-button" id="next"${selectedAnswer === undefined ? " disabled" : ""} aria-label="${state.index + 1 === state.quiz.questions.length ? "查看结果" : "下一题"}" title="${state.index + 1 === state.quiz.questions.length ? "查看结果" : "下一题"}">→</button></div><button class="back" id="back">← 返回主题</button>`, `0${String(state.index + 1).padStart(2, "0")} / ${state.quiz.questions.length}`);
196	  
197	  document.querySelectorAll("[data-answer]").forEach((el) => {
198	    el.addEventListener("click", () => {
199	      state.answers[state.index] = Number(el.dataset.answer);
200	      if (state.index + 1 < state.quiz.questions.length) {
201	        state.index += 1;
202	        renderQuestion();
203	      } else {
204	        renderResult();
205	      }
206	    });
207	  });
208	  
209	  document.querySelector("#previous").onclick = () => {
210	    if (state.index > 0) {
211	      state.index -= 1;
212	      renderQuestion();
213	    }
214	  };
215	  document.querySelector("#next").onclick = () => {
216	    if (state.answers[state.index] === undefined) return;
217	    if (state.index + 1 < state.quiz.questions.length) {
218	      state.index += 1;
219	      renderQuestion();
220	    } else {
221	      renderResult();
222	    }
