270	  // every /t/<product_id> serves the app shell — the page itself figures out
271	  // which product it is and gates access accordingly (URL confers nothing).
272	  if (url.pathname === "/" || url.pathname === "/t" || url.pathname === "/t/") {
273	    res.writeHead(302, { Location: `/t/${DEFAULT_PRODUCT_ID}` });
274	    return res.end();
