283	    return res.end(readFileSync(join(WEB_ROOT, "index.html")));
284	  }
285	  const relative = decodeURIComponent(url.pathname);
286	  if (BLOCKED_FILENAMES.has(relative.split("/").pop())) {
287	    return json(res, 404, { ok: false, error: "not_found" });
288	  }
289	  let filePath = normalize(join(WEB_ROOT, relative === "/" ? "index.html" : relative));
290	  if (!filePath.startsWith(normalize(WEB_ROOT))) {
291	    return json(res, 404, { ok: false, error: "not_found" });
292	  }
