294	    return json(res, 404, { ok: false, error: "not_found" });
295	  }
296	  const type = MIME[extname(filePath)] || "application/octet-stream";
297	  res.writeHead(200, { "Content-Type": type, "Cache-Control": "no-cache" });
298	  res.end(readFileSync(filePath));
299	}
