262	/* Reusable result-card treatment */
263	.result-card { overflow: hidden; padding: 18px; border-color: color-mix(in srgb, var(--accent) 42%, var(--line)); box-shadow: 0 14px 34px rgba(38, 43, 35, .10); }
264	.result-card .visual-art { margin: -18px -18px 22px; height: 188px; }
265	.result-heading-copy { min-width: 0; }
266	.result-type { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; margin-bottom: 5px; }
267	.result-type > span:first-child { color: var(--accent); font-size: 12px; font-weight: 700; letter-spacing: .12em; }
268	.result-name-en { color: var(--muted); font-size: 12px; letter-spacing: .04em; }
269	.result-heading h2 { font-size: clamp(30px, 8vw, 42px); letter-spacing: -.04em; }
270	.result-subtitle { max-width: 38em; margin-top: 7px; color: var(--text); font-size: 15px; line-height: 1.55; }
271	.result-reading { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 6; margin: 20px 0 0; }
272	.result-card .tags { margin: 17px 0 0; }
273	.result-card .quote { margin: 20px 0 0; background: color-mix(in srgb, var(--accent) 5%, transparent); }
274	.visual-art-fallback { display: grid; place-items: center; background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 20%, var(--surface)), var(--surface)); }
275	.visual-art-fallback span { position: static; color: var(--accent); font: 700 68px Georgia, serif; opacity: .65; }
276	.visual-art-fallback-hera { background: linear-gradient(135deg, #ead7cf, #fff6ed); }
277	.visual-art-fallback-hestia { background: linear-gradient(135deg, #eadfc7, #fffaf0); }
278	.visual-art-fallback-nike { background: linear-gradient(135deg, #d9e4e6, #f8f2dd); }
279	.visual-art-fallback-circe { background: linear-gradient(135deg, #d9d2df, #f5eadb); }
280	.mythic-trace { margin-top: 20px; }
281	
282	/* 双面结果卡 —— 严格照 `hecate-flip-card.html` / `athena-double-card-test-v2.html`：
283	   · 正反面各自独立 rotateY，父容器不旋转（否则背面文字会镜像）；
284	   · .card 需要 min-height 撑住高度，因为两个面都是 position:absolute；
285	   · 每面只有「艺术图 4:5 + 姓名 + 一行标题 + 一段正文」；
286	   · 整张卡点击翻面，支持 Enter / 空格。
287	   正面正面图 assets/<theme>/<id>-front.png，背面 <id>-back.png。
288	   任何一面缺图只影响那一面，会退回符号化美术（.visual-art），不会破图。 */
289	.result-hero .scene { perspective: 1400px; }
290	.flip-card {
291	  position: relative;
292	  min-height: 720px;
293	  overflow: visible;
294	  padding: 0;
295	  border: 0;
296	  background: transparent;
297	  box-shadow: none;
298	  cursor: pointer;
299	}
300	.flip-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
301	
302	.flip-card .face {
303	  position: absolute;
304	  inset: 0;
305	  overflow: hidden;
306	  border: 2px solid #cfc4b8;
307	  border-radius: 16px;
308	  background: var(--surface);
309	  box-shadow: 0 18px 36px rgba(85, 72, 59, .15);
310	  backface-visibility: hidden;
311	  -webkit-backface-visibility: hidden;
312	  transform: rotateY(0deg);
313	  transition: transform .7s cubic-bezier(.2, .7, .2, 1), opacity .22s ease;
314	}
315	.flip-card .front { position: relative; }
316	.flip-card .back {
317	  transform: rotateY(180deg);
318	  background: #17243B;
319	  color: #efe6d7;
320	  border-color: #60708c;
321	  box-shadow: 0 22px 28px rgba(0, 0, 0, .53);
322	}
323	.flip-card.is-back .front { transform: rotateY(-180deg); pointer-events: none; }
324	.flip-card.is-back .back { transform: rotateY(0deg); pointer-events: auto; }
325	
326	/* 4:5 艺术图区 */
327	.flip-card .art {
328	  position: relative;
329	  aspect-ratio: 4 / 5;
330	  overflow: hidden;
331	  background: #eee4d6;
332	  border-bottom: 1px solid #cfc4b8;
333	}
334	.flip-card .back .art { background: #8c493d; border-color: #60708c; }
335	.flip-card .art img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: center center; }
336	.flip-card .back .art img { filter: saturate(.9) contrast(1.04); }
337	
338	.flip-fallback { position: absolute; inset: 0; }
339	.flip-fallback[hidden] { display: none; }
340	.flip-fallback .visual-art { height: 100%; margin: 0; }
341	
342	.flip-card .body { padding: 18px 22px 16px; }
343	.flip-card .eyebrow { display: flex; align-items: baseline; gap: 9px; color: var(--ink); font: 600 25px/1.15 Georgia, serif; }
344	.flip-card .eyebrow small { color: #344A68; font: 400 15px/1 Georgia, serif; letter-spacing: .04em; }
345	.flip-card .back .eyebrow, .flip-card .back .eyebrow small { color: #c5a36b; }
346	
347	.flip-card h2 { margin: 11px 0 9px; color: #a85d48; font: 500 16px/1.35 system-ui, sans-serif; }
348	.flip-card .back h2 { color: #c98b72; }
349	
350	.flip-card .reading { margin: 0; color: #514940; font-size: 14px; line-height: 1.7; -webkit-line-clamp: none; display: block; overflow: visible; }
351	.flip-card .back .reading { color: #e0d5c6; }
352	
353	/* 缺图：符号化美术接管这一面的图区 */
354	.flip-card .face.art-missing .art { background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 22%, var(--surface)), var(--surface)); }
355	
356	/* 减少运动偏好：prefers-reduced-motion 的语义是「不要位移/缩放/旋转」，
357	   而不是「取消一切状态变化的可见反馈」。所以这里保留一次不位移的交叉淡入，
358	   而不是硬切 —— 否则在关闭了系统动画的机器上（Windows MinAnimate=0）
359	   翻面看起来像「没反应」。 */
360	@media (prefers-reduced-motion: reduce) {
361	  .flip-card .face {
362	    transition: transform 0s linear, opacity .22s ease;
363	  }
364	  .flip-card .front { opacity: 1; }
365	  .flip-card.is-back .front { opacity: 0; }
366	  .flip-card .back { opacity: 0; }
367	  .flip-card.is-back .back { opacity: 1; }
368	}
369	
370	/* ------------------------------------------------------------- 封面页 ----
371	   一个测试一个网址：单主题产品的入口页，只有标题、引言和开始按钮。 */
372	.cover-hero { max-width: 460px; }
373	.cover-actions { margin: 26px 0 4px; }
374	.cover-actions .primary { padding: 13px 34px; font-size: 15px; }
375	
376	/* ------------------------------------------------------------- 兑换码门 ----
377	   激活页与结果加载态，沿用现有 hero/notice 语言，不引入新视觉体系。 */
378	.gate-hero { max-width: 420px; }
379	.gate-form { display: flex; gap: 10px; margin: 22px 0 6px; }
380	.gate-input {
381	  flex: 1; min-width: 0; padding: 12px 14px;
382	  border: 1px solid var(--line); border-radius: 12px;
383	  background: var(--surface); color: var(--ink);
384	  font: 600 15px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
385	  letter-spacing: .06em; text-transform: uppercase;
386	}
387	.gate-input:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
388	.gate-error { min-height: 20px; margin: 4px 0 0; color: #a04b3c; font-size: 13px; }
389	.result-loading { padding: 40px 0 30px; }
390	
391	@media (max-width: 420px) {
392	  .flip-card { min-height: 660px; }
393	  .flip-card .body { padding: 16px; }
394	  .flip-card .eyebrow { font-size: 22px; }
395	  .result-card { padding: 16px; }
396	  .result-card .visual-art { margin: -16px -16px 20px; height: 164px; }
397	  .result-reading { -webkit-line-clamp: 7; }
398	}
399	
400	/* ============================================================ 卡片微交互（V2 CARD_MOTION）====
401	   卡是物理收藏品，不是 UI 面板：落卡（入场）、倾角（悬停）、探视（邀请翻面）、
402	   升力（翻面）、按压（active）。邀请最多两次，之后永远安静 —— 动效只负责
403	   教会「翻面」这一件事。所有动作只用 transform / opacity / box-shadow，
404	   不触发 layout；flavor 挂在既有的 result-<id> 类上。                          */
405	
406	/* 落卡：结果渲染时，卡片像被放到桌面上 */
407	@keyframes card-arrive {
408	  0% { transform: translateY(16px) rotateX(6deg); opacity: 0; }
409	  100% { transform: translateY(0) rotateX(0); opacity: 1; }
410	}
411	.flip-card.card-arrive { animation: card-arrive .52s cubic-bezier(.2,.7,.2,1) both; will-change: transform; }
412	
413	/* 探视一（3 秒无触碰）：向左轻侧 8°，像有人掀卡角示意还有另一面 */
414	@keyframes card-peek-1 {
415	  0% { transform: rotateY(0) rotateZ(0); }
416	  38% { transform: rotateY(-8deg) rotateZ(.35deg); }
417	  58% { transform: rotateY(-6deg) rotateZ(-.2deg); }
418	  100% { transform: rotateY(0) rotateZ(0); }
419	}
420	.flip-card.card-peek-1 { animation: card-peek-1 1.15s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }
421	
422	/* 探视二（7.5 秒仍无触碰）：幅度更大并轻微离桌，然后就此打住 */
423	@keyframes card-peek-2 {
424	  0% { transform: rotateY(0) rotateZ(0) translateY(0); }
425	  40% { transform: rotateY(-12deg) rotateZ(-.5deg) translateY(-5px); }
426	  62% { transform: rotateY(-9.5deg) rotateZ(.3deg) translateY(-4px); }
427	  100% { transform: rotateY(0) rotateZ(0) translateY(0); }
428	}
429	.flip-card.card-peek-2 { animation: card-peek-2 1.3s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }
430	
431	/* 升力：翻面瞬间卡片离桌一点再落回，与 0.7s 面旋转同步 */
432	@keyframes card-flip-lift {
433	  0% { transform: translateY(0) scale(1); }
434	  50% { transform: translateY(-10px) scale(1.012); }
435	  100% { transform: translateY(0) scale(1); }
436	}
437	.flip-card.is-flipping { animation: card-flip-lift .7s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }
438	
439	/* 悬停倾角与按压：物体被手触碰时的物理反馈 */
440	.flip-card { transition: transform .18s ease; }
441	@media (hover:hover) and (pointer:fine) {
442	  .flip-card:not(.is-back):hover { transform: rotateX(1deg) rotateY(-2deg); }
443	  .flip-card.is-back:hover { transform: rotateX(1deg) rotateY(2deg); }
444	}
445	.flip-card:active { transform: scale(.985); }
446	
447	/* ---- 每位一缕风（flavor）----
448	   Hestia 火光：影染炭橙，探视放慢，像炉火的节拍；       */
449	.result-hestia.flip-card .front { box-shadow: 0 18px 36px rgba(150,74,20,.24); }
450	.result-hestia.flip-card .back { box-shadow: 0 22px 30px rgba(66,30,8,.5); }
451	.result-hestia.card-peek-1 { animation-duration: 1.45s; }
452	.result-hestia.card-peek-2 { animation-duration: 1.6s; }
453	/* Nike 风息：悬停倾角更大、探视更轻快，像翼下有风； */
454	@media (hover:hover) and (pointer:fine) {
455	  .result-nike.flip-card:not(.is-back):hover { transform: rotateX(1.2deg) rotateY(-3.2deg); }
456	}
457	.result-nike.card-peek-1 { animation-duration: .95s; }
458	.result-nike.card-peek-2 { animation-duration: 1.05s; }
459	/* Hera 凝视：不旋转，缓缓向你压近一寸，影染钴青。 */
460	@keyframes card-gaze {
461	  0% { transform: scale(1); }
462	  45% { transform: scale(1.02); }
463	  100% { transform: scale(1); }
464	}
465	.result-hera.card-peek-1 { animation-name: card-gaze; animation-duration: 1.7s; }
466	.result-hera.card-peek-2 { animation-name: card-gaze; animation-duration: 2s; }
467	.result-hera.flip-card .front { box-shadow: 0 18px 36px rgba(34,48,74,.26); }
468	.result-hera.flip-card .back { box-shadow: 0 22px 30px rgba(10,16,32,.55); }
469	/* Athena 冷静：影偏冷灰，标准节拍 */
470	.result-athena.flip-card .front { box-shadow: 0 18px 36px rgba(52,62,80,.22); }
471	/* Aphrodite 温柔：影染玫瑰，探视放缓 */
472	.result-aphrodite.flip-card .front { box-shadow: 0 18px 36px rgba(148,74,96,.22); }
473	.result-aphrodite.card-peek-1 { animation-duration: 1.4s; }
474	.result-aphrodite.card-peek-2 { animation-duration: 1.55s; }
475	/* Artemis 警觉：影染橄榄，探视轻快 */
476	.result-artemis.flip-card .front { box-shadow: 0 18px 36px rgba(74,90,58,.22); }
477	.result-artemis.card-peek-1 { animation-duration: 1.05s; }
478	.result-artemis.card-peek-2 { animation-duration: 1.15s; }
479	/* Hecate 夜行：影最深，探视最慢（夜的节拍） */
480	.result-hecate.flip-card .front { box-shadow: 0 18px 36px rgba(16,22,40,.34); }
481	.result-hecate.card-peek-1 { animation-duration: 1.5s; }
482	.result-hecate.card-peek-2 { animation-duration: 1.65s; }
483	/* Persephone 两界：影染酒色，中速 */
484	.result-persephone.flip-card .front { box-shadow: 0 18px 36px rgba(90,42,66,.24); }
485	/* Demeter 沉稳：影染赭金，慢而稳 */
486	.result-demeter.flip-card .front { box-shadow: 0 18px 36px rgba(140,96,36,.24); }
487	.result-demeter.card-peek-1 { animation-duration: 1.4s; }
488	.result-demeter.card-peek-2 { animation-duration: 1.5s; }
489	/* Medea 决断：影染深酒，探视利落 */
490	.result-medea.flip-card .front { box-shadow: 0 18px 36px rgba(64,24,38,.28); }
491	.result-medea.card-peek-1 { animation-duration: .9s; }
492	.result-medea.card-peek-2 { animation-duration: 1s; }
493	/* Atalanta 冲刺：全套最快 */
494	.result-atalanta.flip-card .front { box-shadow: 0 18px 36px rgba(96,104,50,.2); }
495	.result-atalanta.card-peek-1 { animation-duration: .85s; }
496	.result-atalanta.card-peek-2 { animation-duration: .95s; }
497	/* Circe 岛时：影染螺紫，慢 */
498	.result-circe.flip-card .front { box-shadow: 0 18px 36px rgba(78,48,92,.26); }
499	.result-circe.card-peek-1 { animation-duration: 1.5s; }
500	.result-circe.card-peek-2 { animation-duration: 1.65s; }
501	
502	/* 减少运动：一切位移归零；翻面沿用上面的透明度交叉淡入，提示文案静态出现 */
503	@media (prefers-reduced-motion: reduce) {
504	  .flip-card { transition: none; }
505	  .flip-card.card-arrive,
506	  .flip-card.card-peek-1,
507	  .flip-card.card-peek-2,
508	  .flip-card.is-flipping { animation: none; }
509	}
