// Integration test for the licensing server: boots the real server.mjs on an
// ephemeral port with a throwaway data dir and drives the whole paid flow.
//
//   node tools/test-license-server.mjs
import { spawn } from "node:child_process";
import { mkdtempSync, rmSync, readFileSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { setTimeout as sleep } from "node:timers/promises";
import { createServer as tcpProbe } from "node:net";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");

// Pick a port that is actually free — a leftover dev server on the random port
// would silently answer with old code and turn every assertion into nonsense.
function freePort() {
  return new Promise((resolve, reject) => {
    const probe = (attempt) => {
      const candidate = 8900 + Math.floor(Math.random() * 200);
      const srv = tcpProbe();
      srv.once("error", () => { if (attempt < 20) probe(attempt + 1); else reject(new Error("no free port")); });
      srv.listen(candidate, () => srv.close(() => resolve(candidate)));
    };
    probe(0);
  });
}
const PORT = await freePort();

let passed = 0;
const failures = [];
const check = async (name, fn) => {
  try {
    const d = await fn();
    passed += 1;
    console.log(`  PASS  ${name}${d ? ` — ${d}` : ""}`);
  } catch (e) {
    failures.push({ name, message: e.message });
    console.log(`  FAIL  ${name} — ${e.message}`);
  }
};
const assert = (c, m) => { if (!c) throw new Error(m); };

// A second, theme-limited product so entitlement isolation is really exercised.
// Must exist BEFORE the server spawns — the registry loads at boot.
const demoProductDir = join(ROOT, "server", "content", "products", "zz_selftest");
mkdirSync(demoProductDir, { recursive: true });
writeFileSync(join(demoProductDir, "product.json"), JSON.stringify({
  product_id: "zz_selftest",
  type: "single",
  content_file: "../../quiz_content_upgrade.json",
  theme_ids: ["greek-women"],
}, null, 2));

const dataDir = mkdtempSync(join(tmpdir(), "mythic-test-"));
const child = spawn(process.execPath, [join(ROOT, "server", "server.mjs")], {
  env: { ...process.env, MYTHIC_PORT: String(PORT), MYTHIC_DATA_DIR: dataDir },
  stdio: ["ignore", "pipe", "pipe"],
});
let serverLog = "";
let serverExit = null;
child.on("exit", (code, signal) => { serverExit = { code, signal }; serverLog += `[test] server exited code=${code} signal=${signal}
`; });
child.stdout.on("data", (d) => { serverLog += d; });
child.stderr.on("data", (d) => { serverLog += d; });

const base = `http://127.0.0.1:${PORT}`;
async function post(path, body, headers = {}) {
  const res = await fetch(base + path, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...headers },
    body: JSON.stringify(body || {}),
  });
  return { status: res.status, body: await res.json() };
}
async function get(path, headers = {}) {
  const res = await fetch(base + path, { headers });
  return { status: res.status, body: await res.json() };
}

// wait for listen
for (let i = 0; i < 50; i += 1) {
  try { await fetch(base + "/api/content"); break; } catch { await sleep(100); }
}

try {
  const adminKey = readFileSync(join(dataDir, "admin-key.txt"), "utf8").trim();
  const admin = { "x-admin-key": adminKey };
  const wrongAdmin = { "x-admin-key": "not-the-key" };

  console.log("\n1. admin");
  check("wrong admin key is rejected", async () => {
    const r = await post("/api/admin/create-codes", { count: 1 }, wrongAdmin);
    assert(r.status === 403, `expected 403, got ${r.status}`);
    return "403";
  });
  let code = "";
  await check("admin mints codes", async () => {
    const r = await post("/api/admin/create-codes", { count: 2, note: "integration" }, admin);
    assert(r.status === 200 && r.body.codes.length === 2, JSON.stringify(r.body).slice(0, 120));
    code = r.body.codes[0];
    return r.body.codes.length + " codes";
  });

  console.log("\n2. redeem & binding");
  let secret = "";
  await check("first redeem binds and returns a device secret", async () => {
    const r = await post("/api/redeem", { code, fingerprint: "fpA" });
    assert(r.status === 200 && r.body.ok && r.body.secret, JSON.stringify(r.body).slice(0, 120));
    secret = r.body.secret;
    return "secret minted";
  });
  check("a second browser cannot activate the same code", async () => {
    const r = await post("/api/redeem", { code });
    assert(r.status === 403 && r.body.error === "already_bound", JSON.stringify(r.body));
    return "403 already_bound";
  });
  check("the bound browser can re-enter idempotently", async () => {
    const r = await post("/api/redeem", { code, secret });
    assert(r.status === 200 && r.body.ok, JSON.stringify(r.body));
    return "200";
  });
  check("verify-license accepts the right secret", async () => {
    const r = await post("/api/verify-license", { code, secret });
    assert(r.status === 200, JSON.stringify(r.body));
    return "200";
  });
  check("verify-license rejects a wrong secret", async () => {
    const r = await post("/api/verify-license", { code, secret: "nope" });
    assert(r.status === 403 && r.body.error === "already_bound", JSON.stringify(r.body));
    return "403";
  });
  check("an unknown code is invalid", async () => {
    const r = await post("/api/redeem", { code: "MYTHIC-00000-00000" });
    assert(r.status === 404, JSON.stringify(r.body));
    return "404";
  });

  console.log("\n3. content protection");
  const answers = JSON.parse(readFileSync(join(ROOT, "server", "content", "quiz_content_upgrade.json"), "utf8"))
    .themes.find((t) => t.id === "greek-women").questions.map(() => 0);
  check("the private quiz file is not servable", async () => {
    const res = await fetch(`${base}/quiz_content_upgrade.json`);
    assert(res.status === 404, `expected 404, got ${res.status}`);
    return "404";
  });
  check("sanitized content carries no weights or result texts", async () => {
    const r = await get("/api/content");
    const text = JSON.stringify(r.body);
    for (const marker of ["scores", "normalization_bounds", "reading", "share_line", "mythic_trace"]) {
      assert(!text.includes(marker), `leaked ${marker}`);
    }
    return `${r.body.themes.length} themes`;
  });
  await check("score returns only the winner's record", async () => {
    const r = await post("/api/score", { theme: "greek-women", answers, code, secret });
    assert(r.status === 200 && r.body.result && r.body.result.reading, JSON.stringify(r.body).slice(0, 160));
    assert(!r.body.ranked && !r.body.scores, "must not leak the score table");
    return `winner ${r.body.winnerId}`;
  });
  check("score rejects an unlicensed caller", async () => {
    const r = await post("/api/score", { theme: "greek-women", answers, code, secret: "bad" });
    assert(r.status === 403 && r.body.error === "already_bound", JSON.stringify(r.body));
    return "403";
  });
  check("score rejects malformed answers", async () => {
    const r = await post("/api/score", { theme: "greek-women", answers: [0, 1], code, secret });
    assert(r.status === 400, JSON.stringify(r.body));
    return "400";
  });
  check("score rejects an unknown theme", async () => {
    const r = await post("/api/score", { theme: "nope", answers, code, secret });
    assert(r.status === 404, JSON.stringify(r.body));
    return "404";
  });

  console.log("\n4. reset & static");
  check("the index page is served", async () => {
    const res = await fetch(base + "/");
    const html = await res.text();
    assert(res.status === 200 && html.includes("app.js"), "index not served");
    return "200";
  });
  await check("admin reset clears the binding", async () => {
    const r = await post("/api/admin/reset-binding", { code }, admin);
    assert(r.status === 200 && r.body.ok, JSON.stringify(r.body));
    return "reset";
  });
  check("the old device secret is dead after reset", async () => {
    const r = await post("/api/verify-license", { code, secret });
    assert(r.status === 403 && r.body.error === "not_activated", JSON.stringify(r.body));
    return "403";
  });
  await check("a new browser can re-activate after reset", async () => {
    const r = await post("/api/redeem", { code, fingerprint: "fpB" });
    assert(r.status === 200 && r.body.ok && r.body.secret !== secret, JSON.stringify(r.body).slice(0, 120));
    secret = r.body.secret;
    return "rebound";
  });
  check("admin list reports binding state", async () => {
    const r = await get("/api/admin/list", admin);
    const row = r.body.licenses.find((l) => l.code === code);
    assert(row && row.activated === 1, JSON.stringify(row));
    assert(String(row.device_hash).length <= 12, "device hash must be masked");
    return "activated + masked";
  });

  console.log("\n5. multi-product");
  await check("content honours test_id", async () => {
    const r = await get(`/api/content?test_id=greek_goddess`);
    assert(r.status === 200 && r.body.themes.length === 1 && r.body.themes[0].id === "greek-women",
      `expected greek_goddess to serve exactly greek-women, got ${JSON.stringify(r.body.themes?.map((t) => t.id))}`);
    return "1 theme";
  });
  await check("a theme-limited product only serves its themes", async () => {
    const r = await get(`/api/content?test_id=zz_selftest`);
    assert(r.status === 200 && r.body.themes.length === 1 && r.body.themes[0].id === "greek-women", JSON.stringify(r.body).slice(0, 120));
    return "1 theme";
  });
  await check("unknown test_id is rejected", async () => {
    const r = await get(`/api/content?test_id=nope`);
    assert(r.status === 404 && r.body.error === "unknown_test", JSON.stringify(r.body));
    return "404";
  });
  await check("score works with explicit test_id", async () => {
    const r = await post("/api/score", { test_id: "greek_goddess", theme: "greek-women", answers, code, secret });
    assert(r.status === 200 && r.body.result, JSON.stringify(r.body).slice(0, 120));
    return "200";
  });
  await check("a code cannot score a product it was not minted for", async () => {
    const r = await post("/api/score", { test_id: "zz_selftest", theme: "greek-women", answers, code, secret });
    assert(r.status === 403 && r.body.error === "not_entitled", JSON.stringify(r.body));
    return "403 not_entitled";
  });
  let demoCode = "";
  await check("codes can be minted for another product", async () => {
    const r = await post("/api/admin/create-codes", { product_id: "zz_selftest", count: 1 }, admin);
    assert(r.status === 200 && r.body.product_id === "zz_selftest", JSON.stringify(r.body).slice(0, 120));
    demoCode = r.body.codes[0];
    return r.body.codes[0];
  });
  let demoSecret = "";
  await check("that code redeems and scores its own product", async () => {
    const redeem = await post("/api/redeem", { code: demoCode });
    assert(redeem.status === 200 && redeem.body.product_id === "zz_selftest", JSON.stringify(redeem.body).slice(0, 120));
    demoSecret = redeem.body.secret;
    const score = await post("/api/score", { test_id: "zz_selftest", theme: "greek-women", answers, code: demoCode, secret: demoSecret });
    assert(score.status === 200 && score.body.result, JSON.stringify(score.body).slice(0, 120));
    return "redeem + score";
  });
  await check("its theme set excludes other products' themes", async () => {
    const r = await post("/api/score", { test_id: "zz_selftest", theme: "grand-view-garden", answers, code: demoCode, secret: demoSecret });
    assert(r.status === 404 && r.body.error === "invalid_theme", JSON.stringify(r.body));
    return "404 invalid_theme";
  });
  await check("codes minted without product_id default to greek_goddess", async () => {
    const r = await post("/api/admin/create-codes", { count: 1 }, admin);
    assert(r.status === 200 && r.body.product_id === "greek_goddess", JSON.stringify(r.body).slice(0, 120));
    const created = await get("/api/admin/list", admin);
    const row = created.body.licenses.find((l) => l.code === r.body.codes[0]);
    assert(row && row.product_id === "greek_goddess", "list must show the default product");
    return "defaulted";
  });

  console.log("\n6. rate limiting");
  await check("redeem spraying hits the limiter", async () => {
    let limited = false;
    for (let i = 0; i < 16; i += 1) {
      const r = await post("/api/redeem", { code: `MYTHIC-GUESS-0000${i}` });
      if (r.status === 429) { limited = true; break; }
    }
    assert(limited, "never rate limited after 16 attempts");
    return "429 reached";
  });
} finally {
  child.kill();
  await sleep(150);
  try { rmSync(dataDir, { recursive: true, force: true }); } catch { /* windows file locks */ }
