// ---------------------------------------------------------------- tiny runner ----
let passed = 0;
const failures = [];
let group = "";

function describe(name, fn) {
  group = name;
  console.log(`\n${name}`);
  fn();
}

function check(name, fn) {
  try {
    const detail = fn();
    passed += 1;
    console.log(`  PASS  ${name}${detail ? ` — ${detail}` : ""}`);
  } catch (error) {
    failures.push({ group, name, message: error.message });
    console.log(`  FAIL  ${name} — ${error.message}`);
  }
}

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function assertEqual(actual, expected, message) {
  if (actual !== expected) throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
}

// ---------------------------------------------------------------- fixtures ----
// The full quiz file (weights + all result texts) is server-private; tests read
// the same copy the server reads. The browser only ever sees /api/content.
const data = { "server/content": JSON.parse(readFileSync(join(ROOT, "server", "content", "quiz_content_upgrade.json"), "utf8")) };
const themeOf = () => data["server/content"].themes.find((t) => t.id === THEME_ID);
const theme = themeOf();


const appSource = readFileSync(join(ROOT, "deploy-ready", "app.js"), "utf8");
const cssSource = readFileSync(join(ROOT, "deploy-ready", "styles.css"), "utf8");

const greekNames = {};
{
  const m = appSource.match(/const greekNames = \{([\s\S]*?)\};/);
  if (m) for (const pair of m[1].matchAll(/([a-z]+):\s*"([A-Za-z]+)"/g)) greekNames[pair[1]] = pair[2];
}

function achievableMax(questions, id) {
  return questions.reduce(
    (sum, q) => sum + Math.max(...q.options.map((o) => o.scores?.[id] ?? 0)),
    0
  );
}

function botAnswers(questions, target) {
  return questions.map((q) => {
    let best = 0;
    q.options.forEach((o, i) => {
      if ((o.scores?.[target] ?? 0) > (q.options[best].scores?.[target] ?? 0)) best = i;
    });
    return best;
  });
}

