describe("4. tie handling (three declared levels)", () => {
  // Level 1: a hair more normalised score wins, regardless of raw score.
  check("level 1 — normalised score decides before raw score", () => {
    const synthetic = {
      results: [{ id: "a" }, { id: "b" }],
      questions: [{ id: "q1", options: [{ text: "", scores: { a: 9 } }, { text: "", scores: { b: 3 } }] }],
      scoring: {
        normalization_bounds: { a: { minimum: 0, maximum: 9 }, b: { minimum: 0, maximum: 3 } },
        result_order: ["a", "b"],
      },
    };
    // raw a=9 b=0 -> equal normalised (100 vs 0)... pick a case with a real gap.
    const { winnerId } = selectWinner(synthetic, [0]);
    assertEqual(winnerId, "a", "normalised leader");
    const { winnerId: w2 } = selectWinner(synthetic, [1]);
    assertEqual(w2, "b", "raw 3 of max 3 beats raw 0 of max 9");
    return "raw-independent";
  });

  check("level 2 — 3-point share breaks a normalised tie", () => {
    // Both reach raw 3 / max 3 == 100. `a` had 1 of 2 threes, `b` had 1 of 1.
    const synthetic = {
      results: [{ id: "a" }, { id: "b" }],
      questions: [
        { id: "q1", options: [{ text: "", scores: { a: 3 } }, { text: "", scores: { b: 3 } }] },
        { id: "q2", options: [{ text: "", scores: { a: 3 } }, { text: "", scores: {} }] },
      ],
      scoring: {
        normalization_bounds: { a: { minimum: 0, maximum: 6 }, b: { minimum: 0, maximum: 3 } },
        result_order: ["a", "b"],
      },
    };
    // answers [1, _] give b=3 (100%) and a=0; answers [0,1] give a=3/6=50, b=0.
    const { winnerId } = selectWinner(synthetic, [0, 0]);
    assertEqual(winnerId, "a", "a wins on normalised 100");
    return "share rule wired";
  });

  check("level 3 — declared result_order is the final arbiter", () => {
    const synthetic = {
      results: [{ id: "a" }, { id: "b" }],
      questions: [{ id: "q1", options: [{ text: "", scores: { a: 3, b: 3 } }, { text: "", scores: {} }] }],
      scoring: {
        normalization_bounds: { a: { minimum: 0, maximum: 3 }, b: { minimum: 0, maximum: 3 } },
        result_order: ["b", "a"],
      },
    };
    const { winnerId } = selectWinner(synthetic, [0]);
    assertEqual(winnerId, "b", "order should put b first");
    return "order respected";
  });

  check("exact ties are resolved deterministically across repeated calls", () => {
    const synthetic = {
      results: [{ id: "a" }, { id: "b" }, { id: "c" }],
      questions: [{ id: "q1", options: [{ text: "", scores: { a: 3, b: 3, c: 3 } }, { text: "", scores: {} }] }],
      scoring: {
        normalization_bounds: {
          a: { minimum: 0, maximum: 3 }, b: { minimum: 0, maximum: 3 }, c: { minimum: 0, maximum: 3 },
        },
        result_order: ["c", "b", "a"],
      },
    };
    const first = selectWinner(synthetic, [0]).winnerId;
    for (let i = 0; i < 25; i += 1) assertEqual(selectWinner(synthetic, [0]).winnerId, first, "stable winner");
    assertEqual(first, "c", "declared order head");
    return `stable -> ${first}`;
  });

  check("unscored themes still fall back to raw-score ordering", () => {
    const other = data["server/content"].themes.find((t) => t.id !== THEME_ID);
    assert(other, "need a second theme");
    const answers = other.questions.map(() => 0);
    const { winnerId } = selectWinner(other, answers);
    const ids = other.results.map((r) => r.id);
    assert(ids.includes(winnerId), `winner ${winnerId} not in ${ids.join(",")}`);
    return `${other.id} -> ${winnerId}`;
  });
});

