describe("6. artwork wiring and missing-asset fallback", () => {
  check("front assets exist for all 12 in both deploy directories", () => {
    const missing = [];
    for (const dir of DATA_DIRS) {
      for (const id of IDS) {
        const p = join(ROOT, dir, "assets", "greek-women", `${id}-front.webp`);
        if (!existsSync(p)) missing.push(`${dir}/${id}-front.webp`);
      }
    }
    assert(missing.length === 0, `missing: ${missing.join(", ")}`);
    return "24 files";
  });

  check("front assets are 12 visually distinct files, not one duplicated image", () => {
    const seen = new Map();
    for (const id of IDS) {
      const buf = readFileSync(join(ROOT, "deploy-ready", "assets", "greek-women", `${id}-front.webp`));
      const digest = buf.length + ":" + buf.subarray(0, 4096).toString("latin1").length + ":" + buf.subarray(0, 64).toString("hex");
      if (seen.has(digest)) throw new Error(`${id} duplicates ${seen.get(digest)}`);
      seen.set(digest, id);
    }
    return "12 unique";
  });

  check("back assets exist for all 12 in both deploy directories", () => {
    const missing = [];
    for (const dir of DATA_DIRS) {
      for (const id of IDS) {
        const p = join(ROOT, dir, "assets", "greek-women", `${id}-back.webp`);
        if (!existsSync(p)) missing.push(`${dir}/${id}-back.webp`);
      }
    }
    assert(missing.length === 0, `missing: ${missing.join(", ")} (result card would fall back to symbolic art)`);
    return "24 files";
  });

  check("every back asset has a front/back pair of matching pixel dimensions", () => {
    // V2 publishes WebP (832x1040 q80). Parse the RIFF header: VP8X carries a 3-byte
    // canvas size, plain VP8 a 14-bit keyframe size. Both branches covered so a future
    // alpha/lossless re-encode cannot silently break pairing.
    const dims = (buf) => {
      if (buf.toString("latin1", 0, 4) !== "RIFF" || buf.toString("latin1", 8, 12) !== "WEBP") return "not-webp";
      const chunk = buf.toString("latin1", 12, 16);
      if (chunk === "VP8X") {
        const w = 1 + (buf[24] | (buf[25] << 8) | (buf[26] << 16));
        const h = 1 + (buf[27] | (buf[28] << 8) | (buf[29] << 16));
        return `${w}x${h}`;
      }
      if (chunk === "VP8 ") return `${buf.readUInt16LE(26) & 0x3fff}x${buf.readUInt16LE(28) & 0x3fff}`;
      return "unknown-chunk";
    };
    const problems = [];
    for (const id of IDS) {
      const front = readFileSync(join(ROOT, "deploy-ready", "assets", "greek-women", `${id}-front.webp`));
      const back = readFileSync(join(ROOT, "deploy-ready", "assets", "greek-women", `${id}-back.webp`));
      if (dims(front) !== dims(back)) problems.push(`${id}: ${dims(front)} vs ${dims(back)}`);
      if (front.equals(back)) problems.push(`${id}: front and back are the same file`);
    }
    assert(problems.length === 0, problems.join("; "));
    const sample = readFileSync(join(ROOT, "deploy-ready", "assets", "greek-women", "hera-front.webp"));
    return `all pairs ${dims(sample)}`;
  });

  check("the renderer points at the <id>-front / <id>-back convention", () => {
    assert(/\$\{base\}-\$\{side\}\.webp/.test(appSource), "art path template missing");
    assert(/assets\/\$\{state\.theme/.test(appSource), "asset base should be theme-scoped");
    assert(/face\("front"/.test(appSource) && /face\("back"/.test(appSource), "front/back faces not both rendered");
    return "assets/<theme>/<id>-{front,back}.webp";
  });

  check("each card face carries exactly the four reference blocks", () => {
    // `hecate-flip-card.html` / `athena-double-card-test-v2.html` put only
    // art + eyebrow(name) + h2(title) + reading on a face. subtitle/tags/share are
    // display:none there, and 神话线索 is not in the card body at all.
    const face = appSource.match(/function renderResultFace[\s\S]*?\n}/);
    const art = appSource.match(/function renderResultArt[\s\S]*?\n}/);
    assert(face && art, "renderResultFace / renderResultArt not found");
    const combined = face[0] + art[0];
    for (const marker of ["class=\"art\"", "class=\"eyebrow\"", "class=\"reading\"", "<h2>"]) {
      assert(combined.includes(marker), `result card markup missing ${marker}`);
    }
    assert(!/class="tags"/.test(face[0]), "tags must not be rendered onto the card face");
    assert(!/class="share"/.test(face[0]), "share line must not be rendered onto the card face");
    assert(!/<details>/.test(face[0]), "神话线索 must not be rendered onto the card face");
    // Both faces come from the same renderer, so neither can drift.
    assert(/renderResultFace\(result, presentation\.englishName, art\.front, "front"/.test(appSource), "front face not rendered");
    assert(/renderResultFace\(result, presentation\.englishName, art\.back, "back"/.test(appSource), "back face not rendered");
    return "art + eyebrow + h2 + reading only, on both faces";
  });

  check("the two faces use different copy from the data", () => {
    const missing = [];
    for (const result of theme.results) {
      for (const field of ["back_subtitle", "back_reading"]) {
        if (!result[field] || !String(result[field]).trim()) missing.push(`${result.id}.${field}`);
      }
      if (result.back_subtitle === result.subtitle) missing.push(`${result.id}: back title repeats the front`);
      if (result.back_reading === result.reading) missing.push(`${result.id}: back reading repeats the front`);
    }
    assert(missing.length === 0, missing.join(", "));
    // The renderer must actually consume them, with a safe fallback.
    assert(/result\.back_subtitle \|\| frontSubtitle/.test(appSource), "back_subtitle not read with a fallback");
    assert(/result\.back_reading \|\| frontReading/.test(appSource), "back_reading not read with a fallback");
    return `12 x (back_subtitle, back_reading)`;
  });

  check("a failed artwork degrades to the symbolic art, not a broken image", () => {
    assert(/addEventListener\("error"/.test(appSource), "no error handler bound to artwork images");
    assert(/art-missing/.test(appSource) && /art-missing/.test(cssSource), "missing-art class not wired in both js and css");
    assert(/data-art-fallback/.test(appSource) && /\.flip-fallback/.test(cssSource), "fallback not wired");
    assert(/face\.querySelector\("\[data-art-fallback\]"\)/.test(appSource), "fallback lookup should be scoped to the face");
    return "onerror -> .art-missing (face-scoped)";
  });

  check("the card starts on the front, is keyboard operable, and rotates per face", () => {
    assert(!/data-face="front"/.test(appSource), "state should live on .is-back, not a data-face attribute");
    assert(/classList\.toggle\("is-back"\)/.test(appSource), "flip should toggle .is-back");
    assert(/role="button" tabindex="0"/.test(appSource), "card should be a keyboard-reachable button");
    assert(/event\.key === "Enter"/.test(appSource) && /event\.key === " "/.test(appSource), "Enter/Space not handled");
    assert(/backface-visibility: hidden/.test(cssSource), "backface-visibility missing");
    // Both faces are absolute, so the card needs its own height or the page collapses.
    assert(/\.flip-card \{[^}]*min-height: 720px/.test(cssSource.replace(/\n/g, " ")), "card needs min-height to avoid collapsing");
    // Each face rotates; the parent must not.
    assert(/\.flip-card\.is-back \.front \{ transform: rotateY\(-180deg\)/.test(cssSource), "front face not rotated");
    assert(/\.flip-card\.is-back \.back \{ transform: rotateY\(0deg\)/.test(cssSource), "back face not rotated");
    assert(/prefers-reduced-motion/.test(cssSource), "no reduced-motion guard for the flip");
    return "is-back + Enter/Space + min-height + per-face rotation";
  });

  check("artwork keeps a 4:5 frame so the card cannot jump on load", () => {
    assert(/\.flip-card \.art \{[^}]*aspect-ratio: 4 \/ 5/.test(cssSource), "the art frame should reserve 4:5");
    return "aspect-ratio 4/5 on the art frame";
  });

  check("flip-card classes do not collide with any pre-existing stylesheet rule", () => {
    // Regression guard. The first version of the flip card reused `.art-card`, which was
    // already the Aphrodite symbolic-art invitation card:
    //   .art-card { width:150px; height:92px; transform:rotate(-7deg); ... }
    // The whole result card inherited it and rendered as a thin tilted sliver.
    // Every class the flip card owns must be defined ONLY inside the flip-card block.
    const marker = cssSource.indexOf("双面结果卡");
    assert(marker > 0, "flip-card section marker comment missing");
    const beforeBlock = cssSource.slice(0, marker);
    const inBlock = cssSource.slice(marker);

    const owned = [".flip-card", ".flip-fallback", ".flip-card .face", ".flip-card .art"];
    const problems = [];
    for (const selector of owned) {
      const escaped = selector.replace(/\./g, "\\.").replace(/ /g, "\\s+");
      const re = new RegExp(`(^|[\\s,])${escaped}(?![\\w-])`, "g");
      const leaks = (beforeBlock.match(re) || []).length;
      if (leaks) problems.push(`${selector}: ${leaks} definition(s) before the flip-card block`);
      if (!(inBlock.match(re) || []).length) problems.push(`${selector}: never styled in the flip-card block`);
    }

