   The greek-women theme ships real front portraits at
   assets/greek-women/<id>-front.png and reverse artworks at <id>-back.png.
   Any other theme (and any missing file) falls back to the inline symbolic art,
   so a model outage or a renamed asset degrades instead of showing a blank card.
-------------------------------------------------------------------------------- */

function resultAssetBase(resultId) {
  return `assets/${state.theme || "generic"}/${resultId}`;
}

function hasArtwork(theme, resultId) {
