// `document` is absent when this file is loaded from Node for tests; the
// DOM is only ever touched from render/bind functions, which tests do not call.
const app = typeof document !== "undefined" && document.querySelector ? document.querySelector("#app") : null;
let quizData = null;
let themes = [];
let state = { theme: null, quiz: null, index: 0, answers: [], skin: null };

/* -------------------------------------------------- one test, one URL ----
   每个测试产品有自己的网址 /t/<product_id>；本页从 URL 解析当前产品，
   只载入该产品的主题。单主题产品直接进封面页（标题 + 开始），
   多主题产品（未来的 bundle）才显示该产品内的主题列表。
   URL 本身不承载解锁状态：解锁凭证在 localStorage + 服务端绑定里。  */
const DEFAULT_TEST_ID = "greek_goddess";

function currentTestId() {
  try {
    const match = String(location.pathname || "").match(/^\/t\/([a-z0-9_-]+)/i);
    if (match) return match[1].toLowerCase();
    const query = new URLSearchParams(location.search || "").get("test_id");
    if (query) return String(query).toLowerCase();
  } catch (error) { /* no location in some environments */ }
  return DEFAULT_TEST_ID;
}

/* ------------------------------------------------ product visual layer ----
   公共层只负责功能：license、路由、题库、评分、基本导航。每个测试的艺术
   表达是可选的 themes/<test_id>/ 皮肤包：只有当 themes/<test_id>/skin.json
   存在（HEAD 探测）才加载 skin.js 与 skin.css；没有皮肤的产品（如
   greek_goddess）不会加载任何额外文件，走下方默认模板，渲染路径一字不改。
   皮肤通过 views.<page>(ctx) 接管某个页面的表达，返回 {html, bind}；
   ctx 只暴露功能回调（验帖、选项、翻页、重测），评分与题库不进入皮肤。 */
const SKIN_PAGES = ["gate", "cover", "question", "resultLoading", "result"];

function presetSkins() {
  return (typeof globalThis !== "undefined" && globalThis.__MYTHIC_SKINS__) || null;
}

function injectSkinStylesheet(testId) {
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = `themes/${testId}/skin.css`;
  document.head.appendChild(link);
}

function adoptSkin(skin) {
  if (skin && skin.title && typeof document !== "undefined") document.title = skin.title;
  return skin || null;
}

async function loadSkin(testId) {
  const preset = presetSkins();
  if (preset && preset[testId]) return adoptSkin(preset[testId]);
  if (typeof document === "undefined") return null;
  try {
    // HEAD 探测：皮肤不存在时安静返回，不给无皮肤的产品留下控制台报错。
    const probe = await fetch(`themes/${encodeURIComponent(testId)}/skin.json`, { method: "HEAD" });
    if (!probe.ok) return null;
    const module = await import(`./themes/${encodeURIComponent(testId)}/skin.js`);
    const skin = module && module.default;
    if (!skin || skin.id !== testId || !skin.views) return null;
    injectSkinStylesheet(testId);
    return adoptSkin(skin);
  } catch (error) {
    return null; // 该产品没有皮肤
  }
}

// 皮肤接管了该页面则返回 true。皮肤页面自带 chrome（顶栏属于表达的一部分），
// 所以这里直接写 #app 并标记 body[data-skin]；默认 shell() 会摘掉该标记，
// 保证皮肤未接管的页面（或无皮肤的产品）永远使用默认模板的样式。
function trySkinView(name, ctx) {
  const skin = state.skin;
  if (!skin || !skin.views || typeof skin.views[name] !== "function") return false;
  const view = skin.views[name](ctx);
  const html = view && typeof view.html === "string" ? view.html : "";
  if (!html) return false;
  app.innerHTML = html;
  document.body.setAttribute("data-skin", skin.id || state.testId);
  if (view && typeof view.bind === "function") view.bind(app, ctx);
  return true;
}

/* 皮肤回调上下文：一页一个，只给功能不给表达。返回值语义化，皮肤自行决定
   如何呈现错误与归属提示；引擎的默认渲染函数在开头问一次 trySkinView。 */
function gateContext(message) {
  return {
    message: message || "",
    async submit(rawCode) {
      const code = String(rawCode || "").trim();
      if (!code) return { type: "error", kind: "empty" };
      const stored = getLicense();
      const result = await api("/api/redeem", {
        code, secret: stored ? stored.secret : null, fingerprint: deviceFingerprint()
      });
      if (result.ok && result.data.ok && result.data.secret) {
        saveLicense({ code, secret: result.data.secret });
        if (result.data.product_id !== state.testId) {
          return { type: "other-product", name: result.data.product_name || result.data.product_id };
        }
        loadContent();
        return { type: "unlocked" };
      }
      if (result.data.error === "already_bound") return { type: "error", kind: "already_bound" };
      if (result.data.error === "rate_limited") return { type: "error", kind: "rate_limited" };
      return { type: "error", kind: "invalid" };
    },
  };
}

function coverContext(theme) {
  return {
    productName: state.productName || "MYTHIC",
    theme: { id: theme.id, title: theme.title, subtitle: theme.subtitle },
    start: () => start(theme.id),
  };
}

function questionContext() {
  const q = state.quiz.questions[state.index];
  const advance = () => {
    if (state.index + 1 < state.quiz.questions.length) {
      state.index += 1;
      renderQuestion();
    } else {
      renderResult();
    }
  };
  return {
    question: q.question,
    options: (q.options || []).map((option) => option.text),
    index: state.index,
    total: state.quiz.questions.length,
    selected: state.answers[state.index],
    select(optionIndex) {
      state.answers[state.index] = optionIndex;
      advance();
    },
    next() {
      if (state.answers[state.index] === undefined) return;
      advance();
    },
    previous() {
      if (state.index > 0) {
        state.index -= 1;
        renderQuestion();
      }
    },
    exit() { home(); },
  };
}

function resultLoadingContext() {
  return { productName: state.productName || "MYTHIC" };
}

function resultContext(result) {
  return {
    result,
    productName: state.productName || "MYTHIC",
    themeTitle: state.quiz ? state.quiz.title : "",
    disclaimer: state.quiz ? state.quiz.disclaimer : "",
    actions: {
      again: () => start(state.theme),
      home: () => home(),
      copy: () => copyResult(result, state.skin && state.skin.copyText ? state.skin.copyText(result) : undefined),
      share: () => {
        if (state.skin && typeof state.skin.share === "function") {
          return state.skin.share({ result, productName: state.productName || "MYTHIC", theme: state.theme });
        }
        shareResult(result, getResultPresentation(result).symbol);
      },
    },
  };
}

/* ------------------------------------------------------- license gate ----
   付费兑换码 + 设备绑定。浏览器只保存 {code, secret}（localStorage）；
   评分与判定全部在服务端完成，前端拿到的内容不含任何权重矩阵，
   结果数据也只在答完后才返回、且只返回命中的那一条。
   门还做产品匹配：A 测试的码在 B 测试页面激活时提示归属，不解绑。    */
const LICENSE_KEY = "[REDACTED:SECRET_ASSIGNMENT]";

function getLicense() {
  try { return JSON.parse(localStorage.getItem(LICENSE_KEY) || "null"); } catch (error) { return null; }
}
function saveLicense(license) {
  try { localStorage.setItem(LICENSE_KEY, JSON.stringify(license)); } catch (error) { /* private mode */ }
}
function clearLicense() {
  try { localStorage.removeItem(LICENSE_KEY); } catch (error) { /* ignore */ }
}

// 辅助指纹：只用于服务端记录不一致次数，从不作为拦截条件。
function deviceFingerprint() {
  const parts = [
    typeof navigator !== "undefined" ? navigator.userAgent || "" : "",
    typeof navigator !== "undefined" ? navigator.language || "" : "",
    typeof screen !== "undefined" && screen ? `${screen.width}x${screen.height}x${screen.colorDepth}` : "",
    typeof Intl !== "undefined" && Intl.DateTimeFormat ? Intl.DateTimeFormat().resolvedOptions().timeZone || "" : "",
    typeof navigator !== "undefined" ? navigator.platform || "" : "",
  ];
  return parts.join("|");
}

async function api(path, body) {
  const response = await fetch(path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body || {})
  });
  let data = {};
  try { data = await response.json(); } catch (error) { /* non-json error body */ }
  return { ok: response.ok, status: response.status, data };
}

async function initApp() {
  state.testId = currentTestId();
  state.skin = await loadSkin(state.testId);
  const stored = getLicense();
  if (stored && stored.code && stored.secret) {
    const verified = await api("/api/verify-license", {
      code: stored.code, secret: stored.secret, fingerprint: deviceFingerprint()
    });
    if (verified.ok && verified.data.ok) {
      // 绑定有效，但码属于另一个测试：保留凭证，本页仍上锁并说明归属。
      if (verified.data.product_id !== state.testId) {
        return renderGate(`该兑换码属于《${verified.data.product_name || verified.data.product_id}》测试，请打开对应网址使用。`);
      }
      return loadContent();
    }
    clearLicense();
  }
  renderGate();
}

function renderGate(message) {
  if (trySkinView("gate", gateContext(message))) return;
  shell(`<section class="hero gate-hero"><div class="eyebrow">Redeem</div><h1>输入兑换码</h1><p class="lead">激活后与当前浏览器绑定，之后打开页面即可直接进入。</p><div class="gate-form"><input id="gate-code" class="gate-input" type="text" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码"><button class="primary" id="gate-submit">激活</button></div><p class="gate-error" id="gate-error" role="alert">${message || ""}</p><p class="notice">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需要重新激活，届时可联系卖家重置绑定。</p></section>`, "Redeem");
  const input = document.querySelector("#gate-code");
  const submit = document.querySelector("#gate-submit");
  const showError = (text) => { const el = document.querySelector("#gate-error"); if (el) el.textContent = text; };
  const run = async () => {
    const code = (input.value || "").trim();
    if (!code) { showError("请输入兑换码。"); return; }
    submit.disabled = true;
    submit.textContent = "验证中…";
    const stored = getLicense();
    const result = await api("/api/redeem", { code, secret: stored ? stored.secret : null, fingerprint: deviceFingerprint() });
    submit.disabled = false;
    submit.textContent = "激活";
    if (result.ok && result.data.ok && result.data.secret) {
      saveLicense({ code, secret: result.data.secret });
      if (result.data.product_id !== state.testId) {
        return showError(`该兑换码属于《${result.data.product_name || result.data.product_id}》测试，已在本浏览器激活；请打开对应网址使用。`);
      }
      return loadContent();
    }
    if (result.data.error === "already_bound") showError("该兑换码已在其他设备激活。如需换设备，请联系卖家重置绑定。");
    else if (result.data.error === "rate_limited") showError("尝试过于频繁，请一分钟后再试。");
    else showError("兑换码无效，请检查后重新输入。");
  };
  submit.onclick = run;
  input.onkeydown = (event) => { if (event.key === "Enter") { event.preventDefault(); run(); } };
}

async function loadContent() {
  try {
    const response = await fetch(`/api/content?test_id=${encodeURIComponent(state.testId)}`);
    if (response.status === 404) {
      shell(`<section class="hero"><h2>测试不存在</h2><p class="lead">这个网址没有对应的测试，可能已下线或拼写有误。</p></section>`);
      return;
    }
    if (!response.ok) throw new Error(`content ${response.status}`);
    quizData = await response.json();
    state.productName = (quizData.product && quizData.product.name) || state.testId;
    themes = (quizData.themes || []).map((t) => ({
      id: t.id,
      title: t.title,
      subtitle: t.subtitle || t.description || "",
      source: "/api/content"
    }));
    home();
  } catch (error) {
    console.error("Failed to load quiz data:", error);
    shell(`<section class="hero"><h2>无法载入题库</h2><p class="lead">服务暂时不可用，请稍后刷新重试。</p></section>`);
  }
}

function shell(content, right = "原创互动测试") {
  const theme = state.theme || "";
  app.innerHTML = `<div class="topbar"><span class="brand">MYTHIC / 01</span><span>${right}</span></div><div class="shell" data-theme="${theme}">${content}</div>`;
  // Apply theme to body for CSS variable scope
  document.body.setAttribute("data-theme", theme);
  document.body.removeAttribute("data-skin"); // 默认模板页面不携带任何皮肤样式
}

function home() {
  // 一个测试一个网址：单主题产品直接进封面页；多主题产品（bundle）
  // 才列出该产品自己的主题——不再是全站九宫格。
  if (themes.length === 1) return cover(themes[0]);
  shell(`<section class="hero"><div class="eyebrow">A small ritual for self-discovery</div><h1>选择一个<br>故事主题。</h1><p class="lead">${state.productName || "本合集"}内包含 ${themes.length} 个测试。</p></section><section class="grid">${themes.map((t, i) => `<button class="theme-card" data-theme="${t.id}"><span class="count">0${String(i + 1).padStart(2, "0")}</span><div class="eyebrow">choose</div><h3>${t.title}</h3><p>${t.subtitle}</p></button>`).join("")}</section><p class="notice">这些测试是原创的象征性娱乐内容，不是心理诊断。</p>`);
  document.querySelectorAll(".theme-card[data-theme]").forEach((el) => {
    el.addEventListener("click", (event) => {
      event.stopPropagation();
      start(el.dataset.theme);
    });
  });
}

function cover(theme) {
  if (trySkinView("cover", coverContext(theme))) return;
  shell(`<section class="hero cover-hero"><div class="eyebrow">${state.productName || "MYTHIC TEST"}</div><h1>${theme.title}</h1><p class="lead">${theme.subtitle}</p><div class="cover-actions"><button class="primary" id="cover-start">开始测试</button></div><p class="notice">这是原创的象征性娱乐内容，不是心理诊断。完成后可翻面查看结果卡的另一刻。</p></section>`, state.productName || "MYTHIC TEST");
  document.querySelector("#cover-start").onclick = () => start(theme.id);
}

async function start(id) {
  state = { theme: id, quiz: null, index: 0, answers: [] };
  if (!quizData) return home();

  const themeData = quizData.themes.find((t) => t.id === id);
  if (!themeData) return home();

  state.quiz = {
    id: themeData.id,
    title: themeData.title,
    subtitle: themeData.subtitle || "",
    description: themeData.description || "",
    disclaimer: themeData.disclaimer || "这是一份象征性的娱乐测试。",
    questions: themeData.questions || [],
    results: themeData.results || [],
    scoring: themeData.scoring || null
  };

  renderQuestion();
}

function renderQuestion() {
  if (!state.quiz || state.index >= state.quiz.questions.length) {
    return renderResult();
  }

  const q = state.quiz.questions[state.index];
  const progress = Math.round(((state.index + 1) / state.quiz.questions.length) * 100);
  const selectedAnswer = state.answers[state.index];

  const optionsHtml = (q.options || []).map((o, i) => 
    `<button class="option${selectedAnswer === i ? " selected" : ""}" data-answer="${i}" aria-pressed="${selectedAnswer === i}"><b>${String.fromCharCode(65 + i)}</b><span>${o.text}</span></button>`
  ).join("");

  shell(`<div class="progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${state.quiz.questions.length}" aria-valuenow="${state.index + 1}"><i style="width:${progress}%"></i></div><div class="question-number">QUESTION ${String(state.index + 1).padStart(2, "0")} / ${state.quiz.questions.length}</div><div class="question">${q.question}</div><div class="options">${optionsHtml}</div><div class="question-actions"><button class="secondary icon-button" id="previous"${state.index === 0 ? " disabled" : ""} aria-label="上一题" title="上一题">←</button><button class="primary icon-button" id="next"${selectedAnswer === undefined ? " disabled" : ""} aria-label="${state.index + 1 === state.quiz.questions.length ? "查看结果" : "下一题"}" title="${state.index + 1 === state.quiz.questions.length ? "查看结果" : "下一题"}">→</button></div><button class="back" id="back">← 返回主题</button>`, `0${String(state.index + 1).padStart(2, "0")} / ${state.quiz.questions.length}`);

  document.querySelectorAll("[data-answer]").forEach((el) => {
    el.addEventListener("click", () => {
      state.answers[state.index] = Number(el.dataset.answer);
      if (state.index + 1 < state.quiz.questions.length) {
        state.index += 1;
        renderQuestion();
      } else {
        renderResult();
      }
    });
  });

  document.querySelector("#previous").onclick = () => {
    if (state.index > 0) {
      state.index -= 1;
      renderQuestion();
    }
  };
  document.querySelector("#next").onclick = () => {
    if (state.answers[state.index] === undefined) return;
    if (state.index + 1 < state.quiz.questions.length) {
      state.index += 1;
      renderQuestion();
    } else {
      renderResult();
    }
  };
  document.querySelector("#back").onclick = home;
}

/* --------------------------------------------------------- server scoring ----
   \u8bc4\u5206\u3001\u6743\u91cd\u4e0e\u7ed3\u679c\u5224\u5b9a\u5168\u90e8\u5728\u670d\u52a1\u7aef\uff1a\u8fd9\u91cc\u53ea\u63d0\u4ea4\u7b54\u6848\u7d22\u5f15\uff0c\u63a5\u6536\u547d\u4e2d\u7684\u90a3\u4e00\u6761
   \u7ed3\u679c\u3002\u524d\u7aef bundle \u4e0d\u542b\u4efb\u4f55\u6253\u5206\u903b\u8f91\u6216\u77e9\u9635\uff08/api/content \u5df2\u5265\u79bb scores\u3001
   scoring \u4e0e\u5168\u90e8\u7ed3\u679c\u6b63\u6587\uff09\u3002                                              */

async function renderResult() {
  if (!state.quiz) return home();
  const license = getLicense() || {};
  shell(`<section class="hero result-hero"><div class="eyebrow">\u4f60\u7684\u7ed3\u679c</div><div class="result-loading"><h2>\u6b63\u5728\u751f\u6210\u4f60\u7684\u7ed3\u679c\u2026</h2><p class="lead">\u5224\u5b9a\u5728\u670d\u52a1\u7aef\u5b8c\u6210\u3002</p></div></section>`, "Result");
  let payload = null;
  try {
    const response = await fetch("/api/score", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ theme: state.theme, answers: state.answers, code: license.code, secret: license.secret, test_id: state.testId })
    });
    const body = await response.json();
    if (!response.ok || !body.result) throw new Error(body.error || `score ${response.status}`);
    payload = body;
  } catch (error) {
    console.error("score failed:", error);
    shell(`<section class="hero"><h2>\u7ed3\u679c\u751f\u6210\u5931\u8d25</h2><p class="lead">\u7f51\u7edc\u6216\u670d\u52a1\u6682\u65f6\u4e0d\u53ef\u7528\u3002\u4f60\u7684\u7b54\u6848\u4ecd\u5728\u672c\u9875\uff0c\u53ef\u76f4\u63a5\u91cd\u8bd5\u3002</p><div class="actions"><button class="primary" id="retry">\u91cd\u8bd5</button><button class="back" id="home">\u8fd4\u56de\u4e3b\u9898\u9009\u62e9</button></div></section>`);
    document.querySelector("#retry").onclick = () => renderResult();
    document.querySelector("#home").onclick = home;
    return;
  }
  const result = payload.result;
  const presentation = getResultPresentation(result);
  const art = renderResultArt(result.id);
  shell(`<section class="hero result-hero"><div class="eyebrow">\u4f60\u7684\u7ed3\u679c</div>${renderResultCard(result, presentation, art)}<p class="small result-disclaimer">${state.quiz.disclaimer}</p><div class="actions"><button class="primary" id="share">\u751f\u6210\u5206\u4eab\u56fe</button><button class="secondary" id="copy">\u590d\u5236\u7ed3\u679c\u6587\u6848</button><button class="secondary" id="again">\u518d\u6d4b\u4e00\u6b21</button><button class="back" id="home">\u8fd4\u56de\u4e3b\u9898\u9009\u62e9</button></div></section>`);
  document.querySelector("#again").onclick = () => start(state.theme);
  document.querySelector("#share").onclick = () => shareResult(result, presentation.symbol);
  document.querySelector("#copy").onclick = () => copyResult(result);
  document.querySelector("#home").onclick = home;
  bindResultCard();
}

const greekNames = {
  athena: "Athena", aphrodite: "Aphrodite", artemis: "Artemis", hecate: "Hecate",
  persephone: "Persephone", demeter: "Demeter", medea: "Medea", atalanta: "Atalanta",
  hera: "Hera", hestia: "Hestia", nike: "Nike", circe: "Circe"
};

function getResultPresentation(result) {
  return {
    englishName: result.english_name || result.greek_name || greekNames[result.id] || "",
    symbol: result.name ? result.name.charAt(0) : "\u2726",
    title: result.subtitle || result.core_energy || "\u4e00\u6bb5\u5c5e\u4e8e\u6b64\u523b\u7684\u8c61\u5f81\u6027\u9605\u8bfb",
    reading: result.reading || result.description || ""
  };
}

// 结果卡正文，严格照 `hecate-flip-card.html` / `athena-double-card-test-v2.html`：
//   艺术图（4:5）→ 姓名（+ 英文名）→ 一行标题（h2）→ 一段正文
// 参照页把 subtitle / tags / share 都设了 display:none，卡片上不显示关键词、分享短句，
// 「神话线索」也不进卡片主体 —— 所以这里只渲染这四块，其余字段留在数据里备用。
function renderResultFace(result, englishName, artMarkup, faceClass, subtitle, reading) {
  return `<section class="face ${faceClass}">${artMarkup}<div class="body"><div class="eyebrow">${result.name || "\u6b64\u523b\u7684\u4f60"}${englishName ? `<small>${englishName}</small>` : ""}</div><h2>${subtitle || ""}</h2><p class="reading">${reading || ""}</p></div></section>`;
}

function renderResultCard(result, presentation, art) {
  const id = result.id || "generic";
  const frontSubtitle = result.subtitle || result.core_energy || "";
  const frontReading = result.reading || result.description || "";
  // 背面用独立文案；缺失时退回正面文案，卡片结构不会因此破掉。
  const backSubtitle = result.back_subtitle || frontSubtitle;
  const backReading = result.back_reading || frontReading;

  if (!art) {
    // Themes without artwork keep the plain single-panel card.
    return `<article class="result-panel result-card result-${id}" data-result-id="${id}">${renderResultFace(result, presentation.englishName, "", "face-front", frontSubtitle, frontReading)}</article>`;
  }
  return `<div class="scene"><article class="result-panel result-card flip-card result-${id}" data-result-id="${id}" data-result-art="${id}" role="button" tabindex="0" aria-label="\u7ffb\u8f6c${result.name || ""}\u7ed3\u679c\u5361">${renderResultFace(result, presentation.englishName, art.front, "front", frontSubtitle, frontReading)}${renderResultFace(result, presentation.englishName, art.back, "back", backSubtitle, backReading)}</article></div>`;
}

/* ------------------------------------------------------- result-card artwork ----
   The greek-women theme ships real front portraits at
   assets/greek-women/<id>-front.png and reverse artworks at <id>-back.png.
   Any other theme (and any missing file) falls back to the inline symbolic art,
   so a model outage or a renamed asset degrades instead of showing a blank card.
-------------------------------------------------------------------------------- */

function resultAssetBase(resultId) {
  return `assets/${state.theme || "generic"}/${resultId}`;
}

function hasArtwork(theme, resultId) {
  return theme === "greek-women" && Boolean(resultId);
}

function renderFallbackArt(resultId) {
  return `<div class="visual-art visual-art-fallback visual-art-fallback-${resultId || "generic"}" aria-label="Symbolic result art"><span>${resultId ? resultId.charAt(0).toUpperCase() : "\u2726"}</span></div>`;
}

function visualArtFor(resultId, visualDirection = "") {
  return VISUAL_ART[resultId] ? VISUAL_ART[resultId].trim() : renderFallbackArt(resultId);
}

// Returns null when the theme has no artwork, so the caller can render a plain card.
function renderResultArt(resultId) {
  if (!hasArtwork(state.theme, resultId)) return null;
  const base = resultAssetBase(resultId);
  const fallback = renderFallbackArt(resultId);
  const face = (side, label) => `<figure class="art"><img src="${base}-${side}.webp" alt="${label}" draggable="false" decoding="async" data-art><div class="flip-fallback" data-art-fallback hidden>${fallback}</div></figure>`;
  return {
    front: face("front", `${resultId} 正面艺术图`),
    back: face("back", `${resultId} 背面艺术图`)
  };
}
