function bindResultCard() {
  // A missing artwork must degrade to the symbolic art, never to a broken image.
  // Each face owns its own image and its own fallback, so scoping the lookup to the
  // enclosing .face keeps the front and back fallbacks independent.
  document.querySelectorAll("[data-art]").forEach((img) => {
    img.addEventListener("error", () => {
      const face = img.closest(".face");
      if (!face) return;
      face.classList.add("art-missing");
      img.remove();
      const fallback = face.querySelector("[data-art-fallback]");
      if (fallback) fallback.hidden = false;
    });
  });

  // 整张卡点击翻面（与参照页一致），并支持 Enter / 空格。
  // 正反面各自独立旋转，不旋转父容器，所以背面文字不会镜像。
  const card = document.querySelector("[data-result-art]");
  if (!card) return;
  const frontFace = card.querySelector(".front");
  const backFace = card.querySelector(".back");

  /* ------------------------------------------------- card motion（V2 CARD_MOTION）----
     卡是物理收藏品：落卡、倾角、探视、升力、按压，全部是物体动作。
     动效只负责教会「翻面」这一件事：3 秒无触碰探视一次，7.5 秒再一次，
     之后永远安静。prefers-reduced-motion 时只保留提示文案，不做任何位移。
     邀请计时器只在真实浏览器（有 matchMedia）里排程 —— 无头测试桩没有
     matchMedia，因此不会挂起测试进程；每面的提示元素在运行时插入，
     不进 renderResult 的模板字符串，卡面四块结构保持不变。                        */
  const media = typeof window.matchMedia === "function" ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
  const reduceMotion = Boolean(media && media.matches);
  if (Array.isArray(window.__cardMotionTimers)) window.__cardMotionTimers.forEach(window.clearTimeout);
  window.__cardMotionTimers = [];
  const timers = window.__cardMotionTimers;

  if (!reduceMotion) {
    card.classList.add("card-arrive");
    card.addEventListener("animationend", function onArrive(event) {
      if (event.animationName !== "card-arrive") return;
      card.classList.remove("card-arrive");
      card.removeEventListener("animationend", onArrive);
    });
  }

  // 提示文案已按反馈移除：探视动作本身就是翻面的可供性说明，不再加字。
  let touched = false;
  const quietInvite = () => {
    touched = true;
    timers.forEach(window.clearTimeout);
  };

  if (media && !reduceMotion) {
    timers.push(window.setTimeout(() => {
      if (touched || !card.isConnected) return;
      card.classList.add("card-peek-1");
    }, 3000));
    timers.push(window.setTimeout(() => {
      if (touched || !card.isConnected) return;
      card.classList.remove("card-peek-1");
      card.classList.add("card-peek-2");
    }, 7500));
  }

  const toggle = () => {
    const isBack = card.classList.toggle("is-back");
    card.setAttribute("aria-pressed", String(isBack));
    card.setAttribute("aria-label", isBack ? "返回结果卡正面" : "翻转结果卡");
    if (frontFace) frontFace.setAttribute("aria-hidden", String(isBack));
    if (backFace) backFace.setAttribute("aria-hidden", String(!isBack));
    if (!touched) quietInvite();
    card.classList.remove("card-peek-1");
    card.classList.remove("card-peek-2");
    card.classList.remove("is-flipping");
    void card.offsetWidth; // 连续翻面时让升力动画各自重新起步
    if (!reduceMotion) card.classList.add("is-flipping");
  };
  card.onclick = toggle;
  card.onkeydown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      toggle();
    }
  };
}

async function copyResult(result, textOverride) {
  const text = textOverride || `${result.name || "我的结果"}\n${result.share_line || result.reading || ""}\n\n来自 MYTHIC 原创互动测试`;
  const button = document.querySelector("#copy");
  try {
    await navigator.clipboard.writeText(text);
    button.textContent = "已复制";
  } catch (error) {
    console.error("Failed to copy result:", error);
    button.textContent = "请手动复制";
  }
  window.setTimeout(() => { button.textContent = "复制结果文案"; }, 1800);
}

function shareResult(result, symbol) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;

  const ctx = canvas.getContext("2d");

  // 背景颜色 - 根据主题选择
  const bgColors = {
    "greek-women": "#F2F1E8",
    "grand-view-garden": "#F5EEF2",
    "little-women": "#F7F0E5",
    "pride-prejudice": "#EDF1ED",
    "liaozhai-women": "#102C2C",
    "jane-eyre": "#EEF0F2",
    "peony-pavilion": "#FBF0ED",
    "secret-garden": "#EEF2E7",
    "urban-relations": "#27212A",
    "eileen-chang-city": "#27212A"
  };

  const bgColor = bgColors[state.theme] || "#F6F2EB";
  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, 900, 1200);

  // 文字颜色
  const isDarkTheme = state.theme === "liaozhai-women"
    || state.theme === "urban-relations"
    || state.theme === "eileen-chang-city";
  const textColor = isDarkTheme ? "#F4F0E6" : "#29252A";
  const accentColor = isDarkTheme ? "#E5C78D" : "#5B414C";

  // 头部
  ctx.fillStyle = accentColor;
  ctx.font = "28px sans-serif";
  ctx.fillText("MYTHIC", 70, 90);

  // 结果符号圆圈
  ctx.strokeStyle = accentColor;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(450, 350, 120, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = textColor;
  ctx.font = "bold 80px serif";
  ctx.textAlign = "center";
  ctx.fillText(symbol, 450, 390);

  // 结果名称
  ctx.font = "60px serif";
  ctx.fillText(result.name || "", 450, 580);

  // 副标题
  ctx.font = "26px sans-serif";
  ctx.fillStyle = accentColor;
  ctx.fillText(result.subtitle || result.core_energy || "", 450, 650);

  // 关键词
  ctx.font = "20px sans-serif";
  ctx.fillStyle = textColor;
  const keywords = (result.keywords || []).slice(0, 3).join(" · ");
  ctx.fillText(keywords, 450, 720);

  // 分享短句
  ctx.font = "24px sans-serif";
  const shareLine = result.share_line || "";
  wrapText(ctx, shareLine, 450, 820, 700, 40, textColor);

  // 底部文案
  ctx.font = "18px sans-serif";
  ctx.fillStyle = accentColor;
  ctx.fillText("原创互动测试 · MYTHIC", 450, 1100);

  ctx.fillStyle = textColor;
  ctx.font = "16px sans-serif";
  ctx.fillText("一份象征性的娱乐解读", 450, 1140);

  canvas.toBlob((blob) => {
    if (!blob) {
      console.error("Failed to create result image.");
      return;
    }
    const link = document.createElement("a");
    link.download = `mythic-${state.theme}-${result.id || "result"}.png`;
    link.href = URL.createObjectURL(blob);
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }, "image/png");
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight, color) {
  ctx.fillStyle = color;
  let line = "";
  for (const char of text) {
    const test = line + char;
    if (ctx.measureText(test).width > maxWidth) {
      ctx.fillText(line, x, y);
      line = char;
      y += lineHeight;
    } else {
      line = test;
    }
  }
  ctx.fillText(line, x, y);
}

