};


function bindResultCard() {
  // A missing artwork must degrade to the symbolic art, never to a broken image.
  // Each face owns its own image and its own fallback, so scoping the lookup to the
  // enclosing .face keeps the front and back fallbacks independent.
  document.querySelectorAll("[data-art]").forEach((img) => {
    img.addEventListener("error", () => {
      const face = img.closest(".face");
      if (!face) return;
      face.classList.add("art-missing");
      img.remove();
      const fallback = face.querySelector("[data-art-fallback]");
      if (fallback) fallback.hidden = false;
    });
  });

  // 整张卡点击翻面（与参照页一致），并支持 Enter / 空格。
  // 正反面各自独立旋转，不旋转父容器，所以背面文字不会镜像。
  const card = document.querySelector("[data-result-art]");
  if (!card) return;
  const frontFace = card.querySelector(".front");
  const backFace = card.querySelector(".back");

  /* ------------------------------------------------- card motion（V2 CARD_MOTION）----
     卡是物理收藏品：落卡、倾角、探视、升力、按压，全部是物体动作。
     动效只负责教会「翻面」这一件事：3 秒无触碰探视一次，7.5 秒再一次，
     之后永远安静。prefers-reduced-motion 时只保留提示文案，不做任何位移。
     邀请计时器只在真实浏览器（有 matchMedia）里排程 —— 无头测试桩没有
     matchMedia，因此不会挂起测试进程；每面的提示元素在运行时插入，
     不进 renderResult 的模板字符串，卡面四块结构保持不变。                        */
  const media = typeof window.matchMedia === "function" ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
  const reduceMotion = Boolean(media && media.matches);
  if (Array.isArray(window.__cardMotionTimers)) window.__cardMotionTimers.forEach(window.clearTimeout);
  window.__cardMotionTimers = [];
  const timers = window.__cardMotionTimers;

  if (!reduceMotion) {
    card.classList.add("card-arrive");
    card.addEventListener("animationend", function onArrive(event) {
      if (event.animationName !== "card-arrive") return;
      card.classList.remove("card-arrive");
      card.removeEventListener("animationend", onArrive);
    });
  }

  // 提示文案已按反馈移除：探视动作本身就是翻面的可供性说明，不再加字。
  let touched = false;
  const quietInvite = () => {
    touched = true;
    timers.forEach(window.clearTimeout);
  };

  if (media && !reduceMotion) {
    timers.push(window.setTimeout(() => {
      if (touched || !card.isConnected) return;
      card.classList.add("card-peek-1");
    }, 3000));
    timers.push(window.setTimeout(() => {
      if (touched || !card.isConnected) return;
      card.classList.remove("card-peek-1");
      card.classList.add("card-peek-2");
    }, 7500));
  }

  const toggle = () => {
    const isBack = card.classList.toggle("is-back");
    card.setAttribute("aria-pressed", String(isBack));
    card.setAttribute("aria-label", isBack ? "返回结果卡正面" : "翻转结果卡");
    if (frontFace) frontFace.setAttribute("aria-hidden", String(isBack));
    if (backFace) backFace.setAttribute("aria-hidden", String(!isBack));
    if (!touched) quietInvite();
    card.classList.remove("card-peek-1");
    card.classList.remove("card-peek-2");
    card.classList.remove("is-flipping");
    void card.offsetWidth; // 连续翻面时让升力动画各自重新起步
    if (!reduceMotion) card.classList.add("is-flipping");
  };
  card.onclick = toggle;
  card.onkeydown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      toggle();
    }
  };
}

async function copyResult(result, textOverride) {
  const text = textOverride || `${result.name || "我的结果"}\n${result.share_line || result.reading || ""}\n\n来自 MYTHIC 原创互动测试`;
  const button = document.querySelector("#copy");
  try {
    await navigator.clipboard.writeText(text);
    button.textContent = "已复制";
  } catch (error) {
    console.error("Failed to copy result:", error);
    button.textContent = "请手动复制";
  }
  window.setTimeout(() => { button.textContent = "复制结果文案"; }, 1800);
}

function shareResult(result, symbol) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;

  const ctx = canvas.getContext("2d");

  // 背景颜色 - 根据主题选择
  const bgColors = {
    "greek-women": "#F2F1E8",
    "grand-view-garden": "#F5EEF2",
    "little-women": "#F7F0E5",
    "pride-prejudice": "#EDF1ED",
    "liaozhai-women": "#102C2C",
    "jane-eyre": "#EEF0F2",
    "peony-pavilion": "#FBF0ED",
    "secret-garden": "#EEF2E7",
    "urban-relations": "#27212A",
    "eileen-chang-city": "#27212A"
  };

  const bgColor = bgColors[state.theme] || "#F6F2EB";
  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, 900, 1200);

  // 文字颜色
  const isDarkTheme = state.theme === "liaozhai-women"
    || state.theme === "urban-relations"
    || state.theme === "eileen-chang-city";
  const textColor = isDarkTheme ? "#F4F0E6" : "#29252A";
  const accentColor = isDarkTheme ? "#E5C78D" : "#5B414C";

  // 头部
  ctx.fillStyle = accentColor;
  ctx.font = "28px sans-serif";
  ctx.fillText("MYTHIC", 70, 90);

  // 结果符号圆圈
  ctx.strokeStyle = accentColor;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(450, 350, 120, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = textColor;
  ctx.font = "bold 80px serif";
  ctx.textAlign = "center";
  ctx.fillText(symbol, 450, 390);

  // 结果名称
  ctx.font = "60px serif";
  ctx.fillText(result.name || "", 450, 580);

  // 副标题
  ctx.font = "26px sans-serif";
  ctx.fillStyle = accentColor;
  ctx.fillText(result.subtitle || result.core_energy || "", 450, 650);

  // 关键词
  ctx.font = "20px sans-serif";
  ctx.fillStyle = textColor;
  const keywords = (result.keywords || []).slice(0, 3).join(" · ");
  ctx.fillText(keywords, 450, 720);

  // 分享短句
  ctx.font = "24px sans-serif";
  const shareLine = result.share_line || "";
  wrapText(ctx, shareLine, 450, 820, 700, 40, textColor);

  // 底部文案
  ctx.font = "18px sans-serif";
  ctx.fillStyle = accentColor;
  ctx.fillText("原创互动测试 · MYTHIC", 450, 1100);

  ctx.fillStyle = textColor;
  ctx.font = "16px sans-serif";
  ctx.fillText("一份象征性的娱乐解读", 450, 1140);

  canvas.toBlob((blob) => {
    if (!blob) {
      console.error("Failed to create result image.");
      return;
    }
    const link = document.createElement("a");
    link.download = `mythic-${state.theme}-${result.id || "result"}.png`;
    link.href = URL.createObjectURL(blob);
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }, "image/png");
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight, color) {
  ctx.fillStyle = color;
  let line = "";
  for (const char of text) {
    const test = line + char;
    if (ctx.measureText(test).width > maxWidth) {
      ctx.fillText(line, x, y);
      line = char;
      y += lineHeight;
    } else {
      line = test;
    }
  }
  ctx.fillText(line, x, y);
}

// 初始化应用。评分核心已移至 server/scoring.mjs；本文件不再导出任何可测的
// 算法接缝。license 门先行，验证通过后才载入题库。
if (typeof document !== "undefined" && document.querySelector) {
  initApp();
}

input.content:
/* 大观园回声 · 产品视觉层（product skin）
 *
 * 公共引擎（app.js）负责 license、路由、题库与服务端评分；本文件只做这个
 * 产品的艺术表达：进入（入园）、答题（十八景）、结果（判词签）。
 * 约束：
 *   - 只读 ctx 提供的数据与回调，不接触评分、权重与题库结构；
 *   - 所有文案经 esc() 后插值；所有样式挂在 body[data-skin] 作用域下，
 *     与默认模板和其他产品完全隔离；
 *   - 无外部依赖、无图片资产，视觉全部由排版 + 内联线描 SVG 构成。
 */

const SKIN_ID = "grand-view-garden";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

/* ------------------------------------------------------ 汉字景序 ---- */
const DIGITS = ["零", "一", "二", "三", "四", "五", "六", "七", "八", "九"];
function cnNumber(n) {
  if (n <= 10) return n === 10 ? "十" : DIGITS[n];
  const tens = Math.floor(n / 10);
  const ones = n % 10;
  return `${tens > 1 ? DIGITS[tens] : ""}十${ones ? DIGITS[ones] : ""}`;
}

/* 结果意象：每位一帧园林小品（线描，currentColor 随所在面板取色）。
   抽象器物与园景，不画人物。 */
const ART = {
  observer: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <rect x="238" y="42" width="118" height="118"/>
        <path d="M238 72h118M238 102h118M238 132h118M268 42v118M298 42v118M327 42v118" stroke-width="1" opacity=".5"/>
        <path d="M86 176c4-42-4-78 8-116"/>
        <path d="M118 176c-2-30 2-54-4-78"/>
        <path d="M94 96c20-8 36-6 50 4M94 128c-18-10-32-10-44-2M120 116c16-10 30-10 42 0"/>
      </g>
      <circle class="ra" cx="206" cy="156" r="4"/>
    </svg>`,
  keeper: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <circle cx="200" cy="96" r="62"/>
        <circle cx="200" cy="96" r="52" stroke-width="1" opacity=".5"/>
        <path d="M148 176h104M162 162h76M176 148h48" stroke-width="1.5"/>
        <path d="M200 148v-8" stroke-width="1.5"/>
      </g>
      <circle class="ra" cx="286" cy="140" r="5"/>
    </svg>`,
  manager: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M58 118l52-22 52 22 52-22 52 22 52-22"/>
        <path d="M84 118v34M136 118v34M188 118v34M240 118v34M292 118v34" stroke-width="1.5"/>
        <path d="M56 168c22-8 44-8 66 0s44 8 66 0 44-8 66 0 44 8 66 0" stroke-width="1.5" opacity=".6"/>
        <path d="M72 182c22-8 44-8 66 0s44 8 66 0 44-8 66 0" stroke-width="1" opacity=".4"/>
      </g>
      <circle class="ra" cx="328" cy="86" r="5"/>
    </svg>`,
  reformer: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M64 176V96M92 176V96M120 176V96M148 176V96"/>
        <path d="M52 112h108M52 144h108" stroke-width="1.5"/>
        <rect x="248" y="112" width="104" height="64" stroke-width="1.5"/>
        <path d="M248 144h104M300 112v64" stroke-width="1" opacity=".5"/>
        <path d="M272 100c-2-12 2-20 8-26M322 100c0-14 6-22 14-26" stroke-width="1.5"/>
      </g>
      <circle class="ra" cx="280" cy="66" r="4"/>
    </svg>`,
  companion: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M116 96c22-34 146-34 168 0"/>
        <path d="M200 62v-10" stroke-width="1.5"/>
        <path d="M138 96v72M262 96v72" stroke-width="1.5"/>
        <path d="M124 168h152" stroke-width="1.5"/>
        <path d="M76 186c20-7 40-7 60 0s40 7 60 0 40-7 60 0 40 7 68 0" stroke-width="1.5" opacity=".6"/>
      </g>
      <circle class="ra" cx="318" cy="176" r="6"/>
    </svg>`,
  departure: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M84 176V52h44v124"/>
        <path d="M128 52l30 18v106" stroke-width="1.5" opacity=".8"/>
        <path d="M170 176c60-8 120-44 168-84" stroke-width="1.5" opacity=".6"/>
        <path d="M170 176c54-2 108-24 152-52" stroke-width="1" opacity=".35"/>
        <path d="M296 96c14-18 34-26 54-24" stroke-width="1.5" opacity=".5"/>
      </g>
      <circle class="ra" cx="336" cy="52" r="5"/>
    </svg>`,
};

function vignette(resultId) {
  return ART[resultId] || ART.keeper;
}

/* --------------------------------------------------------- 公共件 ---- */
function brandBar(right) {
  return `<header class="ggw-top"><span class="ggw-brand">大观园回声</span><span class="ggw-top-right">${right}</span></header>`;
}

function pageShell(inner) {
  return `<div class="ggw">${inner}</div>`;
}

function pathDots(total, current) {
  const dots = [];
  for (let i = 0; i < total; i += 1) {
    const state = i < current ? " done" : i === current ? " now" : "";
    dots.push(`<i class="ggw-dot${state}"></i>`);
  }
  return `<div class="ggw-path" role="progressbar" aria-label="游园进度" aria-valuemin="1" aria-valuemax="${total}" aria-valuenow="${current + 1}">${dots.join("")}</div>`;
}

/* ----------------------------------------------------------- 入园 ---- */
const GATE_ERRORS = {
  empty: "请先写下兑换码。",
  already_bound: "此码已在别的浏览器激活。如需更换设备，请联系卖家重置绑定。",
  rate_limited: "尝试过于频繁，请一炷香后再来。",
  invalid: "兑换码无效，请核对后重新输入。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("凭码入园")}
    <section class="ggw-gate">
      <p class="ggw-eyebrow">Grand View Garden</p>
      <h1 class="ggw-gate-title">入园</h1>
      <p class="ggw-gate-lead">此园凭兑换码开放。激活后与当前浏览器绑定，此后再来不必再验。</p>
      <div class="ggw-gate-form">
        <input id="ggw-gate-code" class="ggw-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="ggw-btn-solid" id="ggw-gate-submit">入园</button>
      </div>
      <p class="ggw-gate-error" id="ggw-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="ggw-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#ggw-gate-code");
    const submit = root.querySelector("#ggw-gate-submit");
    const error = root.querySelector("#ggw-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`此码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，请核对后重新输入。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("原创互动测试")}
    <section class="ggw-cover">
      <p class="ggw-eyebrow">Grand View Garden · 关系片刻测试</p>
      <h1 class="ggw-cover-title">大观园回声</h1>
      <p class="ggw-cover-lead">${esc(ctx.theme.title)}</p>
      <p class="ggw-cover-sub">${esc(ctx.theme.subtitle)}</p>
      <figure class="ggw-gate-art" aria-hidden="true">
        <svg viewBox="0 0 600 340">
          <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
            <circle cx="300" cy="140" r="112"/>
            <circle cx="300" cy="140" r="100" stroke-width="1" opacity=".5"/>
            <path d="M262 328c14-42 28-84 38-118" stroke-width="1.5" opacity=".55"/>
            <path d="M338 328c-14-42-28-84-38-118" stroke-width="1.5" opacity=".55"/>
            <path d="M86 328c4-40-4-72 8-108" />
            <path d="M96 244c20-8 36-6 50 4M96 268c-18-10-32-10-44-2"/>
            <path d="M486 328v-40M510 328v-40M534 328v-40" stroke-width="1.5"/>
            <path d="M472 288h76" stroke-width="1.5"/>
          </g>
          <rect class="ra-fill" x="384" y="58" width="16" height="16"/>
        </svg>
      </figure>
      <div class="ggw-cover-actions">
        <button class="ggw-btn-outline" id="ggw-enter">入 园</button>
      </div>
      <p class="ggw-foot">十八处驻足 · 约六分钟 · 原创象征性娱乐内容，不是心理测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#ggw-enter").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 答题 ---- */
const SLIP_MARKS = ["甲", "乙", "丙", "丁"];

function questionView(ctx) {
  const slips = ctx.options.map((text, i) => `
    <button class="ggw-slip${ctx.selected === i ? " stamped" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="ggw-slip-mark" aria-hidden="true">${SLIP_MARKS[i] || "甲"}</span>
      <span class="ggw-slip-text">${esc(text)}</span>
      <span class="ggw-slip-seal" aria-hidden="true">${SLIP_MARKS[i] || "甲"}</span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`第${cnNumber(ctx.index + 1)}景 · 共${cnNumber(ctx.total)}景`)}
    ${pathDots(ctx.total, ctx.index)}
    <section class="ggw-q">
      <p class="ggw-q-kicker">第${cnNumber(ctx.index + 1)}景</p>
      <h2 class="ggw-q-text">${esc(ctx.question)}</h2>
      <div class="ggw-slips">${slips}</div>
      <div class="ggw-q-nav">
        <button class="ggw-link" id="ggw-prev" ${ctx.index === 0 ? "disabled" : ""}>回看上一景</button>
        <button class="ggw-link" id="ggw-exit">出园</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".ggw-slip").forEach((slip) => {
      slip.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        slip.classList.add("stamped");
        slip.setAttribute("aria-pressed", "true");
        // 落印一瞬再翻页，让选择有一个可见的落点。
        window.setTimeout(() => ctx.select(Number(slip.dataset.i)), 320);
      });
    });
    const prev = root.querySelector("#ggw-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#ggw-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

/* -------------------------------------------------------- 结果等待 ---- */
function resultLoadingView() {
  const html = pageShell(`
    ${brandBar("游园既毕")}
    <section class="ggw-loading">
      <svg viewBox="0 0 120 120" class="ggw-loading-ring" aria-hidden="true">
        <circle cx="60" cy="60" r="46" fill="none" stroke="currentColor" stroke-width="2"/>
        <circle cx="60" cy="60" r="38" fill="none" stroke="currentColor" stroke-width="1" opacity=".5"/>
      </svg>
      <p class="ggw-loading-text">判词正在写就……</p>
      <p class="ggw-foot">判定在服务端完成。</p>
    </section>`);
  return { html };
}

/* -------------------------------------------------------- 判词结果 ---- */
function splitList(value) {
  return String(value || "")
    .split(/[,，;；]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function verdictView(ctx) {
  const result = ctx.result || {};
  const [imageLabel, ...rest] = String(result.subtitle || "").split("：");
  const motto = rest.join("：");
  const strengths = splitList(result.strengths);
  const blindSpots = splitList(result.blind_spots);

  const html = pageShell(`
    ${brandBar("游园既毕")}
    <section class="ggw-result">
      <p class="ggw-eyebrow">Verdict · 判词</p>
      <article class="ggw-verdict">
        <figure class="ggw-verdict-art">${vignette(result.id)}</figure>
        <p class="ggw-verdict-image">${esc(imageLabel || "园中意象")}</p>
        <h2 class="ggw-verdict-name">${esc(result.name || "")}</h2>
        ${motto ? `<p class="ggw-verdict-motto">${esc(motto)}</p>` : ""}
        <p class="ggw-verdict-keys">${(result.keywords || []).map(esc).join(" · ")}</p>
        <span class="ggw-verdict-seal" aria-hidden="true">园</span>
      </article>
      <figure class="ggw-verse"><blockquote>${esc(result.share_line || "")}</blockquote></figure>
      <p class="ggw-energy">${esc(result.core_energy || "")}</p>
      <p class="ggw-reading">${esc(result.reading || "")}</p>
      <div class="ggw-cols">
        ${result.relationship_style ? `<div class="ggw-col"><h3>相处方式</h3><p>${esc(result.relationship_style)}</p></div>` : ""}
        ${result.inner_conflict ? `<div class="ggw-col"><h3>内里张力</h3><p>${esc(result.inner_conflict)}</p></div>` : ""}
        ${strengths.length ? `<div class="ggw-col"><h3>所长</h3><ul>${strengths.map((s) => `<li>${esc(s)}</li>`).join("")}</ul></div>` : ""}
        ${blindSpots.length ? `<div class="ggw-col"><h3>所蔽</h3><ul>${blindSpots.map((s) => `<li>${esc(s)}</li>`).join("")}</ul></div>` : ""}
      </div>
      <div class="ggw-actions">
        <button class="ggw-link" id="ggw-copy">复制判词</button>
        <button class="ggw-link" id="ggw-share">存一张签图</button>
        <button class="ggw-link" id="ggw-again">再游一次</button>
        <button class="ggw-link" id="ggw-home">出园</button>
      </div>
      <p class="ggw-foot ggw-disclaimer">${esc(ctx.disclaimer || "")}</p>
    </section>`);

  const bind = (root) => {
    const copy = root.querySelector("#ggw-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已录入笺上";
      window.setTimeout(() => { copy.textContent = "复制判词"; }, 1800);
    });
    root.querySelector("#ggw-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#ggw-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#ggw-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享签图 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const ctx2d = canvas.getContext("2d");
  const PAPER = "#F6F2E7";
  const INK = "#2C3833";
  const SOFT = "#66716A";
  const ROUGE = "#A5544C";

  ctx2d.fillStyle = PAPER;
  ctx2d.fillRect(0, 0, 900, 1200);

  // 月洞门双环
  ctx2d.strokeStyle = INK;
  ctx2d.lineWidth = 3;
  ctx2d.beginPath();
  ctx2d.arc(450, 260, 128, 0, Math.PI * 2);
  ctx2d.stroke();
  ctx2d.lineWidth = 1.5;
  ctx2d.globalAlpha = 0.5;
  ctx2d.beginPath();
  ctx2d.arc(450, 260, 114, 0, Math.PI * 2);
  ctx2d.stroke();
  ctx2d.globalAlpha = 1;

  const center = (text, y, font, color) => {
    ctx2d.font = font;
    ctx2d.fillStyle = color;
    ctx2d.textAlign = "center";
    ctx2d.fillText(text, 450, y);
  };

  center("GRAND VIEW GARDEN", 480, "300 20px Georgia, serif", SOFT);
  const [imageLabel, ...rest] = String(result.subtitle || "").split("：");
  center(imageLabel || "", 540, "300 30px 'Songti SC', 'SimSun', serif", ROUGE);
  center(result.name || "", 620, "700 72px 'Songti SC', 'SimSun', serif", INK);
  center(rest.join("：") || "", 680, "300 30px 'Songti SC', 'SimSun', serif", SOFT);

  // 签文框
  ctx2d.strokeStyle = SOFT;
  ctx2d.lineWidth = 1.5;
  ctx2d.strokeRect(150, 760, 600, 120);
  ctx2d.beginPath();
  ctx2d.moveTo(150, 748);
  ctx2d.lineTo(750, 748);
  ctx2d.stroke();
  center(result.share_line || "", 832, "300 40px 'Songti SC', 'SimSun', serif", INK);

  center((result.keywords || []).join(" · "), 960, "300 28px 'Songti SC', 'SimSun', serif", SOFT);

  // 印
  ctx2d.fillStyle = ROUGE;
  ctx2d.fillRect(430, 1030, 40, 40);
  ctx2d.fillStyle = PAPER;
  ctx2d.font = "700 26px 'Songti SC', 'SimSun', serif";
  ctx2d.fillText("园", 450, 1059);

  center("大观园回声 · 原创互动测试", 1140, "300 22px 'Songti SC', 'SimSun', serif", SOFT);

  canvas.toBlob((blob) => {
    if (!blob) return;
    const link = document.createElement("a");
    link.download = `grand-view-garden-${result.id || "verdict"}.png`;
    link.href = URL.createObjectURL(blob);
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }, "image/png");
}

/* ------------------------------------------------------------- 出口 ---- */
export default {
  id: SKIN_ID,
  title: "大观园回声 · Mythic",
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
  copyText(result) {
    return `${result.name || ""}｜${result.subtitle || ""}\n${result.share_line || ""}\n—— 大观园回声 · 原创互动测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
};

readFileState.content:
/* 大观园回声 · 产品视觉层（product skin）
 *
 * 公共引擎（app.js）负责 license、路由、题库与服务端评分；本文件只做这个
 * 产品的艺术表达：进入（入园）、答题（十八景）、结果（判词签）。
 * 约束：
 *   - 只读 ctx 提供的数据与回调，不接触评分、权重与题库结构；
 *   - 所有文案经 esc() 后插值；所有样式挂在 body[data-skin] 作用域下，
 *     与默认模板和其他产品完全隔离；
 *   - 无外部依赖、无图片资产，视觉全部由排版 + 内联线描 SVG 构成。
 */

const SKIN_ID = "grand-view-garden";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

/* ------------------------------------------------------ 汉字景序 ---- */
const DIGITS = ["零", "一", "二", "三", "四", "五", "六", "七", "八", "九"];
function cnNumber(n) {
  if (n <= 10) return n === 10 ? "十" : DIGITS[n];
  const tens = Math.floor(n / 10);
  const ones = n % 10;
  return `${tens > 1 ? DIGITS[tens] : ""}十${ones ? DIGITS[ones] : ""}`;
}

/* 结果意象：每位一帧园林小品（线描，currentColor 随所在面板取色）。
   抽象器物与园景，不画人物。 */
const ART = {
  observer: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <rect x="238" y="42" width="118" height="118"/>
        <path d="M238 72h118M238 102h118M238 132h118M268 42v118M298 42v118M327 42v118" stroke-width="1" opacity=".5"/>
        <path d="M86 176c4-42-4-78 8-116"/>
        <path d="M118 176c-2-30 2-54-4-78"/>
        <path d="M94 96c20-8 36-6 50 4M94 128c-18-10-32-10-44-2M120 116c16-10 30-10 42 0"/>
      </g>
      <circle class="ra" cx="206" cy="156" r="4"/>
    </svg>`,
  keeper: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <circle cx="200" cy="96" r="62"/>
        <circle cx="200" cy="96" r="52" stroke-width="1" opacity=".5"/>
        <path d="M148 176h104M162 162h76M176 148h48" stroke-width="1.5"/>
        <path d="M200 148v-8" stroke-width="1.5"/>
      </g>
      <circle class="ra" cx="286" cy="140" r="5"/>
    </svg>`,
  manager: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M58 118l52-22 52 22 52-22 52 22 52-22"/>
        <path d="M84 118v34M136 118v34M188 118v34M240 118v34M292 118v34" stroke-width="1.5"/>
        <path d="M56 168c22-8 44-8 66 0s44 8 66 0 44-8 66 0 44 8 66 0" stroke-width="1.5" opacity=".6"/>
        <path d="M72 182c22-8 44-8 66 0s44 8 66 0 44-8 66 0" stroke-width="1" opacity=".4"/>
      </g>
      <circle class="ra" cx="328" cy="86" r="5"/>
    </svg>`,
  reformer: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M64 176V96M92 176V96M120 176V96M148 176V96"/>
        <path d="M52 112h108M52 144h108" stroke-width="1.5"/>
        <rect x="248" y="112" width="104" height="64" stroke-width="1.5"/>
        <path d="M248 144h104M300 112v64" stroke-width="1" opacity=".5"/>
        <path d="M272 100c-2-12 2-20 8-26M322 100c0-14 6-22 14-26" stroke-width="1.5"/>
      </g>
      <circle class="ra" cx="280" cy="66" r="4"/>
    </svg>`,
  companion: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M116 96c22-34 146-34 168 0"/>
        <path d="M200 62v-10" stroke-width="1.5"/>
        <path d="M138 96v72M262 96v72" stroke-width="1.5"/>
        <path d="M124 168h152" stroke-width="1.5"/>
        <path d="M76 186c20-7 40-7 60 0s40 7 60 0 40-7 60 0 40 7 68 0" stroke-width="1.5" opacity=".6"/>
      </g>
      <circle class="ra" cx="318" cy="176" r="6"/>
    </svg>`,
  departure: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M84 176V52h44v124"/>
        <path d="M128 52l30 18v106" stroke-width="1.5" opacity=".8"/>
        <path d="M170 176c60-8 120-44 168-84" stroke-width="1.5" opacity=".6"/>
        <path d="M170 176c54-2 108-24 152-52" stroke-width="1" opacity=".35"/>
        <path d="M296 96c14-18 34-26 54-24" stroke-width="1.5" opacity=".5"/>
      </g>
      <circle class="ra" cx="336" cy="52" r="5"/>
    </svg>`,
};

function vignette(resultId) {
  return ART[resultId] || ART.keeper;
}

/* --------------------------------------------------------- 公共件 ---- */
function brandBar(right) {
  return `<header class="ggw-top"><span class="ggw-brand">大观园回声</span><span class="ggw-top-right">${right}</span></header>`;
}

function pageShell(inner) {
  return `<div class="ggw">${inner}</div>`;
}

function pathDots(total, current) {
  const dots = [];
  for (let i = 0; i < total; i += 1) {
    const state = i < current ? " done" : i === current ? " now" : "";
    dots.push(`<i class="ggw-dot${state}"></i>`);
  }
  return `<div class="ggw-path" role="progressbar" aria-label="游园进度" aria-valuemin="1" aria-valuemax="${total}" aria-valuenow="${current + 1}">${dots.join("")}</div>`;
}

/* ----------------------------------------------------------- 入园 ---- */
const GATE_ERRORS = {
  empty: "请先写下兑换码。",
  already_bound: "此码已在别的浏览器激活。如需更换设备，请联系卖家重置绑定。",
  rate_limited: "尝试过于频繁，请一炷香后再来。",
  invalid: "兑换码无效，请核对后重新输入。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("凭码入园")}
    <section class="ggw-gate">
      <p class="ggw-eyebrow">Grand View Garden</p>
      <h1 class="ggw-gate-title">入园</h1>
      <p class="ggw-gate-lead">此园凭兑换码开放。激活后与当前浏览器绑定，此后再来不必再验。</p>
      <div class="ggw-gate-form">
        <input id="ggw-gate-code" class="ggw-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="ggw-btn-solid" id="ggw-gate-submit">入园</button>
      </div>
      <p class="ggw-gate-error" id="ggw-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="ggw-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#ggw-gate-code");
    const submit = root.querySelector("#ggw-gate-submit");
    const error = root.querySelector("#ggw-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`此码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，请核对后重新输入。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("原创互动测试")}
    <section class="ggw-cover">
      <p class="ggw-eyebrow">Grand View Garden · 关系片刻测试</p>
      <h1 class="ggw-cover-title">大观园回声</h1>
      <p class="ggw-cover-lead">${esc(ctx.theme.title)}</p>
      <p class="ggw-cover-sub">${esc(ctx.theme.subtitle)}</p>
      <figure class="ggw-gate-art" aria-hidden="true">
        <svg viewBox="0 0 600 340">
          <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
            <circle cx="300" cy="140" r="112"/>
            <circle cx="300" cy="140" r="100" stroke-width="1" opacity=".5"/>
            <path d="M262 328c14-42 28-84 38-118" stroke-width="1.5" opacity=".55"/>
            <path d="M338 328c-14-42-28-84-38-118" stroke-width="1.5" opacity=".55"/>
            <path d="M86 328c4-40-4-72 8-108" />
            <path d="M96 244c20-8 36-6 50 4M96 268c-18-10-32-10-44-2"/>
            <path d="M486 328v-40M510 328v-40M534 328v-40" stroke-width="1.5"/>
            <path d="M472 288h76" stroke-width="1.5"/>
          </g>
          <rect class="ra-fill" x="384" y="58" width="16" height="16"/>
        </svg>
      </figure>
      <div class="ggw-cover-actions">
        <button class="ggw-btn-outline" id="ggw-enter">入 园</button>
      </div>
      <p class="ggw-foot">十八处驻足 · 约六分钟 · 原创象征性娱乐内容，不是心理测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#ggw-enter").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 答题 ---- */
const SLIP_MARKS = ["甲", "乙", "丙", "丁"];

function questionView(ctx) {
  const slips = ctx.options.map((text, i) => `
    <button class="ggw-slip${ctx.selected === i ? " stamped" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="ggw-slip-mark" aria-hidden="true">${SLIP_MARKS[i] || "甲"}</span>
      <span class="ggw-slip-text">${esc(text)}</span>
      <span class="ggw-slip-seal" aria-hidden="true">${SLIP_MARKS[i] || "甲"}</span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`第${cnNumber(ctx.index + 1)}景 · 共${cnNumber(ctx.total)}景`)}
    ${pathDots(ctx.total, ctx.index)}
    <section class="ggw-q">
      <p class="ggw-q-kicker">第${cnNumber(ctx.index + 1)}景</p>
      <h2 class="ggw-q-text">${esc(ctx.question)}</h2>
      <div class="ggw-slips">${slips}</div>
      <div class="ggw-q-nav">
        <button class="ggw-link" id="ggw-prev" ${ctx.index === 0 ? "disabled" : ""}>回看上一景</button>
        <button class="ggw-link" id="ggw-exit">出园</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".ggw-slip").forEach((slip) => {
      slip.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        slip.classList.add("stamped");
        slip.setAttribute("aria-pressed", "true");
        // 落印一瞬再翻页，让选择有一个可见的落点。
        window.setTimeout(() => ctx.select(Number(slip.dataset.i)), 320);
      });
    });
    const prev = root.querySelector("#ggw-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#ggw-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

/* -------------------------------------------------------- 结果等待 ---- */
function resultLoadingView() {
  const html = pageShell(`
    ${brandBar("游园既毕")}
    <section class="ggw-loading">
      <svg viewBox="0 0 120 120" class="ggw-loading-ring" aria-hidden="true">
        <circle cx="60" cy="60" r="46" fill="none" stroke="currentColor" stroke-width="2"/>
        <circle cx="60" cy="60" r="38" fill="none" stroke="currentColor" stroke-width="1" opacity=".5"/>
      </svg>
      <p class="ggw-loading-text">判词正在写就……</p>
      <p class="ggw-foot">判定在服务端完成。</p>
    </section>`);
  return { html };
}

/* -------------------------------------------------------- 判词结果 ---- */
function splitList(value) {
  return String(value || "")
    .split(/[,，;；]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function verdictView(ctx) {
  const result = ctx.result || {};
  const [imageLabel, ...rest] = String(result.subtitle || "").split("：");
  const motto = rest.join("：");
  const strengths = splitList(result.strengths);
  const blindSpots = splitList(result.blind_spots);

  const html = pageShell(`
    ${brandBar("游园既毕")}
    <section class="ggw-result">
      <p class="ggw-eyebrow">Verdict · 判词</p>
      <article class="ggw-verdict">
        <figure class="ggw-verdict-art">${vignette(result.id)}</figure>
        <p class="ggw-verdict-image">${esc(imageLabel || "园中意象")}</p>
        <h2 class="ggw-verdict-name">${esc(result.name || "")}</h2>
        ${motto ? `<p class="ggw-verdict-motto">${esc(motto)}</p>` : ""}
        <p class="ggw-verdict-keys">${(result.keywords || []).map(esc).join(" · ")}</p>
        <span class="ggw-verdict-seal" aria-hidden="true">园</span>
      </article>
      <figure class="ggw-verse"><blockquote>${esc(result.share_line || "")}</blockquote></figure>
      <p class="ggw-energy">${esc(result.core_energy || "")}</p>
      <p class="ggw-reading">${esc(result.reading || "")}</p>
      <div class="ggw-cols">
        ${result.relationship_style ? `<div class="ggw-col"><h3>相处方式</h3><p>${esc(result.relationship_style)}</p></div>` : ""}
        ${result.inner_conflict ? `<div class="ggw-col"><h3>内里张力</h3><p>${esc(result.inner_conflict)}</p></div>` : ""}
        ${strengths.length ? `<div class="ggw-col"><h3>所长</h3><ul>${strengths.map((s) => `<li>${esc(s)}</li>`).join("")}</ul></div>` : ""}
        ${blindSpots.length ? `<div class="ggw-col"><h3>所蔽</h3><ul>${blindSpots.map((s) => `<li>${esc(s)}</li>`).join("")}</ul></div>` : ""}
      </div>
      <div class="ggw-actions">
        <button class="ggw-link" id="ggw-copy">复制判词</button>
        <button class="ggw-link" id="ggw-share">存一张签图</button>
        <button class="ggw-link" id="ggw-again">再游一次</button>
        <button class="ggw-link" id="ggw-home">出园</button>
      </div>
      <p class="ggw-foot ggw-disclaimer">${esc(ctx.disclaimer || "")}</p>
    </section>`);

  const bind = (root) => {
    const copy = root.querySelector("#ggw-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已录入笺上";
      window.setTimeout(() => { copy.textContent = "复制判词"; }, 1800);
    });
    root.querySelector("#ggw-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#ggw-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#ggw-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享签图 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const ctx2d = canvas.getContext("2d");
  const PAPER = "#F6F2E7";
  const INK = "#2C3833";
  const SOFT = "#66716A";
  const ROUGE = "#A5544C";

  ctx2d.fillStyle = PAPER;
  ctx2d.fillRect(0, 0, 900, 1200);

  // 月洞门双环
  ctx2d.strokeStyle = INK;
  ctx2d.lineWidth = 3;
  ctx2d.beginPath();
  ctx2d.arc(450, 260, 128, 0, Math.PI * 2);
  ctx2d.stroke();
  ctx2d.lineWidth = 1.5;
  ctx2d.globalAlpha = 0.5;
  ctx2d.beginPath();
  ctx2d.arc(450, 260, 114, 0, Math.PI * 2);
  ctx2d.stroke();
  ctx2d.globalAlpha = 1;

  const center = (text, y, font, color) => {
    ctx2d.font = font;
    ctx2d.fillStyle = color;
    ctx2d.textAlign = "center";
    ctx2d.fillText(text, 450, y);
  };

  center("GRAND VIEW GARDEN", 480, "300 20px Georgia, serif", SOFT);
  const [imageLabel, ...rest] = String(result.subtitle || "").split("：");
  center(imageLabel || "", 540, "300 30px 'Songti SC', 'SimSun', serif", ROUGE);
  center(result.name || "", 620, "700 72px 'Songti SC', 'SimSun', serif", INK);
  center(rest.join("：") || "", 680, "300 30px 'Songti SC', 'SimSun', serif", SOFT);

  // 签文框
  ctx2d.strokeStyle = SOFT;
  ctx2d.lineWidth = 1.5;
  ctx2d.strokeRect(150, 760, 600, 120);
  ctx2d.beginPath();
  ctx2d.moveTo(150, 748);
  ctx2d.lineTo(750, 748);
  ctx2d.stroke();
  center(result.share_line || "", 832, "300 40px 'Songti SC', 'SimSun', serif", INK);

  center((result.keywords || []).join(" · "), 960, "300 28px 'Songti SC', 'SimSun', serif", SOFT);

  // 印
  ctx2d.fillStyle = ROUGE;
  ctx2d.fillRect(430, 1030, 40, 40);
  ctx2d.fillStyle = PAPER;
  ctx2d.font = "700 26px 'Songti SC', 'SimSun', serif";
  ctx2d.fillText("园", 450, 1059);

  center("大观园回声 · 原创互动测试", 1140, "300 22px 'Songti SC', 'SimSun', serif", SOFT);

  canvas.toBlob((blob) => {
    if (!blob) return;
    const link = document.createElement("a");
    link.download = `grand-view-garden-${result.id || "verdict"}.png`;
    link.href = URL.createObjectURL(blob);
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }, "image/png");
}

/* ------------------------------------------------------------- 出口 ---- */
export default {
  id: SKIN_ID,
  title: "大观园回声 · Mythic",
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
  copyText(result) {
    return `${result.name || ""}｜${result.subtitle || ""}\n${result.share_line || ""}\n—— 大观园回声 · 原创互动测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
};

input.content:
/* 大观园回声 · 产品视觉层样式
 *
 * 作用域：全部规则挂在 body[data-skin="grand-view-garden"] 下，只在皮肤
 * 页面（trySkinView 接管时）被 body 标记激活，与默认模板、其他产品隔离。
 *
 * 世界观：游园。宣纸底、墨青字、黛绿与胭脂两个点缀色；园林线描（月洞门、
 * 竹、阑干、曲桥）作印章式的签名；结果是一支深漆判词签。
 * 刻意避开：大红大金、卷轴、游戏 UI 质感、卡牌翻转结构。
 */

body[data-skin="grand-view-garden"] {
  --ggw-paper: #F6F2E7;
  --ggw-paper-lift: #FCF9F0;
  --ggw-ink: #2C3833;
  --ggw-ink-soft: #66716A;
  --ggw-dai: #3F5C54;
  --ggw-rouge: #A5544C;
  --ggw-lacquer: #2E4038;
  --ggw-lacquer-ink: #EFE8D6;
  --ggw-line: #C9C2AE;
  --ggw-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;

  margin: 0;
  color: var(--ggw-ink);
  font-family: var(--ggw-serif);
  background-color: var(--ggw-paper);
  background-image:
    radial-gradient(1100px 520px at 50% -8%, rgba(255, 253, 246, .9), transparent 70%),
    repeating-linear-gradient(0deg, transparent 0 3px, rgba(84, 92, 82, .012) 3px 4px);
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="grand-view-garden"] .ggw {
  max-width: 660px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 22px 22px 48px;
}

body[data-skin="grand-view-garden"] .ggw-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 40px;
  color: var(--ggw-ink-soft);
  font-size: 12px;
  letter-spacing: .22em;
}

body[data-skin="grand-view-garden"] .ggw-brand {
  color: var(--ggw-ink);
  font-weight: 700;
  letter-spacing: .34em;
}

body[data-skin="grand-view-garden"] .ggw-eyebrow {
  margin: 0;
  color: var(--ggw-rouge);
  font: 400 11px/1 Georgia, serif;
  letter-spacing: .3em;
  text-transform: uppercase;
}

body[data-skin="grand-view-garden"] .ggw-foot {
  margin: 34px 0 0;
  color: var(--ggw-ink-soft);
  font-size: 12px;
  line-height: 1.8;
  letter-spacing: .06em;
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="grand-view-garden"] .ggw-btn-solid,
body[data-skin="grand-view-garden"] .ggw-btn-outline {
  font-family: var(--ggw-serif);
  font-size: 16px;
  letter-spacing: .42em;
  text-indent: .42em;
  cursor: pointer;
  transition: background-color .22s ease, color .22s ease, border-color .22s ease;
}

body[data-skin="grand-view-garden"] .ggw-btn-solid {
  padding: 12px 30px;
