}

body[data-skin="grand-view-garden"] .ggw-slip.stamped { border-color: var(--ggw-dai); }

body[data-skin="grand-view-garden"] .ggw-slip.stamped .ggw-slip-mark {
  background: var(--ggw-dai);
  border-color: var(--ggw-dai);
  color: var(--ggw-paper-lift);
}

body[data-skin="grand-view-garden"] .ggw-slip.stamped .ggw-slip-seal {
  animation: ggw-stamp .32s cubic-bezier(.2, .9, .3, 1.2) both;
}

@keyframes ggw-stamp {
  0% { opacity: 0; transform: translateY(-50%) scale(1.6); }
  100% { opacity: 1; transform: translateY(-50%) scale(1); }
}

@keyframes ggw-fade-up {
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="grand-view-garden"] .ggw-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 30px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="grand-view-garden"] .ggw-loading {
  margin-top: 16vh;
  text-align: center;
  color: var(--ggw-dai);
}

body[data-skin="grand-view-garden"] .ggw-loading-ring {
  width: 88px;
  height: 88px;
  animation: ggw-breathe 2.4s ease-in-out infinite;
}

@keyframes ggw-breathe {
  0%, 100% { opacity: .45; transform: scale(.97); }
  50% { opacity: 1; transform: scale(1); }
}

body[data-skin="grand-view-garden"] .ggw-loading-text {
  margin: 26px 0 6px;
  color: var(--ggw-ink);
  font-size: 16px;
  letter-spacing: .3em;
}

/* ---------------------------------------------------------------- 判词 ---- */
body[data-skin="grand-view-garden"] .ggw-result { margin-top: 2vh; }

body[data-skin="grand-view-garden"] .ggw-verdict {
  position: relative;
  margin: 22px 0 0;
  padding: 30px 30px 34px;
  border-radius: 3px;
  background:
    radial-gradient(560px 300px at 85% -10%, rgba(255, 250, 235, .07), transparent 60%),
    var(--ggw-lacquer);
  color: var(--ggw-lacquer-ink);
  box-shadow: 0 22px 44px rgba(38, 52, 46, .28);
  text-align: center;
  overflow: hidden;
}

body[data-skin="grand-view-garden"] .ggw-verdict-art {
  margin: 0 auto;
  width: min(78%, 330px);
  color: var(--ggw-lacquer-ink);
}

body[data-skin="grand-view-garden"] .ggw-verdict-art svg {
