const VOID = new Set(["br","hr","img","input","meta","link","area","base","col","embed","source","track","wbr"]);
function parseFragment(html) {
  const root = new El("#fragment");
  const stack = [root];
  const re = /<\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\s+[a-zA-Z-]+(?:\s*=\s*"[^"]*"|\s*=\s*'[^']*'|\s*=\s*[^\s>]+)?)*)\s*(\/?)>|([^<]+)/g;
  let m;
  while ((m = re.exec(html))) {
    if (m[4] !== undefined) {
      const text = m[4];
      if (text.trim()) stack[stack.length-1].children.push({ textNode: text });
      continue;
    }
    const tag = m[1].toLowerCase();
    const attrs = m[2] || "";
    const selfClose = m[3] === "/";
    if (html[m.index+1] === "/") { // closing tag
      // pop until matching tag
      for (let i = stack.length-1; i>0; i--) { if (stack[i].tagName===tag.toUpperCase()) { stack.length = i; break; } }
      continue;
    }
    const el = new El(tag);
    const attrRe = /([a-zA-Z-]+)(?:\s*=\s*("([^"]*)"|'([^']*)'|[^\s>]+))?/g;
    let a;
    while ((a = attrRe.exec(attrs))) {
      const name = a[1].toLowerCase();
      const value = a[3] ?? a[4] ?? a[2] ?? "";
      el.attributes[name] = value;
      if (name === "id") el.id = value;
      if (name === "class") String(value).split(/\s+/).filter(Boolean).forEach(c=>el.classList.add(c));
      if (name.startsWith("data-")) el.dataset[name.slice(5)] = value;
    }
    stack[stack.length-1].children.push(el);
    el.parent = stack[stack.length-1];
    if (!VOID.has(tag) && !selfClose) stack.push(el);
  }
  return root.children;
}
```

