/* 大观园皮肤 · 端到端流程测试。
 *
 * 用真实 deploy-ready/app.js + 真实 themes/grand-view-garden/skin.js 驱动
 * 完整流程：入园（兑换码）→ 封面 → 十八景逐题作答 → 服务端评分（真实
 * server/scoring.mjs）→ 判词结果页，全部应渲染大观园皮肤而非默认模板。
 * 另附隔离检查：skin.css 全部选择器都挂在 body[data-skin] 作用域下；
 * 皮肤层不带任何评分/网络逻辑；公共层不被皮肤类名渗入。
 *
 * Run: node tools/test-garden-skin.mjs
 */
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { selectWinner } from "../server/scoring.mjs";
import { sanitizeTheme } from "../server/sanitize.mjs";
import { productThemes } from "../server/products.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const results = [];
const check = (name, fn) => {
  try {
    const d = fn();
    if (d && typeof d.then === "function") {
      return d.then((detail) => results.push({ ok: true, name, d: detail }),
        (e) => results.push({ ok: false, name, d: e.message }));
    }
    results.push({ ok: true, name, d });
  } catch (e) {
    results.push({ ok: false, name, d: e.message });
  }
  return Promise.resolve();
};
const assert = (c, m) => { if (!c) throw new Error(m); };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* --------------------------------------------------------- DOM 桩 ---- */
const VOID = new Set(["br", "hr", "img", "input", "meta", "link", "area", "base", "col", "embed", "source", "track", "wbr"]);

function parseFragment(html) {
  const root = new El("#fragment");
  const stack = [root];
  const tokenRe = /<\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\s+[a-zA-Z-]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?)*)\s*(\/?)>|([^<]+)/g;
  let m;
  while ((m = tokenRe.exec(html))) {
    if (m[4] !== undefined) {
      if (m[4].trim()) stack[stack.length - 1].children.push(m[4]);
      continue;
    }
    const tag = m[1].toLowerCase();
    if (html[m.index + 1] === "/") {
      for (let i = stack.length - 1; i > 0; i -= 1) {
        if (stack[i].tagName === tag.toUpperCase()) { stack.length = i; break; }
      }
      continue;
    }
    const el = new El(tag);
    const attrRe = /([a-zA-Z-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
    let a;
    while ((a = attrRe.exec(m[2] || ""))) {
      const name = a[1].toLowerCase();
      const value = a[2] ?? a[3] ?? a[4] ?? "";
      el.attributes[name] = value;
      if (name === "id") el.id = value;
      if (name === "class") String(value).split(/\s+/).filter(Boolean).forEach((c) => el.classList.add(c));
      if (name.startsWith("data-")) el.dataset[name.slice(5).replace(/-([a-z])/g, (_, ch) => ch.toUpperCase())] = value;
    }
    stack[stack.length - 1].children.push(el);
    el.parent = stack[stack.length - 1];
    if (!VOID.has(tag) && m[3] !== "/") stack.push(el);
  }
  return root.children;
}

function matchesSelector(el, selector) {
  const m = selector.match(/^([a-zA-Z][\w-]*)?((?:[.#][\w-]+)*)$/);
  if (!m) throw new Error(`stub selector unsupported: ${selector}`);
  if (m[1] && el.tagName !== m[1].toUpperCase()) return false;
  const rest = m[2] || "";
  const parts = rest.match(/[.#][\w-]+/g) || [];
  for (const part of parts) {
    if (part[0] === "#") { if (el.id !== part.slice(1)) return false; }
    else if (!el.classList.contains(part.slice(1))) return false;
  }
  return true;
}

class El {
  constructor(tag) {
    this.tagName = tag.toUpperCase();
    this.id = "";
    this.children = [];
    this.attributes = {};
    this.dataset = {};
    this.listeners = {};
    this._cls = new Set();
    this.style = {};
    this.value = "";
    this.hidden = false;
    this.parent = null;
    this.classList = {
      add: (...names) => names.forEach((n) => this._cls.add(n)),
      remove: (...names) => names.forEach((n) => this._cls.delete(n)),
      contains: (n) => this._cls.has(n),
      toggle: (n, force) => {
        const wants = force === undefined ? !this._cls.has(n) : Boolean(force);
        if (wants) this._cls.add(n); else this._cls.delete(n);
        return wants;
      },
    };
  }
  set innerHTML(html) { this.children = parseFragment(html); }
  get innerHTML() { return this.children.map((c) => (typeof c === "string" ? c : c.outer)).join(""); }
  get outer() { return `<${this.tagName.toLowerCase()}>${this.innerHTML}</${this.tagName.toLowerCase()}>`; }
  get textContent() { return this.children.map((c) => (typeof c === "string" ? c : c.textContent)).join(""); }
  set textContent(v) { this.children = [String(v)]; }
  setAttribute(n, v) { this.attributes[n] = String(v); if (n === "id") this.id = String(v); }
  getAttribute(n) { return this.attributes[n] ?? null; }
  removeAttribute(n) { delete this.attributes[n]; }
  addEventListener(t, fn) { (this.listeners[t] ||= []).push(fn); }
  removeEventListener(t, fn) { this.listeners[t] = (this.listeners[t] || []).filter((f) => f !== fn); }
  dispatch(type, event = {}) { (this.listeners[type] || []).forEach((fn) => fn({ ...event, target: this })); }
  click() { this.dispatch("click"); }
  focus() {}
  querySelector(sel) { return this.querySelectorAll(sel)[0] || null; }
  querySelectorAll(sel) {
    const out = [];
    const walk = (el) => {
      for (const child of el.children) {
        if (typeof child !== "string") {
          if (matchesSelector(child, sel)) out.push(child);
          walk(child);
        }
      }
    };
    walk(this);
    return out;
  }
  appendChild(child) { this.children.push(child); child.parent = this; return child; }
}

/* --------------------------------------------------- 浏览器全局桩 ---- */
const appEl = new El("main");
appEl.id = "app";
const docEl = new El("#document");
docEl.appendChild(appEl);
const bodyEl = new El("body");
docEl.appendChild(bodyEl);
const headEl = new El("head");
docEl.appendChild(headEl);

const storage = new Map();
globalThis.localStorage = {
  getItem: (k) => (storage.has(k) ? storage.get(k) : null),
  setItem: (k, v) => storage.set(k, String(v)),
  removeItem: (k) => storage.delete(k),
};
globalThis.document = Object.assign(docEl, {
  body: bodyEl,
  head: headEl,
  title: "",
  createElement: (tag) => {
    const el = new El(tag);
    if (tag === "canvas") {
      el.getContext = () => new Proxy({}, { get: () => () => {} });
      el.toBlob = (cb) => cb(null);
    }
    return el;
  },
});
globalThis.location = { pathname: "/t/grand-view-garden", search: "" };
globalThis.navigator = {
  userAgent: "garden-test", language: "zh-CN", platform: "test",
  clipboard: { writeText: async () => {} },
};
globalThis.screen = { width: 390, height: 844, colorDepth: 24 };
globalThis.window = globalThis;

/* ----------------------------------------------------- API 桩 ---- */
const CODE = "GARDENSMOKE001"; // normalizeCode 后与下方一致
const SECRET = "[REDACTED:SECRET_ASSIGNMENT]";
const GARDEN_THEMES = productThemes("grand-view-garden");
const SANITIZED = {
  product: { product_id: "grand-view-garden", name: "大观园回声测试" },
  themes: GARDEN_THEMES.map(sanitizeTheme),
};
let activated = false;
globalThis.fetch = async (url, options = {}) => {
  const body = options.body ? JSON.parse(options.body) : {};
  const norm = (c) => String(c || "").toUpperCase().replace(/[\s-]+/g, "");
  const path = String(url).split("?")[0];
  if (path === "/api/redeem") {
    if (norm(body.code) !== norm(CODE)) return json(404, { ok: false, error: "invalid_code" });
    if (!activated) {
      activated = true;
      return json(200, { ok: true, secret: SECRET, firstUse: true, product_id: "grand-view-garden", product_name: "大观园回声测试" });
    }
    if (body.secret === SECRET) return json(200, { ok: true, secret: SECRET, firstUse: false, product_id: "grand-view-garden", product_name: "大观园回声测试" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/verify-license") {
    if (norm(body.code) === norm(CODE) && body.secret === SECRET && activated) return json(200, { ok: true, product_id: "grand-view-garden", product_name: "大观园回声测试" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/content") return json(200, SANITIZED);
  if (path === "/api/score") {
    const theme = GARDEN_THEMES.find((t) => t.id === body.theme);
    if (!theme) return json(404, { ok: false, error: "invalid_theme" });
    if (norm(body.code) !== norm(CODE) || body.secret !== SECRET) return json(403, { ok: false, error: "already_bound" });
    const { winnerId } = selectWinner(theme, body.answers);
    const result = theme.results.find((r) => r.id === winnerId);
    return json(200, { ok: true, winnerId, result });
  }
  throw new Error(`unexpected fetch: ${url}`);
};
function json(status, body) {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}

/* --------------------------------------------- 挂载真实皮肤并启动 ---- */
const skinModule = await import(join(ROOT, "deploy-ready", "themes", "grand-view-garden", "skin.js"));
globalThis.__MYTHIC_SKINS__ = { "grand-view-garden": skinModule.default };

const appSource = readFileSync(join(ROOT, "deploy-ready", "app.js"), "utf8");
new Function("module", "exports", appSource)({ exports: {} }, {});
await sleep(80);

const skinCss = readFileSync(join(ROOT, "deploy-ready", "themes", "grand-view-garden", "skin.css"), "utf8");

/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the garden gate skin, not the default gate", () => {
  assert(appEl.querySelector(".ggw-gate-title"), "garden gate title missing");
  assert(appEl.querySelector(".ggw-gate-title").textContent.includes("入园"), "gate title copy wrong");
  assert(!appEl.querySelector(".gate-hero"), "default gate template leaked into skin flow");
  assert(bodyEl.attributes["data-skin"] === "grand-view-garden", "body data-skin not set");
  assert(globalThis.document.title.includes("大观园回声"), "skin title not adopted");
  return "garden gate";
});

await check("a valid code unlocks the garden cover", async () => {
  const input = appEl.querySelector("#ggw-gate-code");
  const submit = appEl.querySelector("#ggw-gate-submit");
  assert(input && submit, "gate form missing");
  input.value = CODE.toLowerCase();
  submit.click();
  await sleep(120);
  assert(appEl.querySelector(".ggw-cover-title"), "garden cover missing after redeem");
  assert(appEl.querySelector(".ggw-cover-title").textContent.includes("大观园回声"), "cover title wrong");
  assert(appEl.querySelector("#ggw-enter"), "enter button missing");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1") || "null");
  assert(stored && stored.secret === SECRET, "license not persisted");
  return "cover";
});

await check("entering the garden starts at 景一 with 18 path dots and 3 slips", async () => {
  appEl.querySelector("#ggw-enter").click();
  await sleep(80);
  assert(appEl.querySelector(".ggw-q-kicker").textContent.includes("第一景"), `expected 景一, got ${appEl.querySelector(".ggw-q-kicker")?.textContent}`);
  assert(appEl.querySelectorAll(".ggw-dot").length === 18, "path must show 18 stops");
  assert(appEl.querySelectorAll(".ggw-slip").length === 3, "three slips expected");
  const brand = appEl.querySelector(".ggw-top").textContent;
  assert(brand.includes("第一景") && brand.includes("十八景"), `topbar numbering wrong: ${brand}`);
  return "景一";
});

await check("stamping a slip advances after the seal beat, previous walks back", async () => {
  appEl.querySelectorAll(".ggw-slip")[1].click();
  await sleep(60);
  const stamped = appEl.querySelectorAll(".ggw-slip")[1];
  assert(stamped.classList.contains("stamped"), "slip must be stamped before advancing");
  await sleep(420);
  assert(appEl.querySelector(".ggw-q-kicker").textContent.includes("第二景"), "did not advance to 景二");
  appEl.querySelector("#ggw-prev").click();
  await sleep(50);
  assert(appEl.querySelector(".ggw-q-kicker").textContent.includes("第一景"), "回看上一景 failed");
  assert(appEl.querySelectorAll(".ggw-slip")[1].classList.contains("stamped"), "returning must show the recorded stamp");
  return "stamp + back";
});

await check("a full 18-stop run lands on the verdict page", async () => {
  for (let i = 0; i < 18; i += 1) {
    const kickers = appEl.querySelector(".ggw-q-kicker");
    assert(kickers, `question ${i + 1} missing`);
    appEl.querySelectorAll(".ggw-slip")[0].click();
    await sleep(420);
  }
  const name = appEl.querySelector(".ggw-verdict-name");
  assert(name, "verdict name missing");
  assert(appEl.querySelector(".ggw-verdict-art svg"), "verdict vignette missing");
  assert(appEl.querySelector(".ggw-verdict-seal"), "verdict seal missing");
  assert(appEl.querySelector(".ggw-verse blockquote").textContent.trim().length > 0, "verse empty");
  assert(appEl.querySelector(".ggw-reading").textContent.length > 50, "reading missing");
  for (const id of ["#ggw-copy", "#ggw-share", "#ggw-again", "#ggw-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  assert(appEl.querySelector(".ggw-disclaimer"), "disclaimer missing");
  return `判词：${name.textContent}`;
});

await check("share and copy actions work inside the skin", async () => {
  appEl.querySelector("#ggw-share").click();
  appEl.querySelector("#ggw-copy").click();
  await sleep(60);
  const copy = appEl.querySelector("#ggw-copy");
  assert(copy.textContent.includes("已录入笺上"), `copy feedback wrong: ${copy.textContent}`);
  return "share + copy";
});

await check("again returns to 景一, exit returns to the cover", async () => {
  appEl.querySelector("#ggw-again").click();
  await sleep(60);
  assert(appEl.querySelector(".ggw-q-kicker").textContent.includes("第一景"), "再游一次 failed");
  appEl.querySelector("#ggw-exit").click();
  await sleep(60);
  assert(appEl.querySelector(".ggw-cover-title"), "出园 failed");
  return "again + exit";
});

/* ------------------------------------------------------- 隔离检查 ---- */
check("skin.css is fully scoped to body[data-skin]", () => {
  const stripped = skinCss.replace(/\/\*[\s\S]*?\*\//g, "");
  let depth = 0;
  let media = 0;
  for (const line of stripped.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const opens = (trimmed.match(/{/g) || []).length;
    const closes = (trimmed.match(/}/g) || []).length;
    if (trimmed.endsWith("{") || opens > closes) {
      const isSelector = opens === 1 && trimmed.endsWith("{");
      if (isSelector && !/^(body\[data-skin|@media|@keyframes|from|to|\d+%)/.test(trimmed)) {
        throw new Error(`unscoped selector: ${trimmed}`);
      }
    }
    depth += opens - closes;
  }
  assert(depth === 0, "unbalanced braces in skin.css");
  return "every selector carries the scope prefix";
});

check("skin classes used by skin.js all exist in skin.css", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "grand-view-garden", "skin.js"), "utf8");
  const used = new Set([...js.matchAll(/ggw-[a-z0-9-]+/g)].map((m) => m[0]));
  const defined = new Set([...skinCss.matchAll(/\.(ggw-[a-z0-9-]+)/g)].map((m) => m[1]));
  const missing = [...used].filter((c) => !defined.has(c));
  assert(missing.length === 0, `classes without CSS: ${missing.join(", ")}`);
  return `${used.size} classes covered`;
});

check("the skin carries no scoring, network or content-file logic", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "grand-view-garden", "skin.js"), "utf8");
  for (const banned of ["scores", "normalization_bounds", "selectWinner", "quiz_content_upgrade", "fetch("]) {
    assert(!js.includes(banned), `skin must not contain ${banned}`);
  }
  return "expression only";
});

check("the common layer is free of skin class names", () => {
  assert(!appSource.includes("ggw-"), "default templates must not reference skin classes");
  return "no leak into app.js templates";
});

delete globalThis.__MYTHIC_SKINS__;

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n大观园皮肤 · 流程测试\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
process.exit(failures.length ? 1 : 0);

