    if (body.secret === SECRET) return json(200, { ok: true, secret: SECRET, firstUse: false, product_id: "grand-view-garden", product_name: "大观园回声测试" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/verify-license") {
    if (norm(body.code) === norm(CODE) && body.secret === SECRET && activated) return json(200, { ok: true, product_id: "grand-view-garden", product_name: "大观园回声测试" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/content") return json(200, SANITIZED);
  if (path === "/api/score") {
    const theme = GARDEN_THEMES.find((t) => t.id === body.theme);
    if (!theme) return json(404, { ok: false, error: "invalid_theme" });
    if (norm(body.code) !== norm(CODE) || body.secret !== SECRET) return json(403, { ok: false, error: "already_bound" });
