THEMES_SUBDIR = Path("themes")  # product skins — every product skin ships to both deploys


def sync_tree(src_dir: Path, dst_dir: Path, args, mismatches: list, copied: list) -> list[str]:
    """Mirror every file under src_dir into dst_dir (recursively)."""
    if args.write:
        dst_dir.mkdir(parents=True, exist_ok=True)
    names = sorted(str(p.relative_to(src_dir)) for p in src_dir.rglob("*") if p.is_file())
    for name in names:
        src, dst = src_dir / name, dst_dir / name
        if dst.exists() and digest(src) == digest(dst):
            continue
        mismatches.append(f"{src_dir.name}/{name}")
        print(f"  DIFFERS {name}")
        if args.write:
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
            copied.append(name)
    for path in sorted(dst_dir.rglob("*")):
        if path.is_file() and not (src_dir / path.relative_to(dst_dir)).exists():
            print(f"  only in deploy/: {path.relative_to(dst_dir)} (left alone)")
            mismatches.append(f"only-in-deploy:{path.relative_to(dst_dir)}")
    return names

