readFileState.content:
/* 大观园回声 · 产品视觉层样式
 *
 * 作用域：全部规则挂在 body[data-skin="grand-view-garden"] 下，只在皮肤
 * 页面（trySkinView 接管时）被 body 标记激活，与默认模板、其他产品隔离。
 *
 * 世界观：游园。宣纸底、墨青字、黛绿与胭脂两个点缀色；园林线描（月洞门、
 * 竹、阑干、曲桥）作印章式的签名；结果是一支深漆判词签。
 * 刻意避开：大红大金、卷轴、游戏 UI 质感、卡牌翻转结构。
 */

body[data-skin="grand-view-garden"] {
  --ggw-paper: #F6F2E7;
  --ggw-paper-lift: #FCF9F0;
  --ggw-ink: #2C3833;
  --ggw-ink-soft: #66716A;
  --ggw-dai: #3F5C54;
  --ggw-rouge: #A5544C;
  --ggw-lacquer: #2E4038;
  --ggw-lacquer-ink: #EFE8D6;
  --ggw-line: #C9C2AE;
  --ggw-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;

  margin: 0;
  color: var(--ggw-ink);
  font-family: var(--ggw-serif);
  background-color: var(--ggw-paper);
  background-image:
    radial-gradient(1100px 520px at 50% -8%, rgba(255, 253, 246, .9), transparent 70%),
    repeating-linear-gradient(0deg, transparent 0 3px, rgba(84, 92, 82, .012) 3px 4px);
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="grand-view-garden"] .ggw {
  max-width: 660px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 22px 22px 48px;
}

body[data-skin="grand-view-garden"] .ggw-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 40px;
  color: var(--ggw-ink-soft);
  font-size: 12px;
  letter-spacing: .22em;
}

body[data-skin="grand-view-garden"] .ggw-brand {
  color: var(--ggw-ink);
  font-weight: 700;
  letter-spacing: .34em;
}

body[data-skin="grand-view-garden"] .ggw-eyebrow {
  margin: 0;
  color: var(--ggw-rouge);
  font: 400 11px/1 Georgia, serif;
  letter-spacing: .3em;
  text-transform: uppercase;
}

body[data-skin="grand-view-garden"] .ggw-foot {
  margin: 34px 0 0;
  color: var(--ggw-ink-soft);
  font-size: 12px;
  line-height: 1.8;
  letter-spacing: .06em;
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="grand-view-garden"] .ggw-btn-solid,
body[data-skin="grand-view-garden"] .ggw-btn-outline {
  font-family: var(--ggw-serif);
  font-size: 16px;
  letter-spacing: .42em;
  text-indent: .42em;
  cursor: pointer;
  transition: background-color .22s ease, color .22s ease, border-color .22s ease;
}

body[data-skin="grand-view-garden"] .ggw-btn-solid {
  padding: 12px 30px;
  border: 0;
  background: var(--ggw-dai);
  color: var(--ggw-paper-lift);
}

body[data-skin="grand-view-garden"] .ggw-btn-solid:hover { background: #33504A; }

body[data-skin="grand-view-garden"] .ggw-btn-outline {
  padding: 14px 52px;
  border: 1px solid var(--ggw-ink);
  background: transparent;
  color: var(--ggw-ink);
}

body[data-skin="grand-view-garden"] .ggw-btn-outline:hover {
  background: var(--ggw-dai);
  border-color: var(--ggw-dai);
  color: var(--ggw-paper-lift);
}

body[data-skin="grand-view-garden"] .ggw-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--ggw-ink) 45%, transparent);
  background: transparent;
  color: var(--ggw-ink);
  font-family: var(--ggw-serif);
  font-size: 13px;
  letter-spacing: .18em;
  cursor: pointer;
}

body[data-skin="grand-view-garden"] .ggw-link:hover { color: var(--ggw-dai); border-color: var(--ggw-dai); }
body[data-skin="grand-view-garden"] .ggw-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 入园 ---- */
body[data-skin="grand-view-garden"] .ggw-gate { max-width: 430px; margin: 9vh auto 0; }

body[data-skin="grand-view-garden"] .ggw-gate-title {
  margin: 18px 0 14px;
  font-size: clamp(46px, 10vw, 64px);
  font-weight: 500;
  letter-spacing: .3em;
  line-height: 1;
}

body[data-skin="grand-view-garden"] .ggw-gate-lead {
  margin: 0 0 34px;
  color: var(--ggw-ink-soft);
  font-size: 14px;
  line-height: 2;
}

body[data-skin="grand-view-garden"] .ggw-gate-form {
  display: flex;
  gap: 12px;
  align-items: stretch;
}

body[data-skin="grand-view-garden"] .ggw-gate-input {
  flex: 1;
  min-width: 0;
  padding: 12px 4px;
  border: 0;
  border-bottom: 1px solid var(--ggw-ink);
  background: transparent;
  color: var(--ggw-ink);
  font: 600 15px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .08em;
  text-transform: uppercase;
  border-radius: 0;
}

body[data-skin="grand-view-garden"] .ggw-gate-input:focus-visible {
  outline: 0;
  border-bottom: 2px solid var(--ggw-rouge);
}

body[data-skin="grand-view-garden"] .ggw-gate-error {
  min-height: 22px;
  margin: 14px 0 0;
  color: var(--ggw-rouge);
  font-size: 13px;
  letter-spacing: .04em;
}

/* ---------------------------------------------------------------- 封面 ---- */
body[data-skin="grand-view-garden"] .ggw-cover {
  position: relative;
  margin-top: 5vh;
  text-align: center;
}

body[data-skin="grand-view-garden"] .ggw-cover-title {
  margin: 26px 0 22px;
  font-size: clamp(38px, 10vw, 76px);
  font-weight: 500;
  letter-spacing: .1em;
  text-indent: .1em;
  line-height: 1.08;
  white-space: nowrap;
}

body[data-skin="grand-view-garden"] .ggw-cover-lead {
  max-width: 30em;
  margin: 0 auto;
  font-size: clamp(17px, 4.4vw, 20px);
  line-height: 2;
  letter-spacing: .05em;
}

body[data-skin="grand-view-garden"] .ggw-cover-sub {
  max-width: 30em;
  margin: 12px auto 0;
  color: var(--ggw-ink-soft);
  font-size: 13.5px;
  line-height: 1.9;
  letter-spacing: .06em;
}

body[data-skin="grand-view-garden"] .ggw-gate-art {
  margin: 8px auto 0;
  width: min(96%, 470px);
  color: var(--ggw-ink);
}

body[data-skin="grand-view-garden"] .ggw-gate-art svg { display: block; width: 100%; height: auto; }
body[data-skin="grand-view-garden"] .ra { fill: var(--ggw-rouge); stroke: none; }
body[data-skin="grand-view-garden"] .ra-fill { fill: var(--ggw-rouge); }

body[data-skin="grand-view-garden"] .ggw-cover-actions { margin: 26px 0 0; }

/* ---------------------------------------------------------------- 游园路径 ---- */
body[data-skin="grand-view-garden"] .ggw-path {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  align-items: center;
  margin: 0 2px 34px;
}

body[data-skin="grand-view-garden"] .ggw-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  border: 1px solid var(--ggw-ink-soft);
  opacity: .5;
}

body[data-skin="grand-view-garden"] .ggw-dot.done {
  background: var(--ggw-dai);
  border-color: var(--ggw-dai);
  opacity: .85;
}

body[data-skin="grand-view-garden"] .ggw-dot.now {
  width: 9px;
  height: 9px;
  border-color: var(--ggw-rouge);
  background: var(--ggw-paper-lift);
  opacity: 1;
  animation: ggw-pulse 1.8s ease-in-out infinite;
}

@keyframes ggw-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(165, 84, 76, .32); }
  50% { box-shadow: 0 0 0 5px rgba(165, 84, 76, 0); }
}

/* ---------------------------------------------------------------- 答题 ---- */
body[data-skin="grand-view-garden"] .ggw-q-kicker {
  margin: 0 0 10px;
  color: var(--ggw-rouge);
  font-size: 13px;
  letter-spacing: .5em;
}

body[data-skin="grand-view-garden"] .ggw-q-text {
  margin: 0 0 34px;
  font-size: clamp(24px, 6vw, 31px);
  font-weight: 500;
  line-height: 1.72;
  letter-spacing: .03em;
}

body[data-skin="grand-view-garden"] .ggw-slips {
  display: grid;
  gap: 14px;
}

body[data-skin="grand-view-garden"] .ggw-slip {
  position: relative;
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 18px 20px;
  border: 1px solid var(--ggw-line);
  border-radius: 2px;
  background: var(--ggw-paper-lift);
  box-shadow: 0 1px 0 rgba(84, 92, 82, .08);
  color: var(--ggw-ink);
  font-family: var(--ggw-serif);
  text-align: left;
  cursor: pointer;
  transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease;
  animation: ggw-fade-up .5s cubic-bezier(.2, .7, .2, 1) both;
}

body[data-skin="grand-view-garden"] .ggw-slip:nth-child(2) { animation-delay: .07s; }
body[data-skin="grand-view-garden"] .ggw-slip:nth-child(3) { animation-delay: .14s; }

body[data-skin="grand-view-garden"] .ggw-slip:hover {
  border-color: var(--ggw-dai);
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(47, 64, 56, .1);
}

body[data-skin="grand-view-garden"] .ggw-slip-mark {
  display: grid;
  flex: 0 0 26px;
  width: 26px;
  height: 26px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--ggw-ink) 55%, transparent);
  color: var(--ggw-ink);
  font-size: 13px;
  transition: background-color .16s ease, color .16s ease, border-color .16s ease;
}

body[data-skin="grand-view-garden"] .ggw-slip-text {
  font-size: 15.5px;
  line-height: 1.85;
  letter-spacing: .02em;
}

/* 落印：选中的一笺右缘盖胭脂印 */
body[data-skin="grand-view-garden"] .ggw-slip-seal {
  position: absolute;
  top: 50%;
  right: 16px;
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  background: var(--ggw-rouge);
  color: var(--ggw-paper-lift);
  font-size: 13px;
  opacity: 0;
  transform: translateY(-50%) scale(1.5);
  pointer-events: none;
}

body[data-skin="grand-view-garden"] .ggw-slip.stamped { border-color: var(--ggw-dai); }

body[data-skin="grand-view-garden"] .ggw-slip.stamped .ggw-slip-mark {
  background: var(--ggw-dai);
  border-color: var(--ggw-dai);
  color: var(--ggw-paper-lift);
}

body[data-skin="grand-view-garden"] .ggw-slip.stamped .ggw-slip-seal {
  animation: ggw-stamp .32s cubic-bezier(.2, .9, .3, 1.2) both;
}

@keyframes ggw-stamp {
  0% { opacity: 0; transform: translateY(-50%) scale(1.6); }
  100% { opacity: 1; transform: translateY(-50%) scale(1); }
}

@keyframes ggw-fade-up {
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="grand-view-garden"] .ggw-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 30px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="grand-view-garden"] .ggw-loading {
  margin-top: 16vh;
  text-align: center;
  color: var(--ggw-dai);
}

body[data-skin="grand-view-garden"] .ggw-loading-ring {
  width: 88px;
  height: 88px;
  animation: ggw-breathe 2.4s ease-in-out infinite;
}

@keyframes ggw-breathe {
  0%, 100% { opacity: .45; transform: scale(.97); }
  50% { opacity: 1; transform: scale(1); }
}

body[data-skin="grand-view-garden"] .ggw-loading-text {
  margin: 26px 0 6px;
  color: var(--ggw-ink);
  font-size: 16px;
  letter-spacing: .3em;
}

/* ---------------------------------------------------------------- 判词 ---- */
body[data-skin="grand-view-garden"] .ggw-result { margin-top: 2vh; }

body[data-skin="grand-view-garden"] .ggw-verdict {
  position: relative;
  margin: 22px 0 0;
  padding: 30px 30px 34px;
  border-radius: 3px;
  background:
    radial-gradient(560px 300px at 85% -10%, rgba(255, 250, 235, .07), transparent 60%),
    var(--ggw-lacquer);
  color: var(--ggw-lacquer-ink);
  box-shadow: 0 22px 44px rgba(38, 52, 46, .28);
  text-align: center;
  overflow: hidden;
}

body[data-skin="grand-view-garden"] .ggw-verdict-art {
  margin: 0 auto;
  width: min(78%, 330px);
  color: var(--ggw-lacquer-ink);
}

body[data-skin="grand-view-garden"] .ggw-verdict-art svg {
  display: block;
  width: 100%;
  height: auto;
  opacity: .92;
}

body[data-skin="grand-view-garden"] .ggw-verdict .ra { fill: #C97E6F; }

body[data-skin="grand-view-garden"] .ggw-verdict-image {
  margin: 18px 0 0;
  color: #9DBBAA;
  font-size: 13px;
  letter-spacing: .5em;
  text-indent: .5em;
}

body[data-skin="grand-view-garden"] .ggw-verdict-name {
  margin: 12px 0 0;
  font-size: clamp(36px, 9.5vw, 52px);
  font-weight: 500;
  letter-spacing: .14em;
  text-indent: .14em;
  line-height: 1.2;
}

body[data-skin="grand-view-garden"] .ggw-verdict-motto {
  margin: 10px 0 0;
  color: #C9CDB9;
  font-size: 14.5px;
  letter-spacing: .12em;
}

body[data-skin="grand-view-garden"] .ggw-verdict-keys {
  margin: 18px 0 0;
  color: #9DA79B;
  font-size: 12.5px;
  letter-spacing: .24em;
}

body[data-skin="grand-view-garden"] .ggw-verdict-seal {
  position: absolute;
  top: 18px;
  right: 18px;
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  background: var(--ggw-rouge);
  color: var(--ggw-paper-lift);
  font-size: 15px;
  border-radius: 2px;
}

/* 签文（分享句） */
body[data-skin="grand-view-garden"] .ggw-verse {
  margin: 30px 0 0;
  padding: 22px 18px;
  border-top: 1px solid var(--ggw-line);
  border-bottom: 1px solid var(--ggw-line);
  text-align: center;
}

body[data-skin="grand-view-garden"] .ggw-verse blockquote {
  margin: 0;
  font-size: clamp(18px, 5vw, 22px);
  letter-spacing: .18em;
  line-height: 1.9;
}

body[data-skin="grand-view-garden"] .ggw-energy {
  margin: 26px 2px 0;
  font-size: 16px;
  line-height: 2;
  letter-spacing: .03em;
}

body[data-skin="grand-view-garden"] .ggw-reading {
  margin: 14px 2px 0;
  color: color-mix(in srgb, var(--ggw-ink) 88%, var(--ggw-ink-soft));
  font-size: 14.5px;
  line-height: 2.1;
  text-align: justify;
}

body[data-skin="grand-view-garden"] .ggw-cols {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px 26px;
  margin: 30px 2px 0;
  padding-top: 24px;
  border-top: 1px solid color-mix(in srgb, var(--ggw-line) 70%, transparent);
}

body[data-skin="grand-view-garden"] .ggw-col h3 {
  margin: 0 0 8px;
  color: var(--ggw-dai);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: .4em;
}

body[data-skin="grand-view-garden"] .ggw-col p {
  margin: 0;
  color: var(--ggw-ink-soft);
  font-size: 13.5px;
  line-height: 1.95;
}

body[data-skin="grand-view-garden"] .ggw-col ul {
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--ggw-ink-soft);
  font-size: 13.5px;
  line-height: 1.6;
}

body[data-skin="grand-view-garden"] .ggw-col li {
  margin: 0 0 8px;
  padding-left: 14px;
  position: relative;
}

body[data-skin="grand-view-garden"] .ggw-col li::before {
  content: "";
  position: absolute;
  left: 0;
  top: .62em;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--ggw-dai) 55%, transparent);
}

body[data-skin="grand-view-garden"] .ggw-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 26px;
  margin: 34px 2px 0;
}

body[data-skin="grand-view-garden"] .ggw-disclaimer {
  margin-top: 30px;
  padding-top: 16px;
  border-top: 1px solid color-mix(in srgb, var(--ggw-line) 60%, transparent);
  font-size: 11.5px;
  opacity: .8;
}

/* ---------------------------------------------------------------- 窄屏 ---- */
@media (max-width: 420px) {
  body[data-skin="grand-view-garden"] .ggw { padding: 18px 16px 40px; }
  body[data-skin="grand-view-garden"] .ggw-cols { grid-template-columns: 1fr; }
  body[data-skin="grand-view-garden"] .ggw-gate-form { flex-direction: column; }
  body[data-skin="grand-view-garden"] .ggw-slip { padding: 15px 14px; }
  body[data-skin="grand-view-garden"] .ggw-verdict { padding: 24px 18px 28px; }
}

/* ---------------------------------------------------------------- 动效偏好 ---- */
@media (prefers-reduced-motion: reduce) {
  body[data-skin="grand-view-garden"] .ggw-slip,
  body[data-skin="grand-view-garden"] .ggw-dot.now,
  body[data-skin="grand-view-garden"] .ggw-loading-ring,
  body[data-skin="grand-view-garden"] .ggw-slip.stamped .ggw-slip-seal {
    animation: none;
  }
  body[data-skin="grand-view-garden"] .ggw-slip.stamped .ggw-slip-seal {
    opacity: 1;
    transform: translateY(-50%) scale(1);
  }
  body[data-skin="grand-view-garden"] .ggw-slip { transition: none; }
}

