            <path d="M136 140h148M144 150h132" stroke-width="1" opacity=".55"/>
            <path d="M76 128v-40M94 128v-40M64 92h42" stroke-width="1.2" opacity=".65"/>
            <path d="M328 128v-34M344 128v-34M322 98h44" stroke-width="1.2" opacity=".65"/>
          </g>
          <rect class="ra-fill" x="205" y="94" width="12" height="12"/>
        </svg>
      </figure>
      <div class="pp-invite-actions">
        <button class="pp-btn-outline" id="pp-accept">接受邀请</button>
      </div>
      <p class="pp-foot">十八个场合 · 约六分钟 · 原创象征性娱乐内容，不是心理测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#pp-accept").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ---------------------------------------------------------- 场合 ---- */
const REPLY_MARKS = ["A", "B", "C", "D"];

function questionView(ctx) {
  const lines = ctx.options.map((text, i) => `
    <button class="pp-reply${ctx.selected === i ? " inked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="pp-reply-letter" aria-hidden="true">${REPLY_MARKS[i] || "A"}</span>
      <span class="pp-reply-text">${esc(text)}</span>
      <span class="pp-reply-mark" aria-hidden="true"></span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`第 ${roman(ctx.index + 1)} 场 · 共 ${roman(ctx.total)} 场`)}
    ${ruled(ctx.total, ctx.index)}
    <section class="pp-q">
      <p class="pp-q-kicker">Occasion ${roman(ctx.index + 1)} of ${roman(ctx.total)}</p>
      <h2 class="pp-q-text">${esc(ctx.question)}</h2>
      <div class="pp-replies">${lines}</div>
      <div class="pp-q-nav">
        <button class="pp-link" id="pp-prev" ${ctx.index === 0 ? "disabled" : ""}>回看上一场</button>
        <button class="pp-link" id="pp-exit">告辞</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".pp-reply").forEach((reply) => {
      reply.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        reply.classList.add("inked");
        reply.setAttribute("aria-pressed", "true");
        // 落墨一瞬再翻页：让回帖有一个可见的落点。
        window.setTimeout(() => ctx.select(Number(reply.dataset.i)), 300);
      });
    });
    const prev = root.querySelector("#pp-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#pp-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

/* -------------------------------------------------------- 等待 ---- */
function resultLoadingView() {
  const html = pageShell(`
    ${brandBar("社交季将尽")}
    <section class="pp-card pp-loading">
      <p class="pp-eyebrow">The card is on its way</p>
      <p class="pp-loading-text">名帖正在送达……</p>
      <p class="pp-foot">判定在服务端完成。</p>
    </section>`);
  return { html };
}

/* ------------------------------------------------- 名帖与书翰 ---- */
function splitList(value) {
  return String(value || "")
    .split(/[,，;；]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function verdictView(ctx) {
  const result = ctx.result || {};
  const [imageLabel, ...rest] = String(result.subtitle || "").split("：");
  const motto = rest.join("：");
  const strengths = splitList(result.strengths);
  const blindSpots = splitList(result.blind_spots);

  const html = pageShell(`
    ${brandBar("社交季将尽")}
    <section class="pp-result">
      <p class="pp-eyebrow">The calling card · 名帖</p>
      <article class="pp-card pp-calling-card">
        <p class="pp-card-label">${esc(imageLabel || "门厅留言")}</p>
        <h2 class="pp-card-name">${esc(result.name || "")}</h2>
        ${motto ? `<p class="pp-card-motto">${esc(motto)}</p>` : ""}
        <p class="pp-card-keys">${(result.keywords || []).map(esc).join(" · ")}</p>
      </article>
      <figure class="pp-vignette">${vignette(result.id)}</figure>
      <article class="pp-letter">
        <p class="pp-letter-caption">A letter, unsigned · 一封未署名的信</p>
        <blockquote class="pp-verse">${esc(result.share_line || "")}</blockquote>
        <p class="pp-energy">${esc(result.core_energy || "")}</p>
        <p class="pp-reading">${esc(result.reading || "")}</p>
        <div class="pp-cols">
          ${result.relationship_style ? `<div class="pp-col"><h3>相处方式</h3><p>${esc(result.relationship_style)}</p></div>` : ""}
          ${result.inner_conflict ? `<div class="pp-col"><h3>内里张力</h3><p>${esc(result.inner_conflict)}</p></div>` : ""}
          ${strengths.length ? `<div class="pp-col"><h3>所长</h3><ul>${strengths.map((s) => `<li>${esc(s)}</li>`).join("")}</ul></div>` : ""}
          ${blindSpots.length ? `<div class="pp-col"><h3>所蔽</h3><ul>${blindSpots.map((s) => `<li>${esc(s)}</li>`).join("")}</ul></div>` : ""}
        </div>
      </article>
      <div class="pp-actions">
        <button class="pp-link" id="pp-copy">抄录这封信</button>
        <button class="pp-link" id="pp-share">存一张名帖</button>
        <button class="pp-link" id="pp-again">再赴一场</button>
        <button class="pp-link" id="pp-home">告辞</button>
      </div>
      <p class="pp-foot pp-disclaimer">${esc(ctx.disclaimer || "")}</p>
    </section>`);

  const bind = (root) => {
    const copy = root.querySelector("#pp-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已抄录";
      window.setTimeout(() => { copy.textContent = "抄录这封信"; }, 1800);
    });
    root.querySelector("#pp-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#pp-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#pp-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享名帖 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const ctx2d = canvas.getContext("2d");
  const IVORY = "#F8F5ED";
  const INK = "#26262B";
  const SOFT = "#6B6A72";
  const BURGUNDY = "#7A3B44";

  ctx2d.fillStyle = IVORY;
  ctx2d.fillRect(0, 0, 900, 1200);

  // 双细线框（engraved invitation 边框）
  ctx2d.strokeStyle = INK;
  ctx2d.lineWidth = 2;
  ctx2d.strokeRect(60, 60, 780, 1080);
  ctx2d.lineWidth = 1;
  ctx2d.strokeRect(74, 74, 752, 1052);

  const center = (text, y, font, color) => {
    ctx2d.font = font;
    ctx2d.fillStyle = color;
    ctx2d.textAlign = "center";
    ctx2d.fillText(text, 450, y);
  };

  center("THE CALLING CARD", 200, "300 22px Georgia, serif", SOFT);
  const [imageLabel, ...rest] = String(result.subtitle || "").split("：");
  center(imageLabel || "", 268, "300 28px 'Songti SC', 'SimSun', serif", BURGUNDY);
  center(result.name || "", 380, "500 84px 'Songti SC', 'SimSun', serif", INK);
  center(rest.join("：") || "", 450, "italic 300 30px Georgia, 'Songti SC', serif", SOFT);

  // 名帖分隔细线
  ctx2d.strokeStyle = SOFT;
  ctx2d.lineWidth = 1;
  ctx2d.beginPath();
  ctx2d.moveTo(320, 510);
  ctx2d.lineTo(580, 510);
  ctx2d.stroke();
  center((result.keywords || []).join(" · "), 560, "300 26px 'Songti SC', 'SimSun', serif", SOFT);

  // 信笺引言
  center("A LETTER, UNSIGNED", 700, "300 18px Georgia, serif", BURGUNDY);
  const shareLine = result.share_line || "";
  center(shareLine, 780, "italic 300 40px Georgia, 'Songti SC', serif", INK);

  // 火漆式方印
  ctx2d.fillStyle = BURGUNDY;
  ctx2d.fillRect(426, 940, 48, 48);
  ctx2d.fillStyle = IVORY;
  ctx2d.font = "500 28px Georgia, serif";
  ctx2d.fillText("P", 450, 974);

  center("傲慢与偏见 · 靠近方式 · 原创互动测试", 1100, "300 22px 'Songti SC', 'SimSun', serif", SOFT);

  canvas.toBlob((blob) => {
    if (!blob) return;
    const link = document.createElement("a");
    link.download = `pride-prejudice-${result.id || "calling-card"}.png`;
    link.href = URL.createObjectURL(blob);
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }, "image/png");
}

/* ------------------------------------------------------------- 出口 ---- */
export default {
  id: SKIN_ID,
  title: "傲慢与偏见 · 靠近方式 · Mythic",
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
  copyText(result) {
    return `${result.name || ""}｜${result.subtitle || ""}\n${result.share_line || ""}\n—— 傲慢与偏见 · 靠近方式 · 原创互动测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
};

input.content:
/* 傲慢与偏见 · 靠近方式 —— 产品视觉层样式
 *
 * 作用域：全部规则挂在 body[data-skin="pride-prejudice"] 下，只在皮肤
 * 页面被 body 标记激活，与默认模板、希腊女神、大观园完全隔离。
 *
 * 世界观：摄政时代社交季。暖象牙、墨黑、哑波尔多、灰蓝四个颜色；
 * 双细线框（engraved invitation 边框语汇）贯穿邀请函、名帖与信笺；
 * 进度是社交季记事簿（罗马数字 + 十八道墨杠），选项是信纸上的回帖行，
 * 结果是留在门厅的名帖 + 一封未署名的信。
 * 刻意避开：卡牌翻转、判词漆签、羊皮纸羽毛笔、洛可可花边、游戏 UI。
 */

body[data-skin="pride-prejudice"] {
  --pp-ivory: #F8F5ED;
  --pp-card: #FDFBF4;
  --pp-ink: #26262B;
  --pp-soft: #6B6A72;
  --pp-burgundy: #7A3B44;
  --pp-blue: #66798E;
  --pp-hairline: #D9D3C6;
  --pp-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;

  margin: 0;
  color: var(--pp-ink);
  font-family: var(--pp-serif);
  background-color: var(--pp-ivory);
  background-image:
    radial-gradient(1100px 540px at 50% -8%, rgba(255, 255, 250, .95), transparent 70%),
    repeating-linear-gradient(0deg, transparent 0 3px, rgba(90, 88, 84, .01) 3px 4px);
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="pride-prejudice"] .pp {
  max-width: 660px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 22px 22px 48px;
}

body[data-skin="pride-prejudice"] .pp-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 40px;
  color: var(--pp-soft);
  font-size: 12px;
  letter-spacing: .2em;
}

body[data-skin="pride-prejudice"] .pp-brand {
  color: var(--pp-ink);
  font-weight: 600;
  letter-spacing: .18em;
}

body[data-skin="pride-prejudice"] .pp-eyebrow {
  margin: 0 0 14px;
  color: var(--pp-burgundy);
  font: 400 11px/1 Georgia, serif;
  letter-spacing: .34em;
  text-transform: uppercase;
}

body[data-skin="pride-prejudice"] .pp-foot {
  margin: 32px 0 0;
  color: var(--pp-soft);
  font-size: 12px;
  line-height: 1.9;
  letter-spacing: .05em;
}

/* ------------------------------------------------- 双细线框卡 ---- */
body[data-skin="pride-prejudice"] .pp-card {
  position: relative;
  margin: 0 auto;
  padding: 36px 30px;
  border: 1px solid color-mix(in srgb, var(--pp-ink) 62%, transparent);
  background: var(--pp-card);
  box-shadow: 0 1px 0 rgba(70, 66, 60, .06);
}

/* engraved invitation 的内细线：伪元素画第二道框 */
body[data-skin="pride-prejudice"] .pp-card::after {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid color-mix(in srgb, var(--pp-ink) 30%, transparent);
  pointer-events: none;
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="pride-prejudice"] .pp-btn,
body[data-skin="pride-prejudice"] .pp-btn-outline {
  font-family: var(--pp-serif);
  font-size: 15px;
  letter-spacing: .34em;
  text-indent: .34em;
  cursor: pointer;
  transition: background-color .2s ease, color .2s ease, border-color .2s ease;
}

body[data-skin="pride-prejudice"] .pp-btn {
  padding: 11px 26px;
  border: 1px solid var(--pp-ink);
  background: var(--pp-ink);
  color: var(--pp-ivory);
}

body[data-skin="pride-prejudice"] .pp-btn:hover { background: var(--pp-burgundy); border-color: var(--pp-burgundy); }

body[data-skin="pride-prejudice"] .pp-btn-outline {
  padding: 13px 46px;
  border: 1px solid var(--pp-ink);
  background: transparent;
  color: var(--pp-ink);
}

body[data-skin="pride-prejudice"] .pp-btn-outline:hover {
  background: var(--pp-burgundy);
  border-color: var(--pp-burgundy);
  color: var(--pp-ivory);
}

body[data-skin="pride-prejudice"] .pp-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--pp-ink) 42%, transparent);
  background: transparent;
  color: var(--pp-ink);
  font-family: var(--pp-serif);
  font-size: 13px;
  letter-spacing: .16em;
  cursor: pointer;
}

body[data-skin="pride-prejudice"] .pp-link:hover { color: var(--pp-burgundy); border-color: var(--pp-burgundy); }
body[data-skin="pride-prejudice"] .pp-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 回执 ---- */
body[data-skin="pride-prejudice"] .pp-gate,
body[data-skin="pride-prejudice"] .pp-loading {
  max-width: 440px;
  margin: 10vh auto 0;
  text-align: center;
}

body[data-skin="pride-prejudice"] .pp-display {
  margin: 6px 0 14px;
  font-size: clamp(38px, 9vw, 52px);
  font-weight: 500;
  letter-spacing: .22em;
  text-indent: .22em;
  line-height: 1.1;
}

body[data-skin="pride-prejudice"] .pp-gate-lead {
  margin: 0 0 30px;
  color: var(--pp-soft);
  font-size: 13.5px;
  line-height: 2;
}

body[data-skin="pride-prejudice"] .pp-gate-form {
  display: flex;
  gap: 12px;
  align-items: stretch;
}

body[data-skin="pride-prejudice"] .pp-gate-input {
  flex: 1;
  min-width: 0;
  padding: 12px 4px;
  border: 0;
  border-bottom: 1px solid var(--pp-ink);
  border-radius: 0;
  background: transparent;
  color: var(--pp-ink);
  font: 600 15px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .08em;
  text-transform: uppercase;
}

body[data-skin="pride-prejudice"] .pp-gate-input:focus-visible {
  outline: 0;
  border-bottom: 2px solid var(--pp-burgundy);
}

body[data-skin="pride-prejudice"] .pp-gate-error {
  min-height: 22px;
  margin: 14px 0 0;
  color: var(--pp-burgundy);
  font-size: 13px;
  letter-spacing: .04em;
  text-align: left;
}

/* ---------------------------------------------------------------- 邀请函 ---- */
body[data-skin="pride-prejudice"] .pp-invite {
  margin-top: 4vh;
  max-width: 560px;
  text-align: center;
}

body[data-skin="pride-prejudice"] .pp-invite-title {
  margin: 4px 0 16px;
  font-size: clamp(40px, 10.5vw, 62px);
  font-weight: 500;
  letter-spacing: .14em;
  text-indent: .14em;
  line-height: 1.15;
  white-space: nowrap;
}

body[data-skin="pride-prejudice"] .pp-invite-kicker {
  margin: 0 0 18px;
  color: var(--pp-burgundy);
  font-size: 14.5px;
  letter-spacing: .28em;
  text-indent: .28em;
}

body[data-skin="pride-prejudice"] .pp-invite-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--pp-ink);
  font-size: 15.5px;
  line-height: 2;
}

body[data-skin="pride-prejudice"] .pp-invite-sub {
  margin: 10px auto 0;
  max-width: 26em;
  color: var(--pp-soft);
  font-size: 13px;
  line-height: 1.9;
}

body[data-skin="pride-prejudice"] .pp-estate {
  margin: 26px auto 0;
  width: min(88%, 380px);
  color: var(--pp-ink);
}

body[data-skin="pride-prejudice"] .pp-estate svg { display: block; width: 100%; height: auto; }
body[data-skin="pride-prejudice"] .ra { fill: var(--pp-burgundy); stroke: none; }
body[data-skin="pride-prejudice"] .ra-fill { fill: var(--pp-burgundy); }

body[data-skin="pride-prejudice"] .pp-invite-actions { margin: 24px 0 0; }

/* ------------------------------------------------------ 社交季记事簿 ---- */
body[data-skin="pride-prejudice"] .pp-ledger {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  margin: 0 2px 32px;
}

body[data-skin="pride-prejudice"] .pp-mark {
  width: 10px;
  height: 2px;
  border-radius: 1px;
  background: color-mix(in srgb, var(--pp-ink) 26%, transparent);
}

body[data-skin="pride-prejudice"] .pp-mark.done { background: color-mix(in srgb, var(--pp-ink) 62%, transparent); }

body[data-skin="pride-prejudice"] .pp-mark.now {
  width: 18px;
  height: 3px;
  background: var(--pp-burgundy);
  animation: pp-current 2s ease-in-out infinite;
}

@keyframes pp-current {
  0%, 100% { opacity: 1; }
  50% { opacity: .45; }
}

/* ---------------------------------------------------------------- 场合 ---- */
body[data-skin="pride-prejudice"] .pp-q-kicker {
  margin: 0 0 12px;
  color: var(--pp-burgundy);
  font: 400 12px/1 Georgia, serif;
  letter-spacing: .3em;
  text-transform: uppercase;
}

body[data-skin="pride-prejudice"] .pp-q-text {
  margin: 0 0 30px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--pp-hairline);
  font-size: clamp(22px, 5.6vw, 29px);
  font-weight: 500;
  line-height: 1.75;
  letter-spacing: .02em;
}

/* 回帖：信纸行，不是盒子 —— 与大观园的笺盒区分 */
body[data-skin="pride-prejudice"] .pp-replies {
  display: grid;
  gap: 0;
  border-top: 1px solid var(--pp-hairline);
}

body[data-skin="pride-prejudice"] .pp-reply {
  position: relative;
  display: flex;
  gap: 14px;
  align-items: baseline;
  padding: 19px 6px;
  border: 0;
  border-bottom: 1px solid var(--pp-hairline);
  background: transparent;
  color: var(--pp-ink);
  font-family: var(--pp-serif);
  text-align: left;
  cursor: pointer;
  transition: background-color .18s ease;
  animation: pp-fade-in .45s ease both;
}

body[data-skin="pride-prejudice"] .pp-reply:nth-child(2) { animation-delay: .06s; }
body[data-skin="pride-prejudice"] .pp-reply:nth-child(3) { animation-delay: .12s; }

body[data-skin="pride-prejudice"] .pp-reply:hover { background: color-mix(in srgb, var(--pp-card) 70%, transparent); }

body[data-skin="pride-prejudice"] .pp-reply-letter {
  flex: 0 0 20px;
  color: var(--pp-soft);
  font: 400 14px/1.4 Georgia, serif;
  transition: color .16s ease;
}

body[data-skin="pride-prejudice"] .pp-reply-text {
  font-size: 15px;
  line-height: 1.9;
  letter-spacing: .02em;
}

/* 落墨：回帖行下的波尔多细线扫入，行尾一点墨 */
body[data-skin="pride-prejudice"] .pp-reply-mark {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 1px;
  background: var(--pp-burgundy);
  transform: scaleX(0);
  transform-origin: left;
  pointer-events: none;
}

body[data-skin="pride-prejudice"] .pp-reply.inked { border-bottom-color: transparent; }
body[data-skin="pride-prejudice"] .pp-reply.inked .pp-reply-letter { color: var(--pp-burgundy); font-weight: 700; }
body[data-skin="pride-prejudice"] .pp-reply.inked .pp-reply-text { font-weight: 600; }
body[data-skin="pride-prejudice"] .pp-reply.inked .pp-reply-mark { animation: pp-ink-sweep .34s ease-out both; }

@keyframes pp-ink-sweep {
  0% { transform: scaleX(0); }
  100% { transform: scaleX(1); }
}

@keyframes pp-fade-in {
  0% { opacity: 0; transform: translateY(5px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="pride-prejudice"] .pp-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 28px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="pride-prejudice"] .pp-loading-text {
  margin: 10px 0 4px;
  font-size: 17px;
  letter-spacing: .3em;
  text-indent: .3em;
}

/* ---------------------------------------------------------------- 名帖 ---- */
body[data-skin="pride-prejudice"] .pp-result { margin-top: 2vh; }

body[data-skin="pride-prejudice"] .pp-calling-card {
  max-width: 480px;
  margin-top: 20px;
  padding: 42px 30px 38px;
  text-align: center;
}

body[data-skin="pride-prejudice"] .pp-calling-card .pp-eyebrow { margin-bottom: 10px; }

