/* 傲慢与偏见 · 靠近方式 —— 产品视觉层样式
 *
 * 作用域：全部规则挂在 body[data-skin="pride-prejudice"] 下，只在皮肤
 * 页面被 body 标记激活，与默认模板、希腊女神、大观园完全隔离。
 *
 * 世界观：摄政时代社交季。暖象牙、墨黑、哑波尔多、灰蓝四个颜色；
 * 双细线框（engraved invitation 边框语汇）贯穿邀请函、名帖与信笺；
 * 进度是社交季记事簿（罗马数字 + 十八道墨杠），选项是信纸上的回帖行，
 * 结果是留在门厅的名帖 + 一封未署名的信。
 * 刻意避开：卡牌翻转、判词漆签、羊皮纸羽毛笔、洛可可花边、游戏 UI。
 */

body[data-skin="pride-prejudice"] {
  --pp-ivory: #F8F5ED;
  --pp-card: #FDFBF4;
  --pp-ink: #26262B;
  --pp-soft: #6B6A72;
  --pp-burgundy: #7A3B44;
  --pp-blue: #66798E;
  --pp-hairline: #D9D3C6;
  --pp-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;

  margin: 0;
  color: var(--pp-ink);
  font-family: var(--pp-serif);
  background-color: var(--pp-ivory);
  background-image:
    radial-gradient(1100px 540px at 50% -8%, rgba(255, 255, 250, .95), transparent 70%),
    repeating-linear-gradient(0deg, transparent 0 3px, rgba(90, 88, 84, .01) 3px 4px);
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="pride-prejudice"] .pp {
  max-width: 660px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 22px 22px 48px;
}

body[data-skin="pride-prejudice"] .pp-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 40px;
  color: var(--pp-soft);
  font-size: 12px;
  letter-spacing: .2em;
}

body[data-skin="pride-prejudice"] .pp-brand {
  color: var(--pp-ink);
  font-weight: 600;
  letter-spacing: .18em;
}

body[data-skin="pride-prejudice"] .pp-eyebrow {
  margin: 0 0 14px;
  color: var(--pp-burgundy);
  font: 400 11px/1 Georgia, serif;
  letter-spacing: .34em;
  text-transform: uppercase;
}

body[data-skin="pride-prejudice"] .pp-foot {
  margin: 32px 0 0;
  color: var(--pp-soft);
  font-size: 12px;
  line-height: 1.9;
  letter-spacing: .05em;
}

/* ------------------------------------------------- 双细线框卡 ---- */
body[data-skin="pride-prejudice"] .pp-card {
  position: relative;
  margin: 0 auto;
  padding: 36px 30px;
  border: 1px solid color-mix(in srgb, var(--pp-ink) 62%, transparent);
  background: var(--pp-card);
  box-shadow: 0 1px 0 rgba(70, 66, 60, .06);
}

/* engraved invitation 的内细线：伪元素画第二道框 */
body[data-skin="pride-prejudice"] .pp-card::after {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid color-mix(in srgb, var(--pp-ink) 30%, transparent);
  pointer-events: none;
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="pride-prejudice"] .pp-btn,
body[data-skin="pride-prejudice"] .pp-btn-outline {
  font-family: var(--pp-serif);
  font-size: 15px;
  letter-spacing: .34em;
  text-indent: .34em;
  cursor: pointer;
  transition: background-color .2s ease, color .2s ease, border-color .2s ease;
}

body[data-skin="pride-prejudice"] .pp-btn {
  padding: 11px 26px;
  border: 1px solid var(--pp-ink);
  background: var(--pp-ink);
  color: var(--pp-ivory);
}

body[data-skin="pride-prejudice"] .pp-btn:hover { background: var(--pp-burgundy); border-color: var(--pp-burgundy); }

body[data-skin="pride-prejudice"] .pp-btn-outline {
  padding: 13px 46px;
  border: 1px solid var(--pp-ink);
  background: transparent;
  color: var(--pp-ink);
}

body[data-skin="pride-prejudice"] .pp-btn-outline:hover {
  background: var(--pp-burgundy);
  border-color: var(--pp-burgundy);
  color: var(--pp-ivory);
}

body[data-skin="pride-prejudice"] .pp-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--pp-ink) 42%, transparent);
  background: transparent;
  color: var(--pp-ink);
  font-family: var(--pp-serif);
  font-size: 13px;
  letter-spacing: .16em;
  cursor: pointer;
}

body[data-skin="pride-prejudice"] .pp-link:hover { color: var(--pp-burgundy); border-color: var(--pp-burgundy); }
body[data-skin="pride-prejudice"] .pp-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 回执 ---- */
body[data-skin="pride-prejudice"] .pp-gate,
body[data-skin="pride-prejudice"] .pp-loading {
  max-width: 440px;
  margin: 10vh auto 0;
  text-align: center;
}

body[data-skin="pride-prejudice"] .pp-display {
  margin: 6px 0 14px;
  font-size: clamp(38px, 9vw, 52px);
  font-weight: 500;
  letter-spacing: .22em;
  text-indent: .22em;
  line-height: 1.1;
}

body[data-skin="pride-prejudice"] .pp-gate-lead {
  margin: 0 0 30px;
  color: var(--pp-soft);
  font-size: 13.5px;
  line-height: 2;
}

body[data-skin="pride-prejudice"] .pp-gate-form {
  display: flex;
  gap: 12px;
  align-items: stretch;
}

body[data-skin="pride-prejudice"] .pp-gate-input {
  flex: 1;
  min-width: 0;
  padding: 12px 4px;
  border: 0;
  border-bottom: 1px solid var(--pp-ink);
  border-radius: 0;
  background: transparent;
  color: var(--pp-ink);
  font: 600 15px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .08em;
  text-transform: uppercase;
}

body[data-skin="pride-prejudice"] .pp-gate-input:focus-visible {
  outline: 0;
  border-bottom: 2px solid var(--pp-burgundy);
}

body[data-skin="pride-prejudice"] .pp-gate-error {
  min-height: 22px;
  margin: 14px 0 0;
  color: var(--pp-burgundy);
  font-size: 13px;
  letter-spacing: .04em;
  text-align: left;
}

/* ---------------------------------------------------------------- 邀请函 ---- */
body[data-skin="pride-prejudice"] .pp-invite {
  margin-top: 4vh;
  max-width: 560px;
  text-align: center;
}

body[data-skin="pride-prejudice"] .pp-invite-title {
  margin: 4px 0 16px;
  font-size: clamp(40px, 10.5vw, 62px);
  font-weight: 500;
  letter-spacing: .14em;
  text-indent: .14em;
  line-height: 1.15;
  white-space: nowrap;
}

body[data-skin="pride-prejudice"] .pp-invite-kicker {
  margin: 0 0 18px;
  color: var(--pp-burgundy);
  font-size: 14.5px;
  letter-spacing: .28em;
  text-indent: .28em;
}

body[data-skin="pride-prejudice"] .pp-invite-lead {
  margin: 0 auto;
  max-width: 26em;
