  color: var(--pp-ink);
}

body[data-skin="pride-prejudice"] .pp-estate svg { display: block; width: 100%; height: auto; }
body[data-skin="pride-prejudice"] .ra { fill: var(--pp-burgundy); stroke: none; }
body[data-skin="pride-prejudice"] .ra-fill { fill: var(--pp-burgundy); }

body[data-skin="pride-prejudice"] .pp-invite-actions { margin: 24px 0 0; }

/* ------------------------------------------------------ 社交季记事簿 ---- */
body[data-skin="pride-prejudice"] .pp-ledger {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  margin: 0 2px 32px;
