/* ---------------------------------------------------------- 场合 ---- */
const REPLY_MARKS = ["A", "B", "C", "D"];

function questionView(ctx) {
  const lines = ctx.options.map((text, i) => `
    <button class="pp-reply${ctx.selected === i ? " inked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="pp-reply-letter" aria-hidden="true">${REPLY_MARKS[i] || "A"}</span>
      <span class="pp-reply-text">${esc(text)}</span>
      <span class="pp-reply-mark" aria-hidden="true"></span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`第 ${roman(ctx.index + 1)} 场 · 共 ${roman(ctx.total)} 场`)}
    ${ruled(ctx.total, ctx.index)}
    <section class="pp-q">
      <p class="pp-q-kicker">Occasion ${roman(ctx.index + 1)} of ${roman(ctx.total)}</p>
      <h2 class="pp-q-text">${esc(ctx.question)}</h2>
      <div class="pp-replies">${lines}</div>
      <div class="pp-q-nav">
        <button class="pp-link" id="pp-prev" ${ctx.index === 0 ? "disabled" : ""}>回看上一场</button>
        <button class="pp-link" id="pp-exit">告辞</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".pp-reply").forEach((reply) => {
      reply.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        reply.classList.add("inked");
        reply.setAttribute("aria-pressed", "true");
        // 落墨一瞬再翻页：让回帖有一个可见的落点。
        window.setTimeout(() => ctx.select(Number(reply.dataset.i)), 300);
      });
    });
    const prev = root.querySelector("#pp-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#pp-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

