/* ---------------------------------------------------------------- 名帖 ---- */
body[data-skin="pride-prejudice"] .pp-result { margin-top: 2vh; }

body[data-skin="pride-prejudice"] .pp-calling-card {
  max-width: 480px;
  margin-top: 20px;
  padding: 42px 30px 38px;
  text-align: center;
}

body[data-skin="pride-prejudice"] .pp-calling-card .pp-eyebrow { margin-bottom: 10px; }

body[data-skin="pride-prejudice"] .pp-card-label {
  margin: 0 0 14px;
  color: var(--pp-burgundy);
  font-size: 12.5px;
  letter-spacing: .44em;
  text-indent: .44em;
}

body[data-skin="pride-prejudice"] .pp-card-name {
  margin: 0;
  font-size: clamp(32px, 8.5vw, 46px);
  font-weight: 500;
  letter-spacing: .16em;
  text-indent: .16em;
  line-height: 1.25;
}

body[data-skin="pride-prejudice"] .pp-card-motto {
  margin: 12px 0 0;
  color: var(--pp-soft);
  font-style: italic;
  font-size: 14px;
  letter-spacing: .1em;
}

body[data-skin="pride-prejudice"] .pp-card-keys {
  margin: 20px 0 0;
  padding-top: 16px;
  border-top: 1px solid var(--pp-hairline);
  color: var(--pp-blue);
  font-size: 12.5px;
  letter-spacing: .22em;
}

/* ------------------------------------------------------------ 小品 ---- */
body[data-skin="pride-prejudice"] .pp-vignette {
  margin: 26px auto 0;
  width: min(64%, 300px);
  color: var(--pp-ink);
  opacity: .9;
}

body[data-skin="pride-prejudice"] .pp-vignette svg { display: block; width: 100%; height: auto; }

/* ------------------------------------------------------------ 信笺 ---- */
body[data-skin="pride-prejudice"] .pp-letter {
  max-width: 560px;
  margin: 26px auto 0;
  padding: 34px 30px 30px;
  border: 1px solid var(--pp-hairline);
  border-top: 2px solid color-mix(in srgb, var(--pp-blue) 55%, transparent);
  background: var(--pp-card);
}

body[data-skin="pride-prejudice"] .pp-letter-caption {
  margin: 0 0 18px;
  color: var(--pp-blue);
  font: 400 11px/1 Georgia, serif;
  letter-spacing: .3em;
  text-transform: uppercase;
  text-align: center;
}

body[data-skin="pride-prejudice"] .pp-verse {
  margin: 0 0 22px;
  padding: 0 6px;
  color: var(--pp-ink);
  font-style: italic;
  font-size: clamp(17px, 4.6vw, 20px);
  line-height: 1.9;
  letter-spacing: .08em;
  text-align: center;
}

body[data-skin="pride-prejudice"] .pp-energy {
  margin: 0 0 14px;
  font-size: 15.5px;
  line-height: 2;
}

body[data-skin="pride-prejudice"] .pp-reading {
  margin: 0;
  color: color-mix(in srgb, var(--pp-ink) 86%, var(--pp-soft));
  font-size: 14px;
  line-height: 2.1;
  text-align: justify;
}

body[data-skin="pride-prejudice"] .pp-cols {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px 28px;
  margin: 26px 0 0;
  padding-top: 22px;
  border-top: 1px solid var(--pp-hairline);
}

body[data-skin="pride-prejudice"] .pp-col h3 {
  margin: 0 0 8px;
  color: var(--pp-burgundy);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .36em;
}

body[data-skin="pride-prejudice"] .pp-col p {
  margin: 0;
  color: var(--pp-soft);
  font-size: 13px;
  line-height: 1.95;
}

body[data-skin="pride-prejudice"] .pp-col ul {
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--pp-soft);
  font-size: 13px;
  line-height: 1.6;
}

body[data-skin="pride-prejudice"] .pp-col li {
  margin: 0 0 7px;
  padding-left: 14px;
  position: relative;
}

body[data-skin="pride-prejudice"] .pp-col li::before {
  content: "";
  position: absolute;
  left: 0;
  top: .6em;
  width: 10px;
  height: 1px;
  background: color-mix(in srgb, var(--pp-blue) 75%, transparent);
}

body[data-skin="pride-prejudice"] .pp-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 26px;
  margin: 32px 2px 0;
}

body[data-skin="pride-prejudice"] .pp-disclaimer {
  margin-top: 28px;
  padding-top: 16px;
  border-top: 1px solid var(--pp-hairline);
  font-size: 11.5px;
  opacity: .85;
}

/* ---------------------------------------------------------------- 窄屏 ---- */
@media (max-width: 420px) {
  body[data-skin="pride-prejudice"] .pp { padding: 18px 15px 40px; }
  body[data-skin="pride-prejudice"] .pp-card { padding: 28px 18px; }
  body[data-skin="pride-prejudice"] .pp-cols { grid-template-columns: 1fr; }
  body[data-skin="pride-prejudice"] .pp-gate-form { flex-direction: column; }
  body[data-skin="pride-prejudice"] .pp-letter { padding: 26px 18px 22px; }
}

/* ---------------------------------------------------------------- 动效偏好 ---- */
@media (prefers-reduced-motion: reduce) {
  body[data-skin="pride-prejudice"] .pp-reply,
  body[data-skin="pride-prejudice"] .pp-mark.now,
  body[data-skin="pride-prejudice"] .pp-reply.inked .pp-reply-mark {
    animation: none;
  }
  body[data-skin="pride-prejudice"] .pp-reply.inked .pp-reply-mark { transform: scaleX(1); }
  body[data-skin="pride-prejudice"] .pp-reply { transition: none; }
}

