/* 傲慢与偏见 · 靠近方式 —— 产品视觉层（product skin）
 *
 * 公共引擎（app.js）负责 license、路由、题库与服务端评分；本文件只做这个
 * 产品的艺术表达。世界观：摄政时代的一个社交季——
 *   进入 = 一封邀请函（双细线框，engraved invitation 语汇）
 *   答题 = 社交季的十八个场合，作答即回帖（信纸行式，罗马数字记事簿进度）
 *   结果 = 一张留在门厅的名帖（calling card）+ 一封未署名的私人信件
 * 约束与大观园皮肤相同：只读 ctx 提供的数据与回调；样式全部挂在
 * body[data-skin="pride-prejudice"] 作用域下；无评分、无网络、无图片资产。
 */

const SKIN_ID = "pride-prejudice";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

/* ------------------------------------------------------ 罗马数字 ---- */
function roman(n) {
  const table = [[10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"]];
  let out = "";
  let rest = n;
  for (const [value, glyph] of table) {
    while (rest >= value) { out += glyph; rest -= value; }
  }
  return out || "I";
}

/* 结果意象：每位一幅社交季小品（极简线描， estates & drawing-room）。
   不画人物，器物与建筑暗示。 */
const ART = {
  elizabeth: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round">
        <rect x="140" y="36" width="120" height="122"/>
        <path d="M200 36v122M140 97h120" stroke-width="1" opacity=".5"/>
        <path d="M140 36l-26 14M260 36l26 14" stroke-width="1.2" opacity=".7"/>
        <path d="M126 158h148" stroke-width="1.4"/>
        <path d="M170 176c30-6 60-24 88-44" stroke-width="1.2" opacity=".6"/>
        <path d="M170 176c34-2 66-12 96-24" stroke-width="1" opacity=".35"/>
      </g>
      <circle class="ra" cx="304" cy="118" r="4"/>
    </svg>`,
  jane: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round">
        <path d="M96 128h208" stroke-width="1.4"/>
        <path d="M84 128v10h232v-10" stroke-width="1" opacity=".5"/>
        <path d="M156 128v-18c0-6 6-10 12-10h4c6 0 12 4 12 10v18" />
        <path d="M184 116c10-2 14 2 12 8" stroke-width="1.2"/>
        <path d="M232 128v-18c0-6 6-10 12-10h4c6 0 12 4 12 10v18"/>
        <path d="M166 84c-4-8 2-12-2-20M242 84c-4-8 2-12-2-20" stroke-width="1" opacity=".55"/>
      </g>
      <circle class="ra" cx="204" cy="104" r="4"/>
    </svg>`,
  charlotte: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round">
        <path d="M148 66l52-28 52 28" />
        <path d="M156 66v88M200 66v88M244 66v88" stroke-width="1.5"/>
        <path d="M140 154h120" stroke-width="1.4"/>
        <path d="M148 170h104M156 184h88" stroke-width="1" opacity=".55"/>
        <path d="M292 158v-34M306 158v-34M320 158v-34M286 130h42" stroke-width="1.2" opacity=".7"/>
      </g>
      <circle class="ra" cx="200" cy="120" r="4"/>
    </svg>`,
  lydia: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round">
        <path d="M200 170V72" />
        <path d="M200 108c-26 0-44-12-52-30M200 96c24 0 40-10 48-26" stroke-width="1.5"/>
        <path d="M148 78c-4-6-4-12 0-18M248 70c-4-6-4-10 0-16" stroke-width="1.2"/>
        <path d="M200 72c-5-8-5-14 0-22" stroke-width="1.2"/>
        <path d="M120 184c40-10 120-10 160 0" stroke-width="1" opacity=".5"/>
      </g>
      <circle class="ra" cx="200" cy="44" r="4"/>
    </svg>`,
  anne: `
    <svg viewBox="0 0 400 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round">
        <rect x="150" y="30" width="76" height="140" rx="6"/>
        <circle cx="188" cy="66" r="16" stroke-width="1.4"/>
        <path d="M188 82v34" stroke-width="1.4"/>
        <circle cx="188" cy="120" r="5" stroke-width="1.2"/>
        <path d="M142 170h92" stroke-width="1.4"/>
        <rect x="268" y="112" width="52" height="66" transform="rotate(8 294 145)" stroke-width="1.3"/>
        <path d="M276 128l42 6" stroke-width="1" opacity=".5"/>
      </g>
      <circle class="ra" cx="188" cy="66" r="3.5"/>
    </svg>`,
};

function vignette(resultId) {
  return ART[resultId] || ART.anne;
}

/* --------------------------------------------------------- 公共件 ---- */
function brandBar(right) {
  return `<header class="pp-top"><span class="pp-brand">傲慢与偏见 · 靠近方式</span><span class="pp-top-right">${right}</span></header>`;
}

function pageShell(inner) {
  return `<div class="pp">${inner}</div>`;
}

function ruled(total, current) {
  const marks = [];
  for (let i = 0; i < total; i += 1) {
    const state = i < current ? " done" : i === current ? " now" : "";
    marks.push(`<i class="pp-mark${state}"></i>`);
  }
  return `<div class="pp-ledger" role="progressbar" aria-label="社交季记事簿" aria-valuemin="1" aria-valuemax="${total}" aria-valuenow="${current + 1}">${marks.join("")}</div>`;
}

/* ------------------------------------------------------- R.S.V.P. ---- */
const GATE_ERRORS = {
  empty: "请先写下回执编号。",
  already_bound: "此帖已在别的浏览器应允。如需更换设备，请联系卖家重置绑定。",
  rate_limited: "回执过于频繁，请片刻后再来。",
  invalid: "回执编号无效，请核对后重新输入。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("R.S.V.P.")}
    <section class="pp-card pp-gate">
      <p class="pp-eyebrow">R.S.V.P.</p>
      <h1 class="pp-display">呈递回执</h1>
      <p class="pp-gate-lead">凭兑换码入席。应允之后与当前浏览器绑定，此后赴会不必再验。</p>
      <div class="pp-gate-form">
        <input id="pp-gate-code" class="pp-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="pp-btn" id="pp-gate-submit">呈递</button>
      </div>
      <p class="pp-gate-error" id="pp-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="pp-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#pp-gate-code");
    const submit = root.querySelector("#pp-gate-submit");
    const error = root.querySelector("#pp-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`此帖属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "回执编号无效，请核对后重新输入。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* -------------------------------------------------------- 邀请函 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("社交季")}
    <section class="pp-card pp-invite">
      <p class="pp-eyebrow">An Invitation · 靠近方式测试</p>
      <h1 class="pp-invite-title">傲慢与偏见</h1>
      <p class="pp-invite-kicker">你怎样靠近一个人？</p>
      <p class="pp-invite-lead">${esc(ctx.theme.title)}</p>
      <p class="pp-invite-sub">${esc(ctx.theme.subtitle)}</p>
      <figure class="pp-estate" aria-hidden="true">
        <svg viewBox="0 0 420 150">
          <g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round">
            <path d="M136 56l74-32 74 32"/>
            <path d="M146 56v72M188 56v72M232 56v72M274 56v72" stroke-width="1.5"/>
            <path d="M128 128h164" stroke-width="1.5"/>
            <path d="M136 140h148M144 150h132" stroke-width="1" opacity=".55"/>
            <path d="M76 128v-40M76 100c-8-4-14-10-16-18M76 108c8-4 14-10 16-18M76 96c-6-6-8-12-8-20" stroke-width="1.2" opacity=".65"/>
            <path d="M328 128v-34M328 106c-6-3-10-8-12-14M328 112c6-3 10-8 12-14" stroke-width="1.2" opacity=".65"/>
          </g>
          <rect class="ra-fill" x="205" y="94" width="12" height="12"/>
        </svg>
      </figure>
      <div class="pp-invite-actions">
        <button class="pp-btn-outline" id="pp-accept">接受邀请</button>
      </div>
      <p class="pp-foot">十八个场合 · 约六分钟 · 原创象征性娱乐内容，不是心理测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#pp-accept").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ---------------------------------------------------------- 场合 ---- */
const REPLY_MARKS = ["A", "B", "C", "D"];

function questionView(ctx) {
  const lines = ctx.options.map((text, i) => `
    <button class="pp-reply${ctx.selected === i ? " inked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="pp-reply-letter" aria-hidden="true">${REPLY_MARKS[i] || "A"}</span>
      <span class="pp-reply-text">${esc(text)}</span>
      <span class="pp-reply-mark" aria-hidden="true"></span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`第 ${roman(ctx.index + 1)} 场 · 共 ${roman(ctx.total)} 场`)}
    ${ruled(ctx.total, ctx.index)}
    <section class="pp-q">
      <p class="pp-q-kicker">Occasion ${roman(ctx.index + 1)} of ${roman(ctx.total)}</p>
      <h2 class="pp-q-text">${esc(ctx.question)}</h2>
      <div class="pp-replies">${lines}</div>
      <div class="pp-q-nav">
        <button class="pp-link" id="pp-prev" ${ctx.index === 0 ? "disabled" : ""}>回看上一场</button>
        <button class="pp-link" id="pp-exit">告辞</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".pp-reply").forEach((reply) => {
      reply.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        reply.classList.add("inked");
        reply.setAttribute("aria-pressed", "true");
        // 落墨一瞬再翻页：让回帖有一个可见的落点。
        window.setTimeout(() => ctx.select(Number(reply.dataset.i)), 300);
      });
    });
    const prev = root.querySelector("#pp-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#pp-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

/* -------------------------------------------------------- 等待 ---- */
function resultLoadingView() {
  const html = pageShell(`
    ${brandBar("社交季将尽")}
    <section class="pp-card pp-loading">
      <p class="pp-eyebrow">The card is on its way</p>
      <p class="pp-loading-text">名帖正在送达……</p>
      <p class="pp-foot">判定在服务端完成。</p>
    </section>`);
  return { html };
}

/* ------------------------------------------------- 名帖与书翰 ---- */
function splitList(value) {
  return String(value || "")
    .split(/[,，;；]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function verdictView(ctx) {
  const result = ctx.result || {};
  const [imageLabel, ...rest] = String(result.subtitle || "").split("：");
  const motto = rest.join("：");
  const strengths = splitList(result.strengths);
  const blindSpots = splitList(result.blind_spots);

  const html = pageShell(`
    ${brandBar("社交季将尽")}
    <section class="pp-result">
      <p class="pp-eyebrow">The calling card · 名帖</p>
      <article class="pp-card pp-calling-card">
        <p class="pp-card-label">${esc(imageLabel || "门厅留言")}</p>
        <h2 class="pp-card-name">${esc(result.name || "")}</h2>
        ${motto ? `<p class="pp-card-motto">${esc(motto)}</p>` : ""}
        <p class="pp-card-keys">${(result.keywords || []).map(esc).join(" · ")}</p>
      </article>
      <figure class="pp-vignette">${vignette(result.id)}</figure>
      <article class="pp-letter">
        <p class="pp-letter-caption">A letter, unsigned</p>
        <p class="pp-letter-cn">一封未署名的信</p>
        <blockquote class="pp-verse">${esc(result.share_line || "")}</blockquote>
        <p class="pp-energy">${esc(result.core_energy || "")}</p>
        <p class="pp-reading">${esc(result.reading || "")}</p>
        <div class="pp-cols">
          ${result.relationship_style ? `<div class="pp-col"><h3>相处方式</h3><p>${esc(result.relationship_style)}</p></div>` : ""}
          ${result.inner_conflict ? `<div class="pp-col"><h3>内里张力</h3><p>${esc(result.inner_conflict)}</p></div>` : ""}
          ${strengths.length ? `<div class="pp-col"><h3>所长</h3><ul>${strengths.map((s) => `<li>${esc(s)}</li>`).join("")}</ul></div>` : ""}
          ${blindSpots.length ? `<div class="pp-col"><h3>所蔽</h3><ul>${blindSpots.map((s) => `<li>${esc(s)}</li>`).join("")}</ul></div>` : ""}
        </div>
      </article>
      <div class="pp-actions">
        <button class="pp-link" id="pp-copy">抄录这封信</button>
        <button class="pp-link" id="pp-share">存一张名帖</button>
        <button class="pp-link" id="pp-again">再赴一场</button>
        <button class="pp-link" id="pp-home">告辞</button>
      </div>
      <p class="pp-foot pp-disclaimer">${esc(ctx.disclaimer || "")}</p>
    </section>`);

  const bind = (root) => {
    const copy = root.querySelector("#pp-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已抄录";
      window.setTimeout(() => { copy.textContent = "抄录这封信"; }, 1800);
    });
    root.querySelector("#pp-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#pp-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#pp-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享名帖 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const ctx2d = canvas.getContext("2d");
  const IVORY = "#F8F5ED";
  const INK = "#26262B";
  const SOFT = "#6B6A72";
  const BURGUNDY = "#7A3B44";

  ctx2d.fillStyle = IVORY;
  ctx2d.fillRect(0, 0, 900, 1200);

  // 双细线框（engraved invitation 边框）
  ctx2d.strokeStyle = INK;
  ctx2d.lineWidth = 2;
  ctx2d.strokeRect(60, 60, 780, 1080);
  ctx2d.lineWidth = 1;
  ctx2d.strokeRect(74, 74, 752, 1052);

  const center = (text, y, font, color) => {
    ctx2d.font = font;
    ctx2d.fillStyle = color;
    ctx2d.textAlign = "center";
    ctx2d.fillText(text, 450, y);
  };

  center("THE CALLING CARD", 200, "300 22px Georgia, serif", SOFT);
  const [imageLabel, ...rest] = String(result.subtitle || "").split("：");
  center(imageLabel || "", 268, "300 28px 'Songti SC', 'SimSun', serif", BURGUNDY);
  center(result.name || "", 380, "500 84px 'Songti SC', 'SimSun', serif", INK);
  center(rest.join("：") || "", 450, "italic 300 30px Georgia, 'Songti SC', serif", SOFT);

  // 名帖分隔细线
  ctx2d.strokeStyle = SOFT;
  ctx2d.lineWidth = 1;
  ctx2d.beginPath();
  ctx2d.moveTo(320, 510);
  ctx2d.lineTo(580, 510);
  ctx2d.stroke();
  center((result.keywords || []).join(" · "), 560, "300 26px 'Songti SC', 'SimSun', serif", SOFT);

  // 信笺引言
  center("A LETTER, UNSIGNED", 700, "300 18px Georgia, serif", BURGUNDY);
  const shareLine = result.share_line || "";
  center(shareLine, 780, "italic 300 40px Georgia, 'Songti SC', serif", INK);

  // 火漆式方印
  ctx2d.fillStyle = BURGUNDY;
  ctx2d.fillRect(426, 940, 48, 48);
  ctx2d.fillStyle = IVORY;
  ctx2d.font = "500 28px Georgia, serif";
  ctx2d.fillText("P", 450, 974);

  center("傲慢与偏见 · 靠近方式 · 原创互动测试", 1100, "300 22px 'Songti SC', 'SimSun', serif", SOFT);

  canvas.toBlob((blob) => {
    if (!blob) return;
    const link = document.createElement("a");
    link.download = `pride-prejudice-${result.id || "calling-card"}.png`;
    link.href = URL.createObjectURL(blob);
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }, "image/png");
}

/* ------------------------------------------------------------- 出口 ---- */
export default {
  id: SKIN_ID,
  title: "傲慢与偏见 · 靠近方式 · Mythic",
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
  copyText(result) {
    return `${result.name || ""}｜${result.subtitle || ""}\n${result.share_line || ""}\n—— 傲慢与偏见 · 靠近方式 · 原创互动测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
};

