// scores 只用 0/1/3；每题恰好有一个"主反应"选项与该公主的主场对应。
const Q = (n, dimension, question, a, b, c, note) => ({
  id: `disney-${String(n).padStart(2, "0")}`,
  dimension,
  question,
  options: [a, b, c].map((text, i) => ({ text, scores: [a, b, c][i].scores ? undefined : undefined, ...{ text, scores: arguments ? undefined : undefined } })).map(() => null) && [
    { text: a.text || a[0], scores: a.scores || Object.fromEntries(a[1]) },
  ] && undefined,
});
// The helper above got unwieldy — build options plainly instead.

function q(n, dimension, question, options, note) {
  return {
    id: `disney-${String(n).padStart(2, "0")}`,
    dimension,
    question,
    options: options.map(([text, scores]) => ({ text, scores: Object.fromEntries(scores) })),
    editor_note: note,
  };
}

