  ], "区分缝隙自留地（爱洛）、体面拿主意（灰姑娘）、翻面重来（梅莉达）。"),

  q(24, "回望", "一年过去，回看这一年的自己——最触动你的是：", [
    ["身边的人都好好的，那一刻最开心。", [["snow-white", 3], ["cinderella", 1], ["moana", 1]]],
    ["我亲手做成了一件原本不敢想的事。", [["tiana", 3], ["mulan", 1], ["merida", 1]]],
    ["那几次说走就走、闪闪发光的瞬间。", [["ariel", 3], ["rapunzel", 1], ["moana", 1]]],
  ], "收尾回望题，呼应三大动机群：照料、成就、体验。"),
];

/* --------------------------------------------------- 边界与可达性 ---- */
const ids = results.map((r) => r.id);

// min/max: per question, the least and the best score the princess can earn.
const bounds = {};
for (const id of ids) {
  let min = 0;
  let max = 0;
  for (const question of questions) {
    const vals = question.options.map((o) => o.scores[id] || 0);
    min += Math.min(...vals);
    max += Math.max(...vals);
  }
  if (max === min) throw new Error(`princess ${id} is unreachable: max === min`);
  bounds[id] = { minimum: min, maximum: max };
}

const quiz = {
  id: "disney-princess",
  title: "你是哪位迪士尼公主？",
  subtitle: "24 个日常情境，认领一位和你最像的公主。",
  disclaimer: "这是受经典童话与动画角色启发的原创娱乐测试，与迪士尼公司无关，也不是心理测评。结果只描述本次选择呈现的一面。",
  results: results.map((r) => ({ ...r })),
  questions,
  scoring: {
    method: "range_normalized_sum",
    answer_requirement: "每题恰选一项，全部题目完成后才计算；不把漏答视为0分。",
    points_per_option: 4,
    component_values: [0, 1, 3],
    missing_result_score: 0,
    formula: "每个结果先累加所选选项中的分数；归一化分 = 100 × (累计分 - minimum) / (maximum - minimum)。",
    normalization_bounds: bounds,
    result_order: ids,
  },
};

// ---- reachability: Monte-Carlo over "clearly leaning to P" answering ----
function simulateReachability(runs = 600, leaningShare = 0.8, seedBase = 20260930) {
  const failures = [];
  for (const id of ids) {
    let wins = 0;
    let bestElse = 0;
    for (let run = 0; run < runs; run += 1) {
      let seed = seedBase + run * 131 + id.length * 977;
      const rand = () => {
        seed = (seed * 1103515245 + 12345) & 0x7fffffff;
        return seed / 0x7fffffff;
      };
      const answers = questions.map((question, qIndex) => {
        const best = question.options
          .map((o, i) => ({ i, s: o.scores[id] || 0 }))
          .sort((a, b) => b.s - a.s);
        const topScore = best[0].s;
        const topOptions = best.filter((b) => b.s === topScore).map((b) => b.i);
        if (rand() < leaningShare) {
          return topOptions[Math.floor(rand() * topOptions.length)];
        }
        return Math.floor(rand() * question.options.length);
      });
      const { winnerId, scores } = selectWinner(quiz, answers);
      if (winnerId === id) wins += 1;
      // measure margin on a fully-leaning run for diagnostics
      if (run === 0) {
        const full = questions.map((question) => {
          const best = question.options
            .map((o, i) => ({ i, s: o.scores[id] || 0 }))
            .sort((a, b) => b.s - a.s)[0];
          return best.i;
        });
        const own = selectWinner(quiz, full).winnerId;
        if (own !== id) failures.push(`${id}: full-leaning run elects ${own}`);
      }
      void bestElse;
      void scores;
    }
    const rate = wins / runs;
    const verdict = rate >= 0.85 ? "OK" : "LOW";
    console.log(`  ${verdict}  ${id.padEnd(12)} win-rate ${(rate * 100).toFixed(1)}%`);
    if (rate < 0.85) failures.push(`${id}: win-rate ${(rate * 100).toFixed(1)}% < 85%`);
  }
  return failures;
}

console.log("[build] normalization bounds:");
for (const id of ids) console.log(`  ${id.padEnd(12)} min=${bounds[id].minimum} max=${bounds[id].maximum}`);
console.log("[build] reachability (600 leaning runs per princess):");
const failures = simulateReachability();
if (failures.length) {
  console.error("[build] FAILURES:\n  " + failures.join("\n  "));
  process.exit(1);
}

// ---- balance: no princess may rely on tie-break (full-leaning must win outright) ----
// (covered above via full-leaning diagnostic)

const out = join(ROOT, "server", "content", "disney_princess.json");
writeFileSync(out, JSON.stringify(quiz, null, 1) + "\n", "utf8");
console.log(`[build] wrote ${out}`);
console.log(`[build] ${results.length} results, ${questions.length} questions`);

