body[data-skin="disney-princess"] .dp-q-count {
  margin: 0 0 10px;
  color: #B867B8;
  font: 700 13px/1 var(--dp-sans);
  letter-spacing: .2em;
}

body[data-skin="disney-princess"] .dp-q-text {
  margin: 0 0 22px;
  padding: 24px 26px;
  border-radius: 24px;
  background: rgba(255, 255, 255, .92);
  box-shadow: 0 12px 30px rgba(120, 90, 160, .14);
  font-size: clamp(20px, 5.4vw, 26px);
  font-weight: 700;
  line-height: 1.65;
}

body[data-skin="disney-princess"] .dp-options {
  display: grid;
  gap: 12px;
}

body[data-skin="disney-princess"] .dp-option {
  display: flex;
  gap: 14px;
  align-items: center;
  padding: 17px 20px;
  border: 2px solid transparent;
  border-radius: 20px;
  background: rgba(255, 255, 255, .92);
  box-shadow: 0 6px 16px rgba(120, 90, 160, .12);
  color: var(--dp-ink);
  font: 400 15px/1.75 var(--dp-sans);
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease, background-color .16s ease;
  animation: dp-rise .4s cubic-bezier(.2, .7, .2, 1) both;
}

body[data-skin="disney-princess"] .dp-option:nth-child(2) { animation-delay: .06s; }
body[data-skin="disney-princess"] .dp-option:nth-child(3) { animation-delay: .12s; }

body[data-skin="disney-princess"] .dp-option:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 24px rgba(120, 90, 160, .18);
  border-color: color-mix(in srgb, var(--dp-accent, #B867B8) 46%, transparent);
}

body[data-skin="disney-princess"] .dp-option-key {
  display: grid;
  flex: 0 0 34px;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 12px;
  background: color-mix(in srgb, var(--dp-accent, #B867B8) 16%, #FFF);
  color: var(--dp-accent, #B867B8);
  font-weight: 800;
  font-size: 14px;
}

body[data-skin="disney-princess"] .dp-option.picked {
  background: var(--dp-accent, #B867B8);
  border-color: var(--dp-accent, #B867B8);
  color: #FFF;
  animation: dp-pop .26s ease;
}

body[data-skin="disney-princess"] .dp-option.picked .dp-option-key { background: rgba(255, 255, 255, .24); color: #FFF; }

@keyframes dp-pop {
  0% { transform: scale(1); }
  55% { transform: scale(1.035); }
  100% { transform: scale(1); }
}

@keyframes dp-rise {
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="disney-princess"] .dp-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 24px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="disney-princess"] .dp-loading {
  max-width: 380px;
  margin: 12vh auto 0;
  padding: 40px 26px;
  border-radius: 28px;
  background: rgba(255, 255, 255, .86);
  box-shadow: 0 18px 44px rgba(120, 90, 160, .18);
  text-align: center;
}

body[data-skin="disney-princess"] .dp-spark {
  width: 84px;
  height: 84px;
  margin: 0 auto;
  color: #E5B23A;
  animation: dp-spin 2.6s cubic-bezier(.4, .1, .6, .9) infinite;
}

body[data-skin="disney-princess"] .dp-spark svg { width: 100%; height: 100%; }

@keyframes dp-spin {
  0% { transform: rotate(0) scale(1); }
  50% { transform: rotate(180deg) scale(.86); }
  100% { transform: rotate(360deg) scale(1); }
}

body[data-skin="disney-princess"] .dp-loading-text {
  margin: 18px 0 4px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: .14em;
}

/* ---------------------------------------------------------------- 结果 ---- */
body[data-skin="disney-princess"] .dp-result {
  margin-top: 1vh;
}

body[data-skin="disney-princess"] .dp-eyebrow {
  margin: 0 0 14px;
  color: var(--dp-soft);
  font: 700 12px/1 var(--dp-sans);
  letter-spacing: .26em;
  text-transform: uppercase;
  text-align: center;
}

body[data-skin="disney-princess"] .dp-portrait {
  position: relative;
  margin: 0 auto;
  max-width: 460px;
  border-radius: 30px;
  overflow: hidden;
  background: linear-gradient(160deg, color-mix(in srgb, var(--dp-accent) 34%, #FFF), #FFF);
  box-shadow: 0 24px 54px color-mix(in srgb, var(--dp-accent) 34%, transparent);
  aspect-ratio: 4 / 5;
}

body[data-skin="disney-princess"] .dp-portrait img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

body[data-skin="disney-princess"] .dp-portrait.dp-no-art { display: grid; place-items: center; }
body[data-skin="disney-princess"] .dp-fallback-star { display: none; font-size: 84px; color: var(--dp-accent); opacity: .8; }
body[data-skin="disney-princess"] .dp-portrait.dp-no-art .dp-fallback-star { display: block; }

body[data-skin="disney-princess"] .dp-name-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 12px;
  margin: 24px 0 6px;
}

body[data-skin="disney-princess"] .dp-name {
  margin: 0;
  font-size: clamp(34px, 9vw, 48px);
  font-weight: 800;
  color: var(--dp-accent);
  letter-spacing: .04em;
}

body[data-skin="disney-princess"] .dp-name-en {
  color: var(--dp-soft);
  font: italic 400 17px/1 Georgia, serif;
  letter-spacing: .06em;
}

body[data-skin="disney-princess"] .dp-verdict {
  margin: 4px auto 0;
  max-width: 28em;
  text-align: center;
  font-size: clamp(17px, 4.8vw, 20px);
  font-weight: 700;
  line-height: 1.7;
}

body[data-skin="disney-princess"] .dp-chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 14px 0 4px;
}

body[data-skin="disney-princess"] .dp-chip {
  padding: 6px 14px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--dp-accent) 14%, #FFF);
  color: color-mix(in srgb, var(--dp-accent) 78%, #222);
  font: 600 12.5px/1.4 var(--dp-sans);
  letter-spacing: .1em;
}

/* 三张彩色圆角卡 */
body[data-skin="disney-princess"] .dp-cards {
  display: grid;
  gap: 14px;
  margin: 24px 0 0;
}

body[data-skin="disney-princess"] .dp-card {
  padding: 20px 22px;
  border-radius: 22px;
  background: rgba(255, 255, 255, .92);
  box-shadow: 0 10px 26px rgba(120, 90, 160, .12);
}

body[data-skin="disney-princess"] .dp-card h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px;
  font-size: 13.5px;
  font-weight: 800;
  letter-spacing: .12em;
}

body[data-skin="disney-princess"] .dp-card h3 svg { width: 18px; height: 18px; }
body[data-skin="disney-princess"] .dp-card p { margin: 0; font-size: 14px; line-height: 1.95; color: var(--dp-ink); }

body[data-skin="disney-princess"] .dp-card-like h3 { color: #D2506E; }
body[data-skin="disney-princess"] .dp-card-like { border-top: 5px solid #F0A2B8; }
body[data-skin="disney-princess"] .dp-card-way h3 { color: #5B82C4; }
body[data-skin="disney-princess"] .dp-card-way { border-top: 5px solid #A9C4E8; }
body[data-skin="disney-princess"] .dp-card-blind h3 { color: #B98A2E; }
body[data-skin="disney-princess"] .dp-card-blind { border-top: 5px solid #EFD48F; }

/* 完整解读折叠 */
body[data-skin="disney-princess"] .dp-more {
  margin: 20px 0 0;
  padding: 16px 20px;
  border-radius: 20px;
  background: rgba(255, 255, 255, .8);
}

body[data-skin="disney-princess"] .dp-more summary {
  color: var(--dp-soft);
  font-weight: 600;
  font-size: 13.5px;
  letter-spacing: .12em;
  cursor: pointer;
}

body[data-skin="disney-princess"] .dp-more[open] summary { margin-bottom: 10px; color: var(--dp-accent); }
body[data-skin="disney-princess"] .dp-reading { margin: 0 0 10px; font-size: 14px; line-height: 2.05; }
body[data-skin="disney-princess"] .dp-basis { margin: 0; color: #8B8994; font-size: 11.5px; line-height: 1.8; }

body[data-skin="disney-princess"] .dp-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px 22px;
  margin: 28px 2px 0;
}

body[data-skin="disney-princess"] .dp-actions .dp-btn { padding: 13px 32px; font-size: 14.5px; }
body[data-skin="disney-princess"] .dp-disclaimer { margin-top: 26px; padding-top: 14px; border-top: 1px dashed rgba(120, 100, 150, .3); }

/* ---------------------------------------------------------------- 窄屏 ---- */
@media (max-width: 420px) {
  body[data-skin="disney-princess"] .dp { padding: 16px 14px 40px; }
  body[data-skin="disney-princess"] .dp-gate-form { flex-direction: column; }
  body[data-skin="disney-princess"] .dp-cover { padding: 30px 18px 28px; }
  body[data-skin="disney-princess"] .dp-card { padding: 17px 16px; }
}

/* ---------------------------------------------------------------- 动效偏好 ---- */
@media (prefers-reduced-motion: reduce) {
  body[data-skin="disney-princess"] .dp-dots i,
  body[data-skin="disney-princess"] .dp-spark,
  body[data-skin="disney-princess"] .dp-option,
  body[data-skin="disney-princess"] .dp-option.picked { animation: none; }
  body[data-skin="disney-princess"] .dp-btn,
  body[data-skin="disney-princess"] .dp-option,
  body[data-skin="disney-princess"] .dp-cast-dot { transition: none; }
}

part.text:
skin.css 里我不小心复制了两行 pride-prejudice 的选择器（复制粘贴失误）：

```css
body[data-skin="pride-prejudice"] .pp-gate-form,
body[data-skin="disney-princess"] .dp-gate-form {
  display: flex;
  gap: 10px;
}

body[data-skin="disney-princess"] .dp-gate-form { display: flex; gap: 10px; }
```

第一段给 pride-prejudice 的 .pp-gate-form 加了 display:flex gap 10px——会改 PP 的样式！违反"不改傲慢与偏见"。删掉这两段，只留 dp 的。

