function q(n, dimension, question, options, note) {
  return {
    id: `disney-${String(n).padStart(2, "0")}`,
    dimension,
    question,
    options: options.map(([text, scores]) => ({ text, scores: Object.fromEntries(scores) })),
    editor_note: note,
  };
}

