const sha256 = (buf) => createHash("sha256").update(buf).digest("hex");

async function uploadRef(path, label) {
  const bytes = readFileSync(path);
  const form = new FormData();
  form.append("reqtype", "fileupload");
  form.append("time", "72h");
  form.append("fileToUpload", new Blob([bytes], { type: "image/png" }), `${label}.png`);
  const res = await fetch(UPLOAD, { method: "POST", body: form });
  const url = (await res.text()).trim();
  if (!url.startsWith("http")) throw new Error(`upload failed for ${label}: ${url.slice(0, 160)}`);
  console.log(`   [ref] ${label} -> ${url}`);
  return url;
}

async function submitTask(prompt, refUrl) {
  const res = await fetch(`${SUBMIT}?key=${encodeURIComponent(KEY)}`, {
    method: "POST",
    headers: { Authorization: KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ prompt, aspectRatio: ASPECT, urls: refUrl }),
  });
  const json = await res.json();
  if (json?.code !== 200) throw new Error(`submit rejected: ${JSON.stringify(json).slice(0, 200)}`);
  return json.data.id;
}

async function statusOf(taskId) {
  const res = await fetch(`${DETAIL}?key=${encodeURIComponent(KEY)}&id=${encodeURIComponent(taskId)}`, {
    headers: { Authorization: KEY },
  });
  const json = await res.json();
  return { status: json?.data?.status, message: json?.data?.message, url: json?.data?.result?.[0] };
}

function buildPrompt(id, variant) {
  const brief = BRIEFS[id];
  return [
    `Create one vertical 4:5 FRONT-side artwork for ${id}, a Greek goddess result card in a collectible series.`,
    `Depict a single idealized classical female figure representing ${id}. Use exactly these fixed symbolic elements: ${brief.attributes}. ${brief.extra}`,
    brief.avoid,
    STYLE,
    variant > 1 ? `This is candidate ${variant}; vary the pose and the arrangement of the symbolic elements while keeping the same palette, framing, halo treatment and figure scale as the reference.` : "",
  ].filter(Boolean).join("\n\n");
}

