const TASK_DEADLINE_MS = 420000;

const onlyIdx = process.argv.indexOf("--only");
const idsIdx = process.argv.indexOf("--ids");
let ONLY = onlyIdx !== -1 ? process.argv[onlyIdx + 1] : null;
let IDS_ARG = idsIdx !== -1 ? process.argv[idsIdx + 1] : null;

/* Briefs: signature palette + attributes per princess. Original storybook
   interpretations; briefs deliberately avoid film-still reproduction. */
const BRIEFS = {
  "snow-white": {
    prompt: [
      "A kind-hearted young heroine with short black hair and a small red ribbon headband,",
      "wearing a folk dress with a blue laced top and a sunny yellow skirt. She picks ripe red",
      "apples in a small orchard; a little bluebird sits on the garden fence beside her.",
      "Background: apple-orchard greens and warm ivory, morning light.",
    ].join(" "),
  },
  cinderella: {
    prompt: [
      "A graceful young woman with a blonde updo, wearing a flowing silver-blue evening gown",
      "with a sheer overskirt. She steps down a moonlit garden staircase; a small round pumpkin",
      "carriage silhouette rests far in the distance.",
      "Background: midnight blue with silver sparkles and soft garden hedges.",
    ].join(" "),
  },
  aurora: {
    prompt: [
      "One serene young woman with very long wavy golden hair, wearing a medieval gown whose",
      "skirt shifts between rose pink and sky blue. She dances barefoot in a forest clearing",
      "with a few woodland friends peeking from the grass.",
      "Background: soft dawn haze, tall gentle trees, drifting light petals.",
    ].join(" "),
  },
  ariel: {
    prompt: [
      "A curious young heroine with very long flowing red hair, wearing a violet top and a long",
      "emerald-green skirt. She sits on warm sunlit rocks by the sea, small waves and a few",
      "seashells around her feet.",
      "Background: lagoon turquoise water with coral orange accents.",
    ].join(" "),
  },
  belle: {
    prompt: [
      "A book-loving young woman with brown hair tied by a blue ribbon, wearing a warm golden",
      "gown. She reads one open book in a quiet rose garden; a single red rose blooms on a small",
      "table beside her.",
      "Background: warm library browns and amber candlelight with floating dust motes.",
    ].join(" "),
  },
  jasmine: {
    prompt: [
      "A self-assured young heroine with long black hair and a golden headband, wearing a teal",
      "dress with small gold earrings. She stands on a moonlit palace balcony looking at the",
      "night sky with quiet confidence.",
      "Background: desert twilight — sand gold, teal domes and one crescent moon.",
    ].join(" "),
  },
  pocahontas: {
    prompt: [
      "One free-spirited young woman with very long flowing black hair, wearing a tan fringed",
      "suede dress and a turquoise pendant necklace. Golden and crimson leaves swirl in the wind",
      "around her raised hand; one brass compass lies in the grass at her feet.",
      "Background: river-bend greens and clay orange, wind-driven leaves tracing a curved path.",
    ].join(" "),
  },
  mulan: {
    prompt: [
      "One determined young Chinese heroine with black hair tied back, wearing a red-and-gold",
      "hanfu-inspired dress with a matching sash. She holds one straight sword lowered calmly;",
      "a branch of pink magnolia crosses the corner; light snow drifts softly.",
      "Background: mountain pass greys and imperial red banners far away.",
    ].join(" "),
  },
  tiana: {
    prompt: [
      "A hardworking young woman with dark brown hair, wearing a light green dress with lily-pad",
      "details. She carries a tray of golden pastries through a garden party; a small green tree",
      "frog sits on a lily leaf beside her.",
      "Background: warm evening lamp strings, bayou greens and soft gold.",
    ].join(" "),
  },
