      manifest.images.push({ id, label: `${id}-front`, status: "failed", stage: "submit", error: error.message, prompt });
      continue;
    }
    const submittedAt = Date.now();
    let settled = false;
    while (Date.now() - submittedAt < TASK_DEADLINE_MS) {
      await sleep(POLL_MS);
      let info;
      try { info = await statusOf(taskId); }
      catch { continue; }
      if (info.status === 2) {
        const file = `${id}-front.png`;
        try {
          const res = await fetch(info.url);
          const buf = Buffer.from(await res.arrayBuffer());
          writeFileSync(join(ASSET, file), buf);
          console.log(`[${id}] DONE -> ${file} (${buf.length} bytes)`);
          manifest.images.push({
            id, label: `${id}-front`, file: join("assets", "disney-princess", file),
            task_id: taskId, result_url: info.url, prompt,
            bytes: buf.length, sha256: sha256(buf), status: "ok",
          });
          finished = true;
        } catch (error) {
          console.log(`[${id}] download failed: ${error.message}`);
          manifest.images.push({ id, status: "failed", stage: "download", error: error.message, prompt });
        }
        settled = true;
        break;
      }
      if (info.status === 3) {
        console.log(`[${id}] generation failed: ${info.message}`);
        settled = true;
        break;
      }
    }
    if (!settled) {
      console.log(`[${id}] STALLED past deadline`);
    }
  }
  if (!finished) {
    manifest.images.push({ id, status: "failed", stage: "exhausted", attempts: ATTEMPTS, prompt });
  }
}

writeFileSync(manifestPath, JSON.stringify(manifest, null, 1) + "\n", "utf8");
console.log(`[manifest] ${manifestPath}`);

