// Probe: resubmit a KNOWN-GOOD brief (tiana, already generated successfully)
// and one minimal test prompt. If the known-good brief now fails, the API
// filter is in a state-level lockout, not a per-prompt rejection.
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const KEY = (process.env.DSH_IMAGE_API_KEY || "").trim();
if (!KEY) throw new Error("DSH_IMAGE_API_KEY empty");
const HERE = dirname(fileURLToPath(import.meta.url));
const SUBMIT = "https://api.wuyinkeji.com/api/async/image_gpt_2.5";
const DETAIL = "https://api.wuyinkeji.com/api/async/detail";
const ASPECT = "896*1120";

const manifest = JSON.parse(readFileSync(join(HERE, "..", "deploy-ready", "assets", "disney-princess", "manifest.json"), "utf8"));
const goodPrompt = manifest.images.find((img) => img.id === "tiana" && img.status === "ok").prompt;
const minimalPrompt = [
  "Flat modern storybook illustration, bright warm palette. One kind young woman in a folk",
  "dress holding a red apple in a small orchard, a bluebird on the fence. Generate only the artwork.",
].join(" ");

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function run(label, prompt) {
  const res = await fetch(`${SUBMIT}?key=${encodeURIComponent(KEY)}`, {
    method: "POST",
    headers: { Authorization: KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ prompt, aspectRatio: ASPECT }),
  });
  const json = await res.json();
  if (json?.code !== 200) { console.log(`[${label}] submit rejected`); return; }
  const id = json.data.id;
  for (let t = 0; t < 40; t += 1) {
    await sleep(7000);
    const r2 = await fetch(`${DETAIL}?key=${encodeURIComponent(KEY)}&id=${encodeURIComponent(id)}`, { headers: { Authorization: KEY } });
    const j2 = await r2.json();
    const st = j2?.data?.status;
    if (st === 2) { console.log(`[${label}] PASS`); return; }
    if (st === 3) { console.log(`[${label}] FAIL: ${j2?.data?.message}`); return; }
  }
  console.log(`[${label}] stalled`);
}

await run("known-good-tiana", goodPrompt);
await run("minimal-apple", minimalPrompt);

