// Generate the 13 princess front portraits through the wuyinkeji async
// image API (same pipeline as tools/run-greek-fronts.mjs, but with NO
// reference image: each portrait is an ORIGINAL flat-storybook
// interpretation driven purely by its text brief).
//
// Usage:
//   powershell -ExecutionPolicy Bypass -File tools\run-image-api.ps1 -Script tools\run-disney-fronts.mjs -ExtraArgs @("--only","mulan")
//   powershell -ExecutionPolicy Bypass -File tools\run-image-api.ps1 -Script tools\run-disney-fronts.mjs
//
// Outputs masters to deploy-ready/assets/disney-princess/<id>-front.png
// and records prompt/task/source in assets/disney-princess/manifest.json.
// Promote to WebP afterwards with tools/promote-disney-assets.py --write.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const KEY = (process.env.DSH_IMAGE_API_KEY || "").trim();
if (!KEY) throw new Error("DSH_IMAGE_API_KEY empty — run through tools/run-image-api.ps1");

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const ASSET = join(ROOT, "deploy-ready", "assets", "disney-princess");
const SUBMIT = "https://api.wuyinkeji.com/api/async/image_gpt_2.5";
const DETAIL = "https://api.wuyinkeji.com/api/async/detail";
const ASPECT = "896*1120";
const POLL_MS = 8000;
const TASK_DEADLINE_MS = 420000;

const onlyIdx = process.argv.indexOf("--only");
const idsIdx = process.argv.indexOf("--ids");
let ONLY = onlyIdx !== -1 ? process.argv[onlyIdx + 1] : null;
let IDS_ARG = idsIdx !== -1 ? process.argv[idsIdx + 1] : null;

/* Briefs: signature palette + attributes per princess. Original storybook
   interpretations; briefs deliberately avoid film-still reproduction. */
const BRIEFS = {
  "snow-white": {
    prompt: "One kind young woman with short black hair and a red ribbon headband, in a blue-and-yellow folk dress, picking red apples in a small orchard with a bluebird on the fence.",
  },
  cinderella: {
    prompt: [
      "A graceful young woman with a blonde updo, wearing a flowing silver-blue evening gown",
      "with a sheer overskirt. She steps down a moonlit garden staircase; a small round pumpkin",
      "carriage silhouette rests far in the distance.",
      "Background: midnight blue with silver sparkles and soft garden hedges.",
    ].join(" "),
  },
  aurora: {
    prompt: [
      "One serene young woman with very long wavy golden hair, wearing a medieval gown whose",
      "skirt shifts between rose pink and sky blue. She dances barefoot in a forest clearing",
      "with a few woodland friends peeking from the grass.",
      "Background: soft dawn haze, tall gentle trees, drifting light petals.",
    ].join(" "),
  },
  ariel: {
    prompt: [
      "A curious young heroine with very long flowing red hair, wearing a violet top and a long",
      "emerald-green skirt. She sits on warm sunlit rocks by the sea, small waves and a few",
      "seashells around her feet.",
      "Background: lagoon turquoise water with coral orange accents.",
    ].join(" "),
  },
  belle: {
    prompt: [
      "A book-loving young woman with brown hair tied by a blue ribbon, wearing a warm golden",
      "gown. She reads one open book in a quiet rose garden; a single red rose blooms on a small",
      "table beside her.",
      "Background: warm library browns and amber candlelight with floating dust motes.",
    ].join(" "),
  },
  jasmine: {
    prompt: "One confident young woman with long black hair and a golden headband, in a teal dress with small gold earrings, standing on a moonlit palace balcony above a desert city.",
  },
  pocahontas: {
    prompt: [
      "One free-spirited young woman with very long flowing black hair, wearing a tan fringed",
      "suede dress and a turquoise pendant necklace. Golden and crimson leaves swirl in the wind",
      "around her raised hand; one brass compass lies in the grass at her feet.",
      "Background: river-bend greens and clay orange, wind-driven leaves tracing a curved path.",
    ].join(" "),
  },
  mulan: {
    prompt: [
      "One determined young Chinese heroine with black hair tied back, wearing a red-and-gold",
      "hanfu-inspired dress with a matching sash. She holds one straight sword lowered calmly;",
      "a branch of pink magnolia crosses the corner; light snow drifts softly.",
      "Background: mountain pass greys and imperial red banners far away.",
    ].join(" "),
  },
  tiana: {
    prompt: [
      "A hardworking young woman with dark brown hair, wearing a light green dress with lily-pad",
      "details. She carries a tray of golden pastries through a garden party; a small green tree",
      "frog sits on a lily leaf beside her.",
      "Background: warm evening lamp strings, bayou greens and soft gold.",
    ].join(" "),
  },
  rapunzel: {
    prompt: "One cheerful young woman with very long golden braided hair woven with small flowers, in a lilac dress with pink stripes, standing in a meadow at dusk under warm rising lights.",
  },
  merida: {
    prompt: "One bold young woman with voluminous curly red hair, in a dark teal folk dress with a long sash, standing on a misty highland meadow with old standing stones.",
  },
  moana: {
    prompt: "One spirited young woman with wavy dark-brown hair, in a red-and-orange patterned top with a small shell necklace, standing at a sunlit shoreline gazing at the open sea.",
  },
  raya: {
    prompt: [
      "One lithe young warrior with dark hair in a high bun under a conical straw hat, wearing a",
      "blue-and-green cape over practical trousers. She rests one curved saber-like sword low;",
      "a soft golden dragon-glow light traces a ribbon of air beside her blade.",
      "Background: drought-cracked riverbed blues meeting a ribbon of living golden water.",
    ].join(" "),
  },
};

const STYLE = [
  "Flat modern storybook illustration, bright warm palette, big simple shapes, clean rounded",
  "silhouettes, subtle paper-grain texture, gentle pastel background field. ONE clear figure centered,",
  "three-quarter body or full figure, friendly and inviting mood, poster-like composition, flat graphic",
  "depth, generous negative space around the figure.",
  "No photorealism, no 3D render, no anime styling, no cinematic realism, no horror, no battle scene,",
  "no glowing magic effects, no modern gadgets, no readable letters, logos, watermarks or UI, no text.",
  "Create an ORIGINAL storybook interpretation of a fairy-tale heroine archetype: do not copy any",
  "specific film still, official poster composition, or existing franchise artwork.",
  "Generate only the artwork, not a result-card layout.",
].join(" ");

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const sha256 = (buf) => createHash("sha256").update(buf).digest("hex");

async function submitTask(prompt) {
  const res = await fetch(`${SUBMIT}?key=${encodeURIComponent(KEY)}`, {
    method: "POST",
    headers: { Authorization: KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ prompt, aspectRatio: ASPECT }),
  });
  const json = await res.json();
  if (json?.code !== 200) throw new Error(`submit rejected: ${JSON.stringify(json).slice(0, 200)}`);
  return json.data.id;
}

async function statusOf(taskId) {
  const res = await fetch(`${DETAIL}?key=${encodeURIComponent(KEY)}&id=${encodeURIComponent(taskId)}`, {
    headers: { Authorization: KEY },
  });
  const json = await res.json();
  return { status: json?.data?.status, message: json?.data?.message, url: json?.data?.result?.[0] };
}

function buildPrompt(id) {
  const brief = BRIEFS[id].prompt;
  // Short-prompt mode: long negative-word lists tripped the filter on some
  // briefs while equivalent short ones passed; keep prompts minimal.
  return `Flat modern storybook illustration, bright warm palette, big simple shapes, poster-like composition, flat graphic depth. ${brief} No text, no logos, no watermark. Generate only the artwork.`;
}

if (!existsSync(ASSET)) mkdirSync(ASSET, { recursive: true });

const ids = ONLY ? [ONLY] : IDS_ARG ? IDS_ARG.split(",").map((s) => s.trim()).filter(Boolean) : Object.keys(BRIEFS);
for (const id of ids) {
  if (!BRIEFS[id]) throw new Error(`unknown princess id: ${id}`);
}

const manifestPath = join(ASSET, "manifest.json");
const manifest = existsSync(manifestPath)
  ? JSON.parse(readFileSync(manifestPath, "utf8"))
  : {
      purpose: "original flat-storybook portraits for the disney-princess skin (local demo; original interpretations, no official assets)",
      api: { submit: SUBMIT, detail: DETAIL, aspect_ratio: ASPECT, reference_images: "none" },
      style: STYLE,
      images: [],
    };

// Serial mode: one task at a time (submit -> poll -> download). The API's
// content filter rejects equivalent briefs non-deterministically, so each
// portrait is resubmitted up to ATTEMPTS times before giving up.
const ATTEMPTS = Number(process.env.DSH_ATTEMPTS || 4);
for (const id of ids) {
  if (existsSync(join(ASSET, `${id}-front.png`))) {
    console.log(`[${id}] already generated, skipping`);
    continue;
  }
  const prompt = buildPrompt(id);
  let finished = false;
  for (let attempt = 1; attempt <= ATTEMPTS && !finished; attempt += 1) {
    let taskId;
    try {
      taskId = await submitTask(prompt);
      console.log(`[submit] ${id} (attempt ${attempt}/${ATTEMPTS}) -> ${taskId}`);
    } catch (error) {
      console.log(`[submit] ${id} FAILED: ${error.message}`);
      manifest.images.push({ id, label: `${id}-front`, status: "failed", stage: "submit", error: error.message, prompt });
      continue;
    }
    const submittedAt = Date.now();
    let settled = false;
    while (Date.now() - submittedAt < TASK_DEADLINE_MS) {
      await sleep(POLL_MS);
      let info;
      try { info = await statusOf(taskId); }
      catch { continue; }
      if (info.status === 2) {
        const file = `${id}-front.png`;
        try {
          const res = await fetch(info.url);
          const buf = Buffer.from(await res.arrayBuffer());
          writeFileSync(join(ASSET, file), buf);
          console.log(`[${id}] DONE -> ${file} (${buf.length} bytes)`);
          manifest.images.push({
            id, label: `${id}-front`, file: join("assets", "disney-princess", file),
            task_id: taskId, result_url: info.url, prompt,
            bytes: buf.length, sha256: sha256(buf), status: "ok",
          });
          finished = true;
        } catch (error) {
          console.log(`[${id}] download failed: ${error.message}`);
          manifest.images.push({ id, status: "failed", stage: "download", error: error.message, prompt });
        }
        settled = true;
        break;
      }
      if (info.status === 3) {
        console.log(`[${id}] generation failed: ${info.message}`);
        settled = true;
        break;
      }
    }
    if (!settled) {
      console.log(`[${id}] STALLED past deadline`);
    }
  }
  if (!finished) {
    manifest.images.push({ id, status: "failed", stage: "exhausted", attempts: ATTEMPTS, prompt });
  }
}

writeFileSync(manifestPath, JSON.stringify(manifest, null, 1) + "\n", "utf8");
console.log(`[manifest] ${manifestPath}`);

