/* 你是哪位迪士尼公主？—— 产品视觉层（product skin）
 *
 * 世界观：星光游园会。明亮渐变的傍晚天空，白色大圆角卡片，角色和画面
 * 为主：结果页以公主立绘为核心，页面底色随她的签名色变化。
 * 与大观园（宣纸判词）、傲慢与偏见（象牙名帖）、希腊女神（默认模板）
 * 完全不同的表达；功能仍全部来自公共引擎（license/题库/评分/导航）。
 * 数据字段除通用字段外使用结果记录里的 similarity 与 color。
 */

const SKIN_ID = "disney-princess";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

/* 13 位公主的签名色 —— 与结果记录的 result.color 字段一致，
   封面的色点行也由此渲染。 */
const CAST = [
  { id: "snow-white", name: "白雪公主", color: "#E23D4E" },
  { id: "cinderella", name: "灰姑娘", color: "#6FA8DC" },
  { id: "aurora", name: "爱洛", color: "#E78FB3" },
  { id: "ariel", name: "爱丽儿", color: "#2FA37C" },
  { id: "belle", name: "贝儿", color: "#E5B23A" },
  { id: "jasmine", name: "茉莉", color: "#2BB3A3" },
  { id: "pocahontas", name: "宝嘉康蒂", color: "#C97A4A" },
  { id: "mulan", name: "木兰", color: "#C23B3B" },
  { id: "tiana", name: "蒂安娜", color: "#5C9E54" },
  { id: "rapunzel", name: "乐佩", color: "#9B6DC6" },
  { id: "merida", name: "梅莉达", color: "#B44E2E" },
  { id: "moana", name: "莫阿娜", color: "#E08A3C" },
  { id: "raya", name: "拉雅", color: "#3D7EA6" },
];

const colorOf = (result) => {
  const cast = CAST.find((c) => c.id === (result && result.id));
  return (result && result.color) || (cast && cast.color) || "#B867B8";
};

function pageShell(inner) {
  return `<div class="dp">${inner}</div>`;
}

function brandBar(right) {
  return `<header class="dp-top"><span class="dp-brand">你是哪位迪士尼公主？</span><span class="dp-top-right">${right}</span></header>`;
}

function resultImage(resultId, name, accent) {
  // 生成立绘 assets/disney-princess/<id>-front.webp；缺失时退化为签名色星章。
  const src = `/assets/disney-princess/${encodeURIComponent(resultId)}-front.webp`;
  return `
    <figure class="dp-portrait" style="--dp-accent:${accent}">
      <img src="${src}" alt="${esc(name || resultId || "公主")}的故事书立绘" loading="eager" decoding="async"
           onerror="this.closest('figure').classList.add('dp-no-art'); this.remove();">
      <span class="dp-fallback-star" aria-hidden="true">★</span>
    </figure>`;
}

/* ------------------------------------------------------- 回执（兑换码） ---- */
const GATE_ERRORS = {
  empty: "先输入兑换码哦。",
  already_bound: "这个码已在别的浏览器激活。换设备请联系卖家重置绑定。",
  rate_limited: "尝试太频繁了，一分钟后再来。",
  invalid: "兑换码无效，检查一下再试。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("游乐场")}
    <section class="dp-gate">
      <div class="dp-dots" aria-hidden="true">${CAST.map((c) => `<i style="background:${c.color}"></i>`).join("")}</div>
      <h1 class="dp-title">凭码入场</h1>
      <p class="dp-lead">输入兑换码开始游玩。激活后与当前浏览器绑定，之后随时回来。</p>
      <div class="dp-gate-form">
        <input id="dp-gate-code" class="dp-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="dp-btn" id="dp-gate-submit">入场</button>
      </div>
      <p class="dp-gate-error" id="dp-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="dp-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#dp-gate-code");
    const submit = root.querySelector("#dp-gate-submit");
    const error = root.querySelector("#dp-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`这个码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，检查一下再试。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ------------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("游乐场")}
    <section class="dp-cover">
      <div class="dp-castle" aria-hidden="true">
        <svg viewBox="0 0 320 120">
          <g fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
            <path d="M60 110V56l18-14 18 14v54"/>
            <path d="M96 110V34l16-16 16 16v76"/>
            <path d="M148 110V48l14-12 14 12v62"/>
            <path d="M176 110V28l18-16 18 16v82"/>
            <path d="M212 110V52l16-12 16 12v58"/>
            <path d="M40 110h240"/>
            <path d="M104 46h16M186 36h16M232 62h14" stroke-width="2"/>
          </g>
          <g>
            ${CAST.map((c, i) => `<circle cx="${52 + i * 18}" cy="26" r="4.5" fill="${c.color}"/>`).join("")}
          </g>
        </svg>
      </div>
      <h1 class="dp-title">你是哪位<br>迪士尼公主？</h1>
      <p class="dp-lead">${esc(ctx.theme.subtitle)}</p>
      <div class="dp-cast" aria-label="十三位公主">
        ${CAST.map((c) => `<span class="dp-cast-dot" style="background:${c.color}" title="${esc(c.name)}"></span>`).join("")}
      </div>
      <div class="dp-cover-actions">
        <button class="dp-btn dp-btn-big" id="dp-start">开始</button>
      </div>
      <p class="dp-foot">24 道日常情境 · 约六分钟 · 原创娱乐测试，与迪士尼公司无关，也不是心理测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#dp-start").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ------------------------------------------------------------- 答题 ---- */
function questionView(ctx) {
  const buttons = ctx.options.map((text, i) => `
    <button class="dp-option${ctx.selected === i ? " picked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="dp-option-key" aria-hidden="true">${"ABC"[i] || "•"}</span>
      <span class="dp-option-text">${esc(text)}</span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`${ctx.index + 1} / ${ctx.total}`)}
    <div class="dp-progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${ctx.total}" aria-valuenow="${ctx.index + 1}">
      <i style="width:${Math.round(((ctx.index + 1) / ctx.total) * 100)}%"></i>
    </div>
    <section class="dp-q">
      <p class="dp-q-count">第 ${ctx.index + 1} 题 · 共 ${ctx.total} 题</p>
      <h2 class="dp-q-text">${esc(ctx.question)}</h2>
      <div class="dp-options">${buttons}</div>
      <div class="dp-q-nav">
        <button class="dp-link" id="dp-prev" ${ctx.index === 0 ? "disabled" : ""}>← 上一题</button>
        <button class="dp-link" id="dp-exit">先不答了</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".dp-option").forEach((option) => {
      option.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        option.classList.add("picked");
        option.setAttribute("aria-pressed", "true");
        window.setTimeout(() => ctx.select(Number(option.dataset.i)), 260);
      });
    });
    const prev = root.querySelector("#dp-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#dp-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

/* --------------------------------------------------------- 等待 ---- */
function resultLoadingView() {
  const html = pageShell(`
    ${brandBar("一点魔法")}
    <section class="dp-loading">
      <div class="dp-spark" aria-hidden="true">
        <svg viewBox="0 0 120 120"><path d="M60 12l9 39 39 9-39 9-9 39-9-39-39-9 39-9z" fill="currentColor"/></svg>
      </div>
      <p class="dp-loading-text">星星正在对答案……</p>
      <p class="dp-foot">判定在服务端完成。</p>
    </section>`);
  return { html };
}

/* ------------------------------------------------------------- 结果 ----
   结构（用户定稿）：人物图与姓名 → 一句短引用 → 小字出处 → 两句解释 →
   保存结果图按钮；详细内容全部收进下方折叠区，默认不展开。
   电影引用加「」；原创角色短句不加引号（quote.kind 区分）。 */
function verdictView(ctx) {
  const result = ctx.result || {};
  const accent = colorOf(result);
  const quote = result.quote || {};
  const isFilm = quote.kind === "film";
  const quoteText = isFilm ? `「${esc(quote.text || "")}」` : esc(quote.text || "");

  const detailRows = [];
  if (result.similarity) detailRows.push(["你和她像在哪里", result.similarity]);
  if (result.relationship_style) detailRows.push(["面对关系与选择", result.relationship_style]);
  if (result.blind_spots) detailRows.push(["一个具体的盲点", result.blind_spots]);

  const html = pageShell(`
    ${brandBar("结果")}
    <section class="dp-result" style="--dp-accent:${accent}">
      ${resultImage(result.id, result.name, accent)}
      <div class="dp-name-row">
        <h2 class="dp-name">${esc(result.name || "")}</h2>
        <span class="dp-name-en">${esc(result.english_name || "")}</span>
      </div>
      ${quote.text ? `
      <blockquote class="dp-quote">${quoteText}</blockquote>
      <p class="dp-quote-source">${esc(quote.source_short || "")}</p>` : ""}
      <p class="dp-blurb">${esc(result.blurb || result.subtitle || "")}</p>

      <div class="dp-save">
        <button class="dp-btn" id="dp-share">保存结果图</button>
        <div class="dp-minor">
          <button class="dp-link" id="dp-copy">复制文案</button>
          <button class="dp-link" id="dp-again">再测一次</button>
          <button class="dp-link" id="dp-home">回封面</button>
        </div>
      </div>

      <details class="dp-more">
        <summary>完整解读与出处</summary>
        <p class="dp-keywords">${(result.keywords || []).join(" · ")}</p>
        <p class="dp-reading">${esc(result.reading || "")}</p>
        ${detailRows.map(([title, text]) => `<div class="dp-detail"><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`).join("")}
        ${isFilm ? `<p class="dp-quote-full">引用原文：${esc(quote.original || "")}<br>${esc(quote.scene || "")}　来源为自行翻译，非官方中文台词。</p>` : `<p class="dp-quote-full">${esc(quote.scene || "")}</p>`}
        <p class="dp-basis">${esc(result.character_basis || "")}</p>
      </details>
      <p class="dp-foot dp-disclaimer">${esc(ctx.disclaimer || "")}</p>
    </section>`);

  const bind = (root) => {
    const copy = root.querySelector("#dp-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已复制 ✓";
      window.setTimeout(() => { copy.textContent = "复制文案"; }, 1800);
    });
    root.querySelector("#dp-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#dp-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#dp-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享结果图 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const ctx2d = canvas.getContext("2d");
  const accent = colorOf(result);

  // 明亮天空渐变：从签名的浅色调到象牙白
  const grad = ctx2d.createLinearGradient(0, 0, 0, 1200);
  grad.addColorStop(0, mixHex(accent, "#FFFFFF", 0.55));
  grad.addColorStop(1, "#FFFDF6");
  ctx2d.fillStyle = grad;
  ctx2d.fillRect(0, 0, 900, 1200);

  const center = (text, y, font, color) => {
    ctx2d.font = font;
    ctx2d.fillStyle = color;
    ctx2d.textAlign = "center";
    ctx2d.fillText(text, 450, y);
  };

  center("你是哪位迪士尼公主？", 90, "600 34px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#3A3A44");
  center(result.english_name || "", 150, "300 26px Georgia, serif", "#6B6A72");

  // 立绘（本地资源，同源可安全画入 canvas）
  const img = new Image();
  img.onload = () => {
    const w = 460;
    const h = (img.height / img.width) * w;
    const x = (900 - w) / 2;
    const y = 190;
    ctx2d.save();
    roundRect(ctx2d, x, y, w, h, 36);
    ctx2d.clip();
    ctx2d.drawImage(img, x, y, w, h);
    ctx2d.restore();
    ctx2d.strokeStyle = accent;
    ctx2d.lineWidth = 6;
    roundRect(ctx2d, x, y, w, h, 36);
    ctx2d.stroke();
    finish();
  };
  img.onerror = finish;
  img.src = `/assets/disney-princess/${encodeURIComponent(result.id)}-front.webp`;

  function finish() {
    center(result.name || "", 760, "800 84px 'PingFang SC', 'Microsoft YaHei', sans-serif", accent);
    center(result.subtitle || "", 830, "600 34px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#3A3A44");
    center((result.keywords || []).join(" · "), 890, "300 26px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#6B6A72");
    // 分享短句（可能较长，手动换行）
    ctx2d.font = "300 30px 'PingFang SC', 'Microsoft YaHei', sans-serif";
    ctx2d.fillStyle = "#3A3A44";
    ctx2d.textAlign = "center";
    const line = result.share_line || "";
    const rows = [];
    let current = "";
    for (const ch of line) {
      if (ctx2d.measureText(current + ch).width > 620) { rows.push(current); current = ch; }
      else current += ch;
    }
    if (current) rows.push(current);
    rows.forEach((rowText, i) => ctx2d.fillText(rowText, 450, 970 + i * 46));

    // 签名色圆点行
    CAST.forEach((c, i) => {
      ctx2d.fillStyle = c.color;
      ctx2d.beginPath();
      ctx2d.arc(450 - (CAST.length - 1) * 9 + i * 18, 1120, 5, 0, Math.PI * 2);
      ctx2d.fill();
    });
    center("原创娱乐测试 · 与迪士尼公司无关", 1170, "300 22px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#9A98A0");

    canvas.toBlob((blob) => {
      if (!blob) return;
      const link = document.createElement("a");
      link.download = `disney-princess-${result.id || "result"}.png`;
      link.href = URL.createObjectURL(blob);
      link.click();
      window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    }, "image/png");
  }
}

function roundRect(c, x, y, w, h, r) {
  c.beginPath();
  c.moveTo(x + r, y);
  c.arcTo(x + w, y, x + w, y + h, r);
  c.arcTo(x + w, y + h, x, y + h, r);
  c.arcTo(x, y + h, x, y, r);
  c.arcTo(x, y, x + w, y, r);
  c.closePath();
}

function mixHex(a, b, t) {
  const pa = [1, 3, 5].map((i) => parseInt(a.slice(i, i + 2), 16));
  const pb = [1, 3, 5].map((i) => parseInt(b.slice(i, i + 2), 16));
  return "#" + pa.map((v, i) => Math.round(v + (pb[i] - v) * t).toString(16).padStart(2, "0")).join("");
}

/* ------------------------------------------------------------- 出口 ---- */
export default {
  id: SKIN_ID,
  title: "你是哪位迪士尼公主？",
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
  copyText(result) {
    return `${result.name || ""}（${result.english_name || ""}）\n${result.subtitle || ""}\n${result.share_line || ""}\n\n来自「你是哪位迪士尼公主？」原创娱乐测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
};

