readFileState.content:
/* 你是哪位迪士尼公主？—— 产品视觉层样式
 *
 * 作用域：全部规则挂在 body[data-skin="disney-princess"] 下，与其他产品
 * 和默认模板完全隔离。
 *
 * 世界观：星光游园会。傍晚天空的柔和渐变（珊瑚粉→淡金→丁香紫），白色
 * 大圆角卡片配大投影；结果页的世界随公主的签名色变化（--dp-accent）。
 * 刻意与前三个产品区分：无纸张、无线框、无四栏长文，角色和画面为主。
 */

body[data-skin="disney-princess"] {
  --dp-accent: #B867B8;
  --dp-ink: #3A3A44;
  --dp-soft: #6B6A72;
  --dp-card: #FFFFFF;
  --dp-sans: -apple-system, BlinkMacSystemFont, "PingFang SC", "Segoe UI", "Microsoft YaHei", sans-serif;

  margin: 0;
  color: var(--dp-ink);
  font-family: var(--dp-sans);
  background:
    radial-gradient(900px 460px at 85% -6%, rgba(255, 214, 165, .55), transparent 62%),
    radial-gradient(820px 520px at 8% 12%, rgba(255, 176, 196, .5), transparent 60%),
    radial-gradient(900px 620px at 50% 108%, rgba(190, 168, 255, .38), transparent 64%),
    linear-gradient(180deg, #FFF4E6 0%, #FFE9F0 46%, #F3EEFF 100%);
  background-attachment: fixed;
}

body[data-skin="disney-princess"] .dp {
  max-width: 640px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 22px 20px 48px;
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="disney-princess"] .dp-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 26px;
  color: var(--dp-soft);
  font-size: 12px;
  letter-spacing: .08em;
}

body[data-skin="disney-princess"] .dp-brand {
  color: var(--dp-ink);
  font-weight: 700;
  letter-spacing: .06em;
}

body[data-skin="disney-princess"] .dp-title {
  margin: 8px 0 14px;
  font-size: clamp(38px, 10vw, 58px);
  font-weight: 800;
  line-height: 1.18;
  letter-spacing: .02em;
  color: var(--dp-ink);
}

body[data-skin="disney-princess"] .dp-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--dp-soft);
  font-size: 15px;
  line-height: 1.9;
}

body[data-skin="disney-princess"] .dp-foot {
  margin: 30px 0 0;
  color: #8B8994;
  font-size: 11.5px;
  line-height: 1.8;
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="disney-princess"] .dp-btn {
  padding: 14px 44px;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #B867B8, #7A5FD0);
  color: #FFF;
  font: 700 16px/1 var(--dp-sans);
  letter-spacing: .18em;
  text-indent: .18em;
  cursor: pointer;
  box-shadow: 0 10px 22px rgba(150, 105, 200, .38);
  transition: transform .16s ease, box-shadow .16s ease, filter .16s ease;
}

body[data-skin="disney-princess"] .dp-btn:hover { transform: translateY(-2px); box-shadow: 0 14px 26px rgba(150, 105, 200, .44); }
body[data-skin="disney-princess"] .dp-btn:active { transform: translateY(0) scale(.98); }
body[data-skin="disney-princess"] .dp-btn-big { padding: 16px 56px; font-size: 17px; }

body[data-skin="disney-princess"] .dp-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1.5px solid rgba(58, 58, 68, .28);
  background: transparent;
  color: var(--dp-soft);
  font: 500 13px/1.5 var(--dp-sans);
  letter-spacing: .08em;
  cursor: pointer;
}

body[data-skin="disney-princess"] .dp-link:hover { color: var(--dp-accent); border-color: var(--dp-accent); }
body[data-skin="disney-princess"] .dp-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 入场 ---- */
