/* 迪士尼公主皮肤 · 端到端流程测试。
 *
 * 真实 deploy-ready/app.js + 真实 themes/disney-princess/skin.js 驱动完整
 * 流程：入场（兑换码）→ 封面 → 24 题作答 → 服务端评分（真实
 * server/scoring.mjs）→ 结果页，全部应渲染公主皮肤而非默认模板或其他
 * 产品皮肤。另附：13 结果可达性采样、皮肤无跨产品样式泄漏检查。
 *
 * Run: node tools/test-disney-skin.mjs
 */
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { selectWinner } from "../server/scoring.mjs";
import { sanitizeTheme } from "../server/sanitize.mjs";
import { productThemes } from "../server/products.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const results = [];
const check = (name, fn) => {
  try {
    const d = fn();
    if (d && typeof d.then === "function") {
      return d.then((detail) => results.push({ ok: true, name, d: detail }),
        (e) => results.push({ ok: false, name, d: e.message }));
    }
    results.push({ ok: true, name, d });
  } catch (e) {
    results.push({ ok: false, name, d: e.message });
  }
  return Promise.resolve();
};
const assert = (c, m) => { if (!c) throw new Error(m); };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* --------------------------------------------------------- DOM 桩 ---- */
const VOID = new Set(["br", "hr", "img", "input", "meta", "link", "area", "base", "col", "embed", "source", "track", "wbr"]);

function parseFragment(html) {
  const root = new El("#fragment");
  const stack = [root];
  const tokenRe = /<\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\s+[a-zA-Z-]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?)*)\s*(\/?)>|([^<]+)/g;
  let m;
  while ((m = tokenRe.exec(html))) {
    if (m[4] !== undefined) {
      if (m[4].trim()) stack[stack.length - 1].children.push(m[4]);
      continue;
    }
    const tag = m[1].toLowerCase();
    if (html[m.index + 1] === "/") {
      for (let i = stack.length - 1; i > 0; i -= 1) {
        if (stack[i].tagName === tag.toUpperCase()) { stack.length = i; break; }
      }
      continue;
    }
    const el = new El(tag);
    const attrRe = /([a-zA-Z-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
    let a;
    while ((a = attrRe.exec(m[2] || ""))) {
      const name = a[1].toLowerCase();
      const value = a[2] ?? a[3] ?? a[4] ?? "";
      el.attributes[name] = value;
      if (name === "id") el.id = value;
      if (name === "class") String(value).split(/\s+/).filter(Boolean).forEach((c) => el.classList.add(c));
      if (name.startsWith("data-")) el.dataset[name.slice(5).replace(/-([a-z])/g, (_, ch) => ch.toUpperCase())] = value;
    }
    stack[stack.length - 1].children.push(el);
    el.parent = stack[stack.length - 1];
    if (!VOID.has(tag) && m[3] !== "/") stack.push(el);
  }
  return root.children;
}

function matchesSelector(el, selector) {
  const parts = selector.trim().split(/\s+/);
  if (parts.length > 1) {
    const last = parts[parts.length - 1];
    if (!matchesSelector(el, last)) return false;
    let node = el.parent;
    let depth = parts.length - 2;
    while (node && depth >= 0) {
      if (matchesSelector(node, parts[depth])) depth -= 1;
      node = node.parent;
    }
    return depth < 0;
  }
  const m = selector.match(/^([a-zA-Z][\w-]*)?((?:[.#][\w-]+)*)$/);
  if (!m) throw new Error(`stub selector unsupported: ${selector}`);
  if (m[1] && el.tagName !== m[1].toUpperCase()) return false;
  const tokens = (m[2] || "").match(/[.#][\w-]+/g) || [];
  for (const part of tokens) {
    if (part[0] === "#") { if (el.id !== part.slice(1)) return false; }
    else if (!el.classList.contains(part.slice(1))) return false;
  }
  return true;
}

class El {
  constructor(tag) {
    this.tagName = tag.toUpperCase();
    this.id = "";
    this.children = [];
    this.attributes = {};
    this.dataset = {};
    this.listeners = {};
    this._cls = new Set();
    this.style = {};
    this.value = "";
    this.hidden = false;
    this.parent = null;
    this.classList = {
      add: (...names) => names.forEach((n) => this._cls.add(n)),
      remove: (...names) => names.forEach((n) => this._cls.delete(n)),
      contains: (n) => this._cls.has(n),
    };
  }
  set innerHTML(html) { this.children = parseFragment(html); }
  get innerHTML() { return this.children.map((c) => (typeof c === "string" ? c : c.outer)).join(""); }
  get outer() { return `<${this.tagName.toLowerCase()}>${this.innerHTML}</${this.tagName.toLowerCase()}>`; }
  get textContent() { return this.children.map((c) => (typeof c === "string" ? c : c.textContent)).join(""); }
  set textContent(v) { this.children = [String(v)]; }
  setAttribute(n, v) { this.attributes[n] = String(v); if (n === "id") this.id = String(v); }
  getAttribute(n) { return this.attributes[n] ?? null; }
  removeAttribute(n) { delete this.attributes[n]; }
  addEventListener(t, fn) { (this.listeners[t] ||= []).push(fn); }
  dispatch(type, event = {}) { (this.listeners[type] || []).forEach((fn) => fn({ ...event, target: this })); }
  click() { this.dispatch("click"); }
  focus() {}
  querySelector(sel) { return this.querySelectorAll(sel)[0] || null; }
  querySelectorAll(sel) {
    const out = [];
    const walk = (el) => {
      for (const child of el.children) {
        if (typeof child !== "string") {
          if (matchesSelector(child, sel)) out.push(child);
          walk(child);
        }
      }
    };
    walk(this);
    return out;
  }
  appendChild(child) { this.children.push(child); child.parent = this; return child; }
}

/* --------------------------------------------------- 浏览器全局桩 ---- */
const appEl = new El("main");
appEl.id = "app";
const docEl = new El("#document");
docEl.appendChild(appEl);
const bodyEl = new El("body");
docEl.appendChild(bodyEl);
const headEl = new El("head");
docEl.appendChild(headEl);

const storage = new Map();
globalThis.localStorage = {
  getItem: (k) => (storage.has(k) ? storage.get(k) : null),
  setItem: (k, v) => storage.set(k, String(v)),
  removeItem: (k) => storage.delete(k),
};
let canvasCreated = 0;
globalThis.document = Object.assign(docEl, {
  body: bodyEl,
  head: headEl,
  title: "",
  createElement: (tag) => {
    const el = new El(tag);
    if (tag === "canvas") {
      canvasCreated += 1;
      el.getContext = () => new Proxy({}, {
        get: (t, prop) => {
          if (prop === "createLinearGradient") return () => ({ addColorStop: () => {} });
          if (prop === "measureText") return () => ({ width: String(prop).length ? 10 : 10 });
          return () => {};
        },
      });
      el.toBlob = (cb) => cb(null);
    }
    if (tag === "a") { el.click = () => {}; }
    return el;
  },
});
globalThis.location = { pathname: "/t/disney-princess", search: "" };
Object.defineProperty(globalThis, "navigator", {
  value: {
    userAgent: "dp-test", language: "zh-CN", platform: "test",
    clipboard: { writeText: async () => {} },
  },
  configurable: true,
});
globalThis.screen = { width: 390, height: 844, colorDepth: 24 };
globalThis.window = globalThis;
globalThis.Image = class { set src(v) { this._src = v; if (this.onload) setTimeout(this.onload, 0); } };

/* ----------------------------------------------------- API 桩 ---- */
const CODE = "DPNOTESMOKE001";
const SECRET = "[REDACTED:SECRET_ASSIGNMENT]";
const DP_THEMES = productThemes("disney-princess");
const SANITIZED = {
  product: { product_id: "disney-princess", name: "你是哪位迪士尼公主" },
  themes: DP_THEMES.map(sanitizeTheme),
};
let activated = false;
globalThis.fetch = async (url, options = {}) => {
  const body = options.body ? JSON.parse(options.body) : {};
  const norm = (c) => String(c || "").toUpperCase().replace(/[\s-]+/g, "");
  const path = String(url).split("?")[0];
  if (path === "/api/redeem") {
    if (norm(body.code) !== norm(CODE)) return json(404, { ok: false, error: "invalid_code" });
    if (!activated) {
      activated = true;
      return json(200, { ok: true, secret: SECRET, firstUse: true, product_id: "disney-princess", product_name: "你是哪位迪士尼公主" });
    }
    if (body.secret === SECRET) return json(200, { ok: true, secret: SECRET, firstUse: false, product_id: "disney-princess", product_name: "你是哪位迪士尼公主" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/verify-license") {
    if (norm(body.code) === norm(CODE) && body.secret === SECRET && activated) return json(200, { ok: true, product_id: "disney-princess", product_name: "你是哪位迪士尼公主" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/content") return json(200, SANITIZED);
  if (path === "/api/score") {
    const theme = DP_THEMES.find((t) => t.id === body.theme);
    if (!theme) return json(404, { ok: false, error: "invalid_theme" });
    if (norm(body.code) !== norm(CODE) || body.secret !== SECRET) return json(403, { ok: false, error: "already_bound" });
    const { winnerId } = selectWinner(theme, body.answers);
    const result = theme.results.find((r) => r.id === winnerId);
    return json(200, { ok: true, winnerId, result });
  }
  throw new Error(`unexpected fetch: ${url}`);
};
function json(status, body) {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}

/* --------------------------------------------- 挂载真实皮肤并启动 ---- */
const skinModule = await import(pathToFileURL(join(ROOT, "deploy-ready", "themes", "disney-princess", "skin.js")).href);
globalThis.__MYTHIC_SKINS__ = { "disney-princess": skinModule.default };

const appSource = readFileSync(join(ROOT, "deploy-ready", "app.js"), "utf8");
new Function("module", "exports", appSource)({ exports: {} }, {});
await sleep(80);

const skinCss = readFileSync(join(ROOT, "deploy-ready", "themes", "disney-princess", "skin.css"), "utf8");

/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the princess entrance skin, not the default gate", () => {
  assert(appEl.querySelector(".dp-title"), "princess gate title missing");
  assert(appEl.querySelector(".dp-gate-form"), "gate form missing");
  assert(!appEl.querySelector(".gate-hero"), "default gate template leaked into skin flow");
  assert(bodyEl.attributes["data-skin"] === "disney-princess", "body data-skin not set");
  assert(globalThis.document.title === "你是哪位迪士尼公主？", `skin title wrong: ${globalThis.document.title}`);
  return "entrance";
});

await check("a valid code unlocks the cover with the 13-color cast row", async () => {
  const input = appEl.querySelector("#dp-gate-code");
  const submit = appEl.querySelector("#dp-gate-submit");
  input.value = CODE.toLowerCase();
  submit.click();
  await sleep(120);
  assert(appEl.querySelector(".dp-cover"), "princess cover missing after redeem");
  assert(appEl.querySelector(".dp-cover .dp-title").textContent.includes("迪士尼公主"), "cover title wrong");
  assert(appEl.querySelectorAll(".dp-cast-dot").length === 13, "cast row must show 13 princess colors");
  assert(appEl.querySelector("#dp-start"), "start button missing");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1") || "null");
  assert(stored && stored.secret === SECRET, "license not persisted");
  return "cover";
});

await check("starting shows question 1 of 24 with three options and a progress bar", async () => {
  appEl.querySelector("#dp-start").click();
  await sleep(80);
  assert(appEl.querySelector(".dp-q-count").textContent.includes("第 1 题"), `expected Q1, got ${appEl.querySelector(".dp-q-count")?.textContent}`);
  assert(appEl.querySelectorAll(".dp-option").length === 3, "three options expected");
  assert(appEl.querySelector(".dp-progress i"), "progress bar missing");
  assert(appEl.querySelector(".dp-top").textContent.includes("1 / 24"), "topbar counter wrong");
  return "Q1";
});

await check("picking an option colors it and advances", async () => {
  appEl.querySelectorAll(".dp-option")[1].click();
  await sleep(60);
  assert(appEl.querySelectorAll(".dp-option")[1].classList.contains("picked"), "option must be picked before advancing");
  await sleep(340);
  assert(appEl.querySelector(".dp-q-count").textContent.includes("第 2 题"), "did not advance to Q2");
  appEl.querySelector("#dp-prev").click();
  await sleep(50);
  assert(appEl.querySelector(".dp-q-count").textContent.includes("第 1 题"), "上一题 failed");
  assert(appEl.querySelectorAll(".dp-option")[1].classList.contains("picked"), "returning must show the recorded pick");
  return "pick + back";
});

await check("a full 24-question run lands on a named result page", async () => {
  for (let i = 0; i < 24; i += 1) {
    const count = appEl.querySelector(".dp-q-count");
    assert(count, `question ${i + 1} missing`);
    appEl.querySelectorAll(".dp-option")[0].click();
    await sleep(340);
  }
  const name = appEl.querySelector(".dp-name");
  assert(name, "result name missing");
  assert(appEl.querySelector(".dp-name-en"), "english name missing");
  assert(appEl.querySelector(".dp-quote").textContent.trim().length > 2, "short quote missing");
  assert(appEl.querySelector(".dp-quote-source"), "quote source line missing");
  assert(appEl.querySelector(".dp-blurb").textContent.trim().length > 10, "two-sentence blurb missing");
  assert(appEl.querySelector("#dp-share"), "save button must sit before the fold content");
  const more = appEl.querySelector(".dp-more");
  assert(more && !more.attributes.open, "detail section must stay collapsed by default");
  assert(more.textContent.includes("完整解读"), "collapsed section missing");
  for (const id of ["#dp-copy", "#dp-again", "#dp-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  assert(appEl.querySelector(".dp-disclaimer"), "disclaimer missing");
  return `角色：${name.textContent}`;
});

await check("result page carries the princess accent color and artwork slot", () => {
  const section = appEl.querySelector(".dp-result");
  assert(section.attributes.style && section.attributes.style.includes("--dp-accent"), "accent color not set on result");
  assert(appEl.querySelector(".dp-portrait"), "portrait slot missing");
  return "accent + portrait";
});

await check("share and copy actions work inside the skin", async () => {
  canvasCreated = 0;
  appEl.querySelector("#dp-share").click();
  appEl.querySelector("#dp-copy").click();
  await sleep(60);
  const copy = appEl.querySelector("#dp-copy");
  assert(copy.textContent.includes("已复制"), `copy feedback wrong: ${copy.textContent}`);
  assert(canvasCreated >= 1, "share must build a canvas image");
  return "share + copy";
});

await check("again restarts at Q1, exit returns to the cover", async () => {
  appEl.querySelector("#dp-again").click();
  await sleep(60);
  assert(appEl.querySelector(".dp-q-count").textContent.includes("第 1 题"), "再测一次 failed");
  appEl.querySelector("#dp-exit").click();
  await sleep(60);
  assert(appEl.querySelector(".dp-cover"), "回封面 failed");
  return "again + exit";
});

/* ------------------------------------------------------- 可达性 ---- */
check("all 13 princesses are reachable, not via tie-break", () => {
  const theme = DP_THEMES[0];
  const ids = theme.results.map((r) => r.id);
  assert(ids.length === 13, `expected 13 results, got ${ids.length}`);
  const runs = 200;
  let seed = 424242;
  const rand = () => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed / 0x7fffffff;
  };
  const lows = [];
  for (const id of ids) {
    let wins = 0;
    for (let run = 0; run < runs; run += 1) {
      const answers = theme.questions.map((question) => {
        const best = question.options
          .map((o, i) => ({ i, s: o.scores[id] || 0 }))
          .sort((a, b) => b.s - a.s);
        const topScore = best[0].s;
        const topOptions = best.filter((b) => b.s === topScore).map((b) => b.i);
        if (rand() < 0.8) return topOptions[Math.floor(rand() * topOptions.length)];
        return Math.floor(rand() * question.options.length);
      });
      const { winnerId, scores } = selectWinner(theme, answers);
      if (winnerId === id) wins += 1;
      if (run === 0) {
        // full-leaning run must win with a strictly positive normalized margin
        const full = theme.questions.map((question) =>
          question.options
            .map((o, i) => ({ i, s: o.scores[id] || 0 }))
            .sort((a, b) => b.s - a.s)[0].i);
        const verdict = selectWinner(theme, full);
        assert(verdict.winnerId === id, `full-leaning run elects ${verdict.winnerId} for ${id}`);
        const bounds = theme.scoring.normalization_bounds;
        const norm = (raw, id2) => (100 * (raw[id2] - bounds[id2].minimum)) / (bounds[id2].maximum - bounds[id2].minimum);
        const mine = norm(verdict.scores, id);
        const bestOther = Math.max(...ids.filter((x) => x !== id).map((x) => norm(verdict.scores, x)));
        if (mine - bestOther < 3) lows.push(`${id} margin ${((mine - bestOther)).toFixed(1)}`);
      }
    }
    const rate = wins / runs;
    assert(rate >= 0.8, `${id} leaning win-rate ${(rate * 100).toFixed(1)}% < 80%`);
  }
  return `13/13 reachable; strict margins${lows.length ? " (thin: " + lows.join(", ") + ")" : " all ≥3 pts"}`;
});

/* ------------------------------------------------------- 隔离检查 ---- */
check("skin.css is fully scoped and does not touch other products", () => {
  const stripped = skinCss.replace(/\/\*[\s\S]*?\*\//g, "");
  let depth = 0;
  for (const line of stripped.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const opens = (trimmed.match(/{/g) || []).length;
    const closes = (trimmed.match(/}/g) || []).length;
    if (trimmed.endsWith("{") && opens === 1) {
      if (!/^(body\[data-skin|@media|@keyframes|from|to|\d+%)/.test(trimmed)) {
        throw new Error(`unscoped selector: ${trimmed}`);
      }
    }
    depth += opens - closes;
  }
  assert(depth === 0, "unbalanced braces in skin.css");
  for (const foreign of ["pp-", "ggw-"]) {
    assert(!skinCss.includes(foreign), `skin.css must not reference ${foreign} (cross-product leak)`);
  }
  return "scoped, no cross-product selectors";
});

