const { join } = await import("node:path");
const { pathToFileURL } = await import("node:url");
const { setupBrowserRuntime } = await import(
  pathToFileURL(join(browserPluginRoot, "scripts", "browser-client.mjs")).href
);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.getForUrl("http://127.0.0.1:8790/t/disney-princess");
const info = (await browser.tabs.list())[0];
const tab = await browser.tabs.get(info.id);
const checks = [];
for (const [url, marker, skin] of [
  ["http://127.0.0.1:8790/t/greek_goddess", "#gate-code", null],
  ["http://127.0.0.1:8790/t/grand-view-garden", "#ggw-gate-code", "grand-view-garden"],
  ["http://127.0.0.1:8790/t/pride-prejudice", "#pp-gate-code", "pride-prejudice"],
]) {
  await tab.goto(url);
  await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
  await tab.playwright.waitForTimeout(1400);
  const state = await tab.playwright.evaluate((sel) => ({
    gate: Boolean(document.querySelector(sel)),
    skin: document.body.getAttribute("data-skin"),
  }), marker);
  const skinOk = skin ? state.skin === skin : state.skin === null;
  checks.push(`${url.split("/t/")[1]}: ${state.gate && skinOk ? "OK" : "PROBLEM"}`);
}
// 回到迪士尼结果页交付
await tab.goto("http://127.0.0.1:8790/t/disney-princess");
await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
await tab.playwright.waitForTimeout(1000);
await tab.markDeliverable();
checks;

