  animation: dp-spin 2.6s cubic-bezier(.4, .1, .6, .9) infinite;
}

body[data-skin="disney-princess"] .dp-spark svg { width: 100%; height: 100%; }

@keyframes dp-spin {
  0% { transform: rotate(0) scale(1); }
  50% { transform: rotate(180deg) scale(.86); }
  100% { transform: rotate(360deg) scale(1); }
}

body[data-skin="disney-princess"] .dp-loading-text {
  margin: 18px 0 4px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: .14em;
}

/* ---------------------------------------------------------------- 结果 ---- */
body[data-skin="disney-princess"] .dp-result {
