/* 你是哪位迪士尼公主？—— 产品视觉层样式
 *
 * 作用域：全部规则挂在 body[data-skin="disney-princess"] 下，与其他产品
 * 和默认模板完全隔离。
 *
 * 世界观：星光游园会。傍晚天空的柔和渐变（珊瑚粉→淡金→丁香紫），白色
 * 大圆角卡片配大投影；结果页的世界随公主的签名色变化（--dp-accent）。
 * 刻意与前三个产品区分：无纸张、无线框、无四栏长文，角色和画面为主。
 */

body[data-skin="disney-princess"] {
  --dp-accent: #B867B8;
  --dp-ink: #3A3A44;
  --dp-soft: #6B6A72;
  --dp-card: #FFFFFF;
  --dp-sans: -apple-system, BlinkMacSystemFont, "PingFang SC", "Segoe UI", "Microsoft YaHei", sans-serif;

  margin: 0;
  color: var(--dp-ink);
  font-family: var(--dp-sans);
  background:
    radial-gradient(900px 460px at 85% -6%, rgba(255, 214, 165, .55), transparent 62%),
    radial-gradient(820px 520px at 8% 12%, rgba(255, 176, 196, .5), transparent 60%),
    radial-gradient(900px 620px at 50% 108%, rgba(190, 168, 255, .38), transparent 64%),
    linear-gradient(180deg, #FFF4E6 0%, #FFE9F0 46%, #F3EEFF 100%);
  background-attachment: fixed;
}

body[data-skin="disney-princess"] .dp {
  max-width: 640px;
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  /* 底部随安全区让位；页面保持自然滚动，不锁 100vh */
  padding: 14px 16px calc(28px + env(safe-area-inset-bottom, 0px));
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="disney-princess"] .dp-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 12px;
  color: var(--dp-soft);
  font-size: 12px;
  letter-spacing: .08em;
}

body[data-skin="disney-princess"] .dp-brand {
  color: var(--dp-ink);
  font-weight: 700;
  letter-spacing: .06em;
}

body[data-skin="disney-princess"] .dp-title {
  margin: 8px 0 14px;
  font-size: clamp(38px, 10vw, 58px);
  font-weight: 800;
  line-height: 1.18;
  letter-spacing: .02em;
  color: var(--dp-ink);
}

body[data-skin="disney-princess"] .dp-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--dp-soft);
  font-size: 15px;
  line-height: 1.9;
}

body[data-skin="disney-princess"] .dp-foot {
  margin: 30px 0 0;
  color: #8B8994;
  font-size: 11.5px;
  line-height: 1.8;
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="disney-princess"] .dp-btn {
  padding: 14px 44px;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #B867B8, #7A5FD0);
  color: #FFF;
  font: 700 16px/1 var(--dp-sans);
  letter-spacing: .18em;
  text-indent: .18em;
  cursor: pointer;
  box-shadow: 0 10px 22px rgba(150, 105, 200, .38);
  transition: transform .16s ease, box-shadow .16s ease, filter .16s ease;
}

body[data-skin="disney-princess"] .dp-btn:hover { transform: translateY(-2px); box-shadow: 0 14px 26px rgba(150, 105, 200, .44); }
body[data-skin="disney-princess"] .dp-btn:active { transform: translateY(0) scale(.98); }
body[data-skin="disney-princess"] .dp-btn-big { padding: 16px 56px; font-size: 17px; }

body[data-skin="disney-princess"] .dp-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1.5px solid rgba(58, 58, 68, .28);
  background: transparent;
  color: var(--dp-soft);
  font: 500 13px/1.5 var(--dp-sans);
  letter-spacing: .08em;
  cursor: pointer;
}

body[data-skin="disney-princess"] .dp-link:hover { color: var(--dp-accent); border-color: var(--dp-accent); }
body[data-skin="disney-princess"] .dp-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 入场 ---- */
body[data-skin="disney-princess"] .dp-gate {
  max-width: 440px;
  margin: 8vh auto 0;
  padding: 34px 28px;
  border-radius: 28px;
  background: rgba(255, 255, 255, .86);
  box-shadow: 0 18px 44px rgba(120, 90, 160, .18);
  text-align: center;
}

body[data-skin="disney-princess"] .dp-dots {
  display: flex;
  justify-content: center;
  gap: 7px;
  margin-bottom: 20px;
}

body[data-skin="disney-princess"] .dp-dots i {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  animation: dp-twinkle 2.2s ease-in-out infinite;
}

body[data-skin="disney-princess"] .dp-dots i:nth-child(3n) { animation-delay: .3s; }
body[data-skin="disney-princess"] .dp-dots i:nth-child(3n+1) { animation-delay: .7s; }

@keyframes dp-twinkle {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .45; transform: scale(.82); }
}

body[data-skin="disney-princess"] .dp-gate .dp-title { font-size: clamp(30px, 8vw, 40px); }
body[data-skin="disney-princess"] .dp-gate-lead { margin: 0 0 24px; }

body[data-skin="disney-princess"] .dp-gate-form { display: flex; gap: 10px; }

body[data-skin="disney-princess"] .dp-gate-input {
  flex: 1;
  min-width: 0;
  padding: 13px 16px;
  border: 2px solid rgba(58, 58, 68, .14);
  border-radius: 999px;
  background: #FFF;
  color: var(--dp-ink);
  font: 600 14px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .06em;
}

body[data-skin="disney-princess"] .dp-gate-input:focus-visible {
  outline: 0;
  border-color: var(--dp-accent, #B867B8);
}

body[data-skin="disney-princess"] .dp-gate-error {
  min-height: 20px;
  margin: 12px 0 0;
  color: #C24E6A;
  font-size: 13px;
}

body[data-skin="disney-princess"] .dp-gate .dp-btn { padding: 13px 30px; }

/* ---------------------------------------------------------------- 封面 ---- */
body[data-skin="disney-princess"] .dp-cover {
  max-width: 480px;
  margin: 4vh auto 0;
  padding: 38px 26px 34px;
  border-radius: 34px;
  background: rgba(255, 255, 255, .82);
  box-shadow: 0 24px 60px rgba(120, 90, 160, .2);
  text-align: center;
}

body[data-skin="disney-princess"] .dp-castle {
  width: min(72%, 300px);
  margin: 0 auto 6px;
  color: #B79BD8;
}

body[data-skin="disney-princess"] .dp-castle svg { display: block; width: 100%; height: auto; }

body[data-skin="disney-princess"] .dp-cover .dp-title { font-size: clamp(36px, 9.4vw, 52px); }

body[data-skin="disney-princess"] .dp-cast {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 18px 0 4px;
}

body[data-skin="disney-princess"] .dp-cast-dot {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 3px solid #FFF;
  box-shadow: 0 3px 8px rgba(90, 70, 120, .25);
  transition: transform .16s ease;
}

body[data-skin="disney-princess"] .dp-cast-dot:hover { transform: scale(1.25); }

body[data-skin="disney-princess"] .dp-cover-actions { margin: 22px 0 0; }

/* ---------------------------------------------------------------- 答题 ----
   一题基本一屏：收紧装饰与间距，字号与交互不变。 */
body[data-skin="disney-princess"] .dp-progress {
  height: 8px;
  margin: 2px 2px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .75);
  box-shadow: inset 0 1px 3px rgba(120, 90, 160, .18);
  overflow: hidden;
}

body[data-skin="disney-princess"] .dp-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #FF9FB2, #B867B8 55%, #7A5FD0);
  transition: width .3s ease;
}

body[data-skin="disney-princess"] .dp-q-count {
  margin: 0 0 6px;
  color: #B867B8;
  font: 700 13px/1 var(--dp-sans);
  letter-spacing: .2em;
}

body[data-skin="disney-princess"] .dp-q-text {
  margin: 0 0 12px;
  padding: 15px 18px;
  border-radius: 18px;
  background: rgba(255, 255, 255, .92);
  box-shadow: 0 8px 22px rgba(120, 90, 160, .13);
  font-size: clamp(20px, 5.4vw, 26px);
  font-weight: 700;
  line-height: 1.6;
}

body[data-skin="disney-princess"] .dp-options {
  display: grid;
  gap: 8px;
}

body[data-skin="disney-princess"] .dp-option {
  display: flex;
  gap: 11px;
  align-items: center;
  padding: 12px 15px;
  border: 2px solid transparent;
  border-radius: 16px;
  background: rgba(255, 255, 255, .92);
  box-shadow: 0 5px 14px rgba(120, 90, 160, .11);
  color: var(--dp-ink);
  font: 400 15px/1.65 var(--dp-sans);
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease, background-color .16s ease;
  animation: dp-rise .4s cubic-bezier(.2, .7, .2, 1) both;
}

body[data-skin="disney-princess"] .dp-option:nth-child(2) { animation-delay: .06s; }
body[data-skin="disney-princess"] .dp-option:nth-child(3) { animation-delay: .12s; }

body[data-skin="disney-princess"] .dp-option:hover {
  border-color: color-mix(in srgb, var(--dp-accent, #B867B8) 46%, transparent);
}

body[data-skin="disney-princess"] .dp-option-key {
  display: grid;
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 10px;
  background: color-mix(in srgb, var(--dp-accent, #B867B8) 16%, #FFF);
  color: var(--dp-accent, #B867B8);
  font-weight: 800;
  font-size: 13px;
}

body[data-skin="disney-princess"] .dp-option.picked {
  background: var(--dp-accent, #B867B8);
  border-color: var(--dp-accent, #B867B8);
  color: #FFF;
  animation: dp-pop .26s ease;
}

body[data-skin="disney-princess"] .dp-option.picked .dp-option-key { background: rgba(255, 255, 255, .24); color: #FFF; }

@keyframes dp-pop {
  0% { transform: scale(1); }
  55% { transform: scale(1.035); }
  100% { transform: scale(1); }
}

@keyframes dp-rise {
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="disney-princess"] .dp-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 24px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="disney-princess"] .dp-loading {
  max-width: 380px;
  margin: 12vh auto 0;
  padding: 40px 26px;
  border-radius: 28px;
  background: rgba(255, 255, 255, .86);
  box-shadow: 0 18px 44px rgba(120, 90, 160, .18);
  text-align: center;
}

body[data-skin="disney-princess"] .dp-spark {
  width: 84px;
  height: 84px;
  margin: 0 auto;
  color: #E5B23A;
  animation: dp-spin 2.6s cubic-bezier(.4, .1, .6, .9) infinite;
}

body[data-skin="disney-princess"] .dp-spark svg { width: 100%; height: 100%; }

@keyframes dp-spin {
  0% { transform: rotate(0) scale(1); }
  50% { transform: rotate(180deg) scale(.86); }
  100% { transform: rotate(360deg) scale(1); }
}

body[data-skin="disney-princess"] .dp-loading-text {
  margin: 18px 0 4px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: .14em;
}

/* ---------------------------------------------------------------- 结果 ---- */
body[data-skin="disney-princess"] .dp-result {
  margin-top: 1vh;
}

body[data-skin="disney-princess"] .dp-portrait {
  position: relative;
  margin: 0 auto;
  max-width: 460px;
  border-radius: 30px;
  overflow: hidden;
  background: linear-gradient(160deg, color-mix(in srgb, var(--dp-accent) 34%, #FFF), #FFF);
  box-shadow: 0 24px 54px color-mix(in srgb, var(--dp-accent) 34%, transparent);
  aspect-ratio: 4 / 5;
}

body[data-skin="disney-princess"] .dp-portrait img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

body[data-skin="disney-princess"] .dp-portrait.dp-no-art { display: grid; place-items: center; }
body[data-skin="disney-princess"] .dp-fallback-star { display: none; font-size: 84px; color: var(--dp-accent); opacity: .8; }
body[data-skin="disney-princess"] .dp-portrait.dp-no-art .dp-fallback-star { display: block; }

body[data-skin="disney-princess"] .dp-name-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 12px;
  margin: 24px 0 6px;
}

body[data-skin="disney-princess"] .dp-name {
  margin: 0;
  font-size: clamp(34px, 9vw, 48px);
  font-weight: 800;
  color: var(--dp-accent);
  letter-spacing: .04em;
}

body[data-skin="disney-princess"] .dp-name-en {
  color: var(--dp-soft);
  font: italic 400 17px/1 Georgia, serif;
  letter-spacing: .06em;
}

/* 引用 + 出处 + 两句解释 */
body[data-skin="disney-princess"] .dp-quote {
  margin: 20px auto 0;
  max-width: 26em;
  text-align: center;
  font-size: clamp(17px, 4.8vw, 21px);
  font-weight: 600;
  line-height: 1.85;
  letter-spacing: .04em;
}

body[data-skin="disney-princess"] .dp-quote-source {
  margin: 8px 0 0;
  color: var(--dp-soft);
  font-size: 12px;
  letter-spacing: .12em;
  text-align: center;
}

body[data-skin="disney-princess"] .dp-blurb {
  margin: 20px auto 0;
  max-width: 27em;
  padding: 16px 20px;
  border-radius: 18px;
  background: rgba(255, 255, 255, .85);
  box-shadow: 0 8px 20px rgba(120, 90, 160, .1);
  font-size: 14.5px;
  line-height: 2;
  text-align: center;
}

/* 保存按钮区：单独排版，主按钮 + 次要链接 */
body[data-skin="disney-princess"] .dp-save {
  margin: 26px 0 0;
  text-align: center;
}

body[data-skin="disney-princess"] .dp-save .dp-btn { padding: 14px 52px; font-size: 15.5px; }

body[data-skin="disney-princess"] .dp-minor {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 14px;
}

/* 完整解读折叠区 */
body[data-skin="disney-princess"] .dp-more {
  margin: 26px 0 0;
  padding: 16px 20px;
  border-radius: 20px;
  background: rgba(255, 255, 255, .8);
}

body[data-skin="disney-princess"] .dp-more summary {
  color: var(--dp-soft);
  font-weight: 600;
  font-size: 13.5px;
  letter-spacing: .12em;
  cursor: pointer;
  text-align: center;
}

body[data-skin="disney-princess"] .dp-more[open] summary { margin-bottom: 12px; color: var(--dp-accent); }

body[data-skin="disney-princess"] .dp-keywords {
  margin: 0 0 12px;
  color: var(--dp-accent);
  font: 600 13px/1.6 var(--dp-sans);
  letter-spacing: .18em;
  text-align: center;
}

body[data-skin="disney-princess"] .dp-reading { margin: 0 0 14px; font-size: 14px; line-height: 2.05; }

body[data-skin="disney-princess"] .dp-detail h3 {
  margin: 14px 0 6px;
  color: var(--dp-accent);
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: .28em;
}

body[data-skin="disney-princess"] .dp-detail p { margin: 0; color: var(--dp-ink); font-size: 13.5px; line-height: 1.95; }

body[data-skin="disney-princess"] .dp-quote-full {
  margin: 18px 0 0;
  padding-top: 12px;
  border-top: 1px dashed rgba(120, 100, 150, .3);
  color: var(--dp-soft);
  font-size: 12px;
  line-height: 1.9;
}

body[data-skin="disney-princess"] .dp-basis { margin: 12px 0 0; color: #8B8994; font-size: 11.5px; line-height: 1.8; }

body[data-skin="disney-princess"] .dp-disclaimer {
  margin-top: 24px;
  padding-top: 14px;
  border-top: 1px dashed rgba(120, 100, 150, .3);
}

/* ---------------------------------------------------------------- 窄屏 ---- */
@media (max-width: 420px) {
  body[data-skin="disney-princess"] .dp { padding: 16px 14px 40px; }
  body[data-skin="disney-princess"] .dp-gate-form { flex-direction: column; }
  body[data-skin="disney-princess"] .dp-cover { padding: 30px 18px 28px; }
  body[data-skin="disney-princess"] .dp-more { padding: 14px 14px; }
}

/* ---------------------------------------------------------------- 动效偏好 ---- */
@media (prefers-reduced-motion: reduce) {
  body[data-skin="disney-princess"] .dp-dots i,
  body[data-skin="disney-princess"] .dp-spark,
  body[data-skin="disney-princess"] .dp-option,
  body[data-skin="disney-princess"] .dp-option.picked { animation: none; }
  body[data-skin="disney-princess"] .dp-btn,
  body[data-skin="disney-princess"] .dp-option,
  body[data-skin="disney-princess"] .dp-cast-dot { transition: none; }
}

input.new_string:
body[data-skin="disney-princess"] .dp-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
}

input.old_string:
body[data-skin="disney-princess"] .dp-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 24px;
}

