const d = JSON.parse(require('fs').readFileSync('server/content/disney_princess.json','utf8'));
const t = d.themes[0];
let longest = { q: 0, qi: 0, o: 0, oi: 0 };
t.questions.forEach((q, i) => {
  if (q.question.length > longest.q) longest = { ...longest, q: q.question.length, qi: i };
  q.options.forEach((o, j) => { if (o.text.length > longest.o) longest = { ...longest, o: o.text.length, oi: i }; });
});
console.log('longest question: #' + (longest.qi+1) + ' (' + longest.q + ' chars): ' + t.questions[longest.qi].question);
console.log('longest option in Q' + (longest.oi+1) + ' (' + longest.o + ' chars)');
t.questions[longest.qi].options.forEach((o,j)=>console.log('  Q'+(longest.qi+1)+' opt'+j+':', o.text.length, 'chars'));
"

