        return Math.floor(rand() * question.options.length);
      });
      const { winnerId } = selectWinner(theme, answers);
      if (winnerId === id) wins += 1;
    }
    const rate = wins / runs;
    const verdict = rate >= 0.85 ? "OK" : "LOW";
    console.log(`  ${verdict}  ${id.padEnd(8)} win-rate ${(rate * 100).toFixed(1)}%`);
    if (rate < 0.85) failures.push(`${id}: ${(rate * 100).toFixed(1)}%`);
  }
  return failures;
}

