/* 你是哪一种猫咪？—— 产品视觉层（product skin）
 *
 * 世界观：窗台贴纸。暖奶油底、白色圆角贴纸卡配硬偏移阴影（不是公主的
 * 柔光渐变，也不是文学测试的信纸线框）；橘色强调，每只猫有签名色。
 * 结果页结构：立绘 → 名字 → 原创角色短句（无引号，小字标注）→
 * 两句解释 → 保存结果图。功能全部来自公共引擎。
 */

const SKIN_ID = "cat-personas";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

const CAST = [
  { id: "orange", name: "干饭班长 · 橘猫", color: "#E8913C" },
  { id: "tuxedo", name: "凌晨跑酷选手 · 奶牛猫", color: "#3A3A44" },
  { id: "tabby", name: "巷战猎手 · 狸花", color: "#A67B4F" },
  { id: "white", name: "社交担当 · 白猫", color: "#8E9AAF" },
  { id: "black", name: "午夜巡警 · 黑猫", color: "#4E4259" },
  { id: "calico", name: "限时营业 · 三花", color: "#D9704F" },
  { id: "british", name: "高位观战 · 蓝猫", color: "#7C93AE" },
  { id: "fluffy", name: "被窝钉子户 · 长毛", color: "#C9A86B" },
];

const colorOf = (result) => {
  const cast = CAST.find((c) => c.id === (result && result.id));
  return (result && result.color) || (cast && cast.color) || "#E8913C";
};

function pageShell(inner) {
  return `<div class="cp">${inner}</div>`;
}

function brandBar(right) {
  return `<header class="cp-top"><span class="cp-brand">你是哪一种猫咪？</span><span class="cp-top-right">${right}</span></header>`;
}

function pawRow() {
  return `<div class="cp-paws" aria-hidden="true">${CAST.map((c) => `<i style="background:${c.color}"></i>`).join("")}</div>`;
}

function resultImage(resultId, name, accent) {
  const src = `/assets/cat-personas/${encodeURIComponent(resultId)}-front.webp`;
  return `
    <figure class="cp-portrait" style="--cp-accent:${accent}">
      <img src="${src}" alt="${esc(name || resultId || "猫咪")}的故事书立绘" loading="eager" decoding="async"
           onerror="this.closest('figure').classList.add('cp-no-art'); this.remove();">
      <span class="cp-fallback" aria-hidden="true">≈^..^≈</span>
    </figure>`;
}

/* ----------------------------------------------------------- 回执 ---- */
const GATE_ERRORS = {
  empty: "先输入兑换码喵。",
  already_bound: "这个码已在别的浏览器激活。换设备请联系卖家重置绑定。",
  rate_limited: "尝试太频繁了，让爪子歇一分钟。",
  invalid: "兑换码无效，检查一下再试。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("猫窝")}
    <section class="cp-card cp-gate">
      ${pawRow()}
      <h1 class="cp-title">凭码入窝</h1>
      <p class="cp-lead">输入兑换码开始。激活后与当前浏览器绑定，之后随时回来。</p>
      <div class="cp-gate-form">
        <input id="cp-gate-code" class="cp-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="cp-btn" id="cp-gate-submit">入窝</button>
      </div>
      <p class="cp-gate-error" id="cp-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="cp-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#cp-gate-code");
    const submit = root.querySelector("#cp-gate-submit");
    const error = root.querySelector("#cp-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`这个码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，检查一下再试。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("猫窝")}
    <section class="cp-card cp-cover">
      <figure class="cp-cover-art" aria-hidden="true">
        <svg viewBox="0 0 320 130">
          <g fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">
            <path d="M96 108V64l14-12 14 12 14-12 14 12v44"/>
            <path d="M104 44c2-8 8-12 12-6M154 44c-2-8-8-12-12-6"/>
            <path d="M168 108V72c0-8 6-12 14-12s14 4 14 12v36"/>
            <path d="M204 78c8-2 14 2 16 8M204 92c8 2 12 6 12 12"/>
            <path d="M46 108h228"/>
            <circle cx="252" cy="52" r="14"/>
            <path d="M244 42l-3-5M260 42l3-5M252 38v-5" stroke-width="2"/>
          </g>
        </svg>
      </figure>
      <h1 class="cp-title">你是哪一种<br>猫咪？</h1>
      <p class="cp-lead">${esc(ctx.theme.subtitle)}</p>
      <div class="cp-cast" aria-label="八种猫咪">
        ${CAST.map((c) => `<span class="cp-cast-dot" style="background:${c.color}" title="${esc(c.name)}"></span>`).join("")}
      </div>
      <div class="cp-cover-actions">
        <button class="cp-btn cp-btn-big" id="cp-start">开始</button>
      </div>
      <p class="cp-foot">16 个日常情境 · 约五分钟 · 原创娱乐测试，不测宠物也不要求养猫，更不是科学人格测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#cp-start").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 答题 ---- */
function questionView(ctx) {
  const buttons = ctx.options.map((text, i) => `
    <button class="cp-option${ctx.selected === i ? " picked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="cp-option-key" aria-hidden="true">${"ABC"[i] || "•"}</span>
      <span class="cp-option-text">${esc(text)}</span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`${ctx.index + 1} / ${ctx.total}`)}
    <div class="cp-progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${ctx.total}" aria-valuenow="${ctx.index + 1}">
      <i style="width:${Math.round(((ctx.index + 1) / ctx.total) * 100)}%"></i>
    </div>
    <section class="cp-q">
      <p class="cp-q-count">第 ${ctx.index + 1} 题 · 共 ${ctx.total} 题</p>
      <h2 class="cp-q-text">${esc(ctx.question)}</h2>
      <div class="cp-options">${buttons}</div>
      <div class="cp-q-nav">
        <button class="cp-link" id="cp-prev" ${ctx.index === 0 ? "disabled" : ""}>← 上一题</button>
        <button class="cp-link" id="cp-exit">先不答了</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".cp-option").forEach((option) => {
      option.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        option.classList.add("picked");
