  const grad = ctx2d.createLinearGradient(0, 0, 0, 1200);
  grad.addColorStop(0, mixHex(accent, "#FFF8EC", 0.62));
  grad.addColorStop(1, "#FFF9EE");
  ctx2d.fillStyle = grad;
