function wrap(ctx2d, text, maxWidth) {
  const rows = [];
  let current = "";
  for (const ch of String(text || "")) {
    if (ctx2d.measureText(current + ch).width > maxWidth) { rows.push(current); current = ch; }
    else current += ch;
  }
  if (current) rows.push(current);
