  font-size: clamp(26px, 7.2vw, 38px);
  font-weight: 800;
  color: var(--cp-accent);
  letter-spacing: .02em;
}

body[data-skin="cat-personas"] .cp-name-en {
  color: var(--cp-soft);
  font: italic 400 16px/1 Georgia, serif;
  letter-spacing: .06em;
}

body[data-skin="cat-personas"] .cp-quote {
  margin: 12px auto 0;
  max-width: 26em;
  text-align: center;
  font-size: clamp(17px, 4.8vw, 20px);
  font-weight: 700;
  line-height: 1.7;
  letter-spacing: .03em;
}

body[data-skin="cat-personas"] .cp-quote-source {
  margin: 5px 0 0;
  color: var(--cp-soft);
  font-size: 12px;
  letter-spacing: .18em;
  text-align: center;
}

body[data-skin="cat-personas"] .cp-blurb {
  margin: 10px auto 0;
  max-width: 30em;
  padding: 10px 16px;
  border-radius: 14px;
  border: 2px dashed color-mix(in srgb, var(--cp-accent, #E8913C) 55%, transparent);
  background: rgba(255, 255, 255, .75);
  font-size: 14.5px;
  line-height: 1.9;
  text-align: center;
}

