body[data-skin="cat-personas"] .cp-save {
  margin: 14px 0 0;
  text-align: center;
}

body[data-skin="cat-personas"] .cp-save .cp-btn { padding: 13px 42px; font-size: 15px; }

body[data-skin="cat-personas"] .cp-minor {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 8px;
}

