// Generate the 8 cat persona portraits (serial submit + auto-retry + short
// prompts — the pipeline lessons from run-disney-fronts.mjs).
//
// Usage:
//   powershell -ExecutionPolicy Bypass -File tools\run-image-api.ps1 -Script tools\run-cat-fronts.mjs -ExtraArgs @("--only","orange")
//   powershell -ExecutionPolicy Bypass -File tools\run-image-api.ps1 -Script tools\run-cat-fronts.mjs
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const KEY = (process.env.DSH_IMAGE_API_KEY || "").trim();
if (!KEY) throw new Error("DSH_IMAGE_API_KEY empty — run through tools/run-image-api.ps1");

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const ASSET = join(ROOT, "deploy-ready", "assets", "cat-personas");
const SUBMIT = "https://api.wuyinkeji.com/api/async/image_gpt_2.5";
const DETAIL = "https://api.wuyinkeji.com/api/async/detail";
const ASPECT = "896*1120";
const POLL_MS = 8000;
const TASK_DEADLINE_MS = 420000;
const ATTEMPTS = Number(process.env.DSH_ATTEMPTS || 4);

const onlyIdx = process.argv.indexOf("--only");
const idsIdx = process.argv.indexOf("--ids");
const ONLY = onlyIdx !== -1 ? process.argv[onlyIdx + 1] : null;
const IDS_ARG = idsIdx !== -1 ? process.argv[idsIdx + 1] : null;

/* 每只猫不同品种毛色 + 不同姿态/动作/小场景（不是头像换毛色）。原创演绎。 */
const BRIEFS = {
  orange: "One chubby orange tabby cat sitting upright in front of a full food bowl, front paws resting on the bowl rim, looking up hopefully, sunny kitchen window light.",
  tuxedo: "One black-and-white tuxedo cat leaping out of a cardboard box, tissue paper flying around, mid-pounce in a cozy living room.",
  tabby: "One brown mackerel tabby cat crouching on top of a bookshelf, tail hanging down, staring down at the room with focused eyes.",
  white: "One fluffy white cat rubbing against a visitor's legs at the entryway, tail up in a happy question mark, warm door light.",
  black: "One sleek black cat with bright yellow eyes walking along a windowsill at night, crescent moon and rooftops behind the glass.",
  calico: "One calico cat sitting with perfect posture on the armrest of a tall chair, tail curled around her paws, chin slightly raised.",
  british: "One round blue-gray cat lying on the top platform of a cat tree, eyes half closed, overlooking the room below.",
  fluffy: "One long-haired cream cat sunk deep into a blanket on a bed, only half of its face showing, afternoon sun stripes on the sheets.",
};

function buildPrompt(id) {
  // Short-prompt mode: long prompt word lists tripped the filter before.
  return `Flat storybook illustration of a cute cat, warm cream palette, big simple shapes, poster-like composition, flat graphic depth. ${BRIEFS[id]} No text, no logos, no watermark. Generate only the artwork.`;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const sha256 = (buf) => createHash("sha256").update(buf).digest("hex");

async function submitTask(prompt) {
  const res = await fetch(`${SUBMIT}?key=${encodeURIComponent(KEY)}`, {
    method: "POST",
    headers: { Authorization: KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ prompt, aspectRatio: ASPECT }),
  });
  const json = await res.json();
  if (json?.code !== 200) throw new Error(`submit rejected: ${JSON.stringify(json).slice(0, 200)}`);
  return json.data.id;
}

async function statusOf(taskId) {
  const res = await fetch(`${DETAIL}?key=${encodeURIComponent(KEY)}&id=${encodeURIComponent(taskId)}`, {
    headers: { Authorization: KEY },
  });
  const json = await res.json();
  return { status: json?.data?.status, message: json?.data?.message, url: json?.data?.result?.[0] };
}

if (!existsSync(ASSET)) mkdirSync(ASSET, { recursive: true });

const ids = ONLY ? [ONLY] : IDS_ARG ? IDS_ARG.split(",").map((s) => s.trim()).filter(Boolean) : Object.keys(BRIEFS);
for (const id of ids) {
  if (!BRIEFS[id]) throw new Error(`unknown persona id: ${id}`);
}

const manifestPath = join(ASSET, "manifest.json");
const manifest = existsSync(manifestPath)
  ? JSON.parse(readFileSync(manifestPath, "utf8"))
  : {
      purpose: "original flat-storybook cat portraits for the cat-personas skin (local demo; all characters original)",
      api: { submit: SUBMIT, detail: DETAIL, aspect_ratio: ASPECT, reference_images: "none" },
      images: [],
    };

for (const id of ids) {
  if (existsSync(join(ASSET, `${id}-front.png`))) {
    console.log(`[${id}] already generated, skipping`);
    continue;
  }
  const prompt = buildPrompt(id);
  let finished = false;
  for (let attempt = 1; attempt <= ATTEMPTS && !finished; attempt += 1) {
    let taskId;
    try {
      taskId = await submitTask(prompt);
      console.log(`[submit] ${id} (attempt ${attempt}/${ATTEMPTS}) -> ${taskId}`);
    } catch (error) {
      console.log(`[submit] ${id} FAILED: ${error.message}`);
      manifest.images.push({ id, status: "failed", stage: "submit", error: error.message, prompt });
      continue;
    }
    const submittedAt = Date.now();
    let settled = false;
    while (Date.now() - submittedAt < TASK_DEADLINE_MS) {
      await sleep(POLL_MS);
      let info;
      try { info = await statusOf(taskId); }
      catch { continue; }
      if (info.status === 2) {
        const file = `${id}-front.png`;
        try {
          const res = await fetch(info.url);
          const buf = Buffer.from(await res.arrayBuffer());
          writeFileSync(join(ASSET, file), buf);
          console.log(`[${id}] DONE -> ${file} (${buf.length} bytes)`);
          manifest.images.push({
            id, label: `${id}-front`, file: join("assets", "cat-personas", file),
            task_id: taskId, result_url: info.url, prompt,
            bytes: buf.length, sha256: sha256(buf), status: "ok",
          });
          finished = true;
        } catch (error) {
          console.log(`[${id}] download failed: ${error.message}`);
          manifest.images.push({ id, status: "failed", stage: "download", error: error.message, prompt });
        }
        settled = true;
        break;
      }
      if (info.status === 3) {
        console.log(`[${id}] generation failed: ${info.message}`);
        settled = true;
        break;
      }
    }
    if (!settled) console.log(`[${id}] STALLED past deadline`);
  }
  if (!finished) manifest.images.push({ id, status: "failed", stage: "exhausted", attempts: ATTEMPTS, prompt });
}

writeFileSync(manifestPath, JSON.stringify(manifest, null, 1) + "\n", "utf8");
console.log(`[manifest] ${manifestPath}`);

