/* 猫咪角色皮肤 · 端到端流程测试。
 *
 * 真实 deploy-ready/app.js + 真实 themes/cat-personas/skin.js 驱动完整流程：
 * 入场（兑换码）→ 封面 → 16 题作答 → 服务端评分（真实 server/scoring.mjs）
 * → 结果页（原创短句，不得伪造出处）→ 保存/重测。另附 8 结果可达性采样
 * 与跨产品隔离检查。
 *
 * Run: node tools/test-cat-skin.mjs
 */
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { selectWinner } from "../server/scoring.mjs";
import { sanitizeTheme } from "../server/sanitize.mjs";
import { productThemes } from "../server/products.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const results = [];
const check = (name, fn) => {
  try {
    const d = fn();
    if (d && typeof d.then === "function") {
      return d.then((detail) => results.push({ ok: true, name, d: detail }),
        (e) => results.push({ ok: false, name, d: e.message }));
    }
    results.push({ ok: true, name, d });
  } catch (e) {
    results.push({ ok: false, name, d: e.message });
  }
  return Promise.resolve();
};
const assert = (c, m) => { if (!c) throw new Error(m); };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* --------------------------------------------------------- DOM 桩 ---- */
const VOID = new Set(["br", "hr", "img", "input", "meta", "link", "area", "base", "col", "embed", "source", "track", "wbr"]);

function parseFragment(html) {
  const root = new El("#fragment");
  const stack = [root];
  const tokenRe = /<\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\s+[a-zA-Z-]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?)*)\s*(\/?)>|([^<]+)/g;
  let m;
  while ((m = tokenRe.exec(html))) {
    if (m[4] !== undefined) {
      if (m[4].trim()) stack[stack.length - 1].children.push(m[4]);
      continue;
    }
    const tag = m[1].toLowerCase();
    if (html[m.index + 1] === "/") {
      for (let i = stack.length - 1; i > 0; i -= 1) {
        if (stack[i].tagName === tag.toUpperCase()) { stack.length = i; break; }
      }
      continue;
    }
    const el = new El(tag);
    const attrRe = /([a-zA-Z-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
    let a;
    while ((a = attrRe.exec(m[2] || ""))) {
      const name = a[1].toLowerCase();
      const value = a[2] ?? a[3] ?? a[4] ?? "";
      el.attributes[name] = value;
      if (name === "id") el.id = value;
      if (name === "class") String(value).split(/\s+/).filter(Boolean).forEach((c) => el.classList.add(c));
      if (name.startsWith("data-")) el.dataset[name.slice(5).replace(/-([a-z])/g, (_, ch) => ch.toUpperCase())] = value;
    }
    stack[stack.length - 1].children.push(el);
    el.parent = stack[stack.length - 1];
    if (!VOID.has(tag) && m[3] !== "/") stack.push(el);
  }
  return root.children;
}

function matchesSelector(el, selector) {
  const parts = selector.trim().split(/\s+/);
  if (parts.length > 1) {
    const last = parts[parts.length - 1];
    if (!matchesSelector(el, last)) return false;
    let node = el.parent;
    let depth = parts.length - 2;
    while (node && depth >= 0) {
      if (matchesSelector(node, parts[depth])) depth -= 1;
      node = node.parent;
    }
    return depth < 0;
  }
  const m = selector.match(/^([a-zA-Z][\w-]*)?((?:[.#][\w-]+)*)$/);
  if (!m) throw new Error(`stub selector unsupported: ${selector}`);
  if (m[1] && el.tagName !== m[1].toUpperCase()) return false;
  const tokens = (m[2] || "").match(/[.#][\w-]+/g) || [];
  for (const part of tokens) {
    if (part[0] === "#") { if (el.id !== part.slice(1)) return false; }
    else if (!el.classList.contains(part.slice(1))) return false;
  }
  return true;
}

class El {
  constructor(tag) {
    this.tagName = tag.toUpperCase();
    this.id = "";
    this.children = [];
    this.attributes = {};
    this.dataset = {};
    this.listeners = {};
    this._cls = new Set();
    this.style = {};
    this.value = "";
    this.hidden = false;
    this.parent = null;
    this.classList = {
      add: (...names) => names.forEach((n) => this._cls.add(n)),
      remove: (...names) => names.forEach((n) => this._cls.delete(n)),
      contains: (n) => this._cls.has(n),
    };
  }
  set innerHTML(html) { this.children = parseFragment(html); }
  get innerHTML() { return this.children.map((c) => (typeof c === "string" ? c : c.outer)).join(""); }
  get outer() { return `<${this.tagName.toLowerCase()}>${this.innerHTML}</${this.tagName.toLowerCase()}>`; }
  get textContent() { return this.children.map((c) => (typeof c === "string" ? c : c.textContent)).join(""); }
  set textContent(v) { this.children = [String(v)]; }
  setAttribute(n, v) { this.attributes[n] = String(v); if (n === "id") this.id = String(v); }
  getAttribute(n) { return this.attributes[n] ?? null; }
  removeAttribute(n) { delete this.attributes[n]; }
  addEventListener(t, fn) { (this.listeners[t] ||= []).push(fn); }
  dispatch(type, event = {}) { (this.listeners[type] || []).forEach((fn) => fn({ ...event, target: this })); }
  click() { this.dispatch("click"); }
  focus() {}
  querySelector(sel) { return this.querySelectorAll(sel)[0] || null; }
  querySelectorAll(sel) {
    const out = [];
    const walk = (el) => {
      for (const child of el.children) {
        if (typeof child !== "string") {
          if (matchesSelector(child, sel)) out.push(child);
          walk(child);
        }
      }
    };
    walk(this);
    return out;
  }
  appendChild(child) { this.children.push(child); child.parent = this; return child; }
}

/* --------------------------------------------------- 浏览器全局桩 ---- */
const appEl = new El("main");
appEl.id = "app";
const docEl = new El("#document");
docEl.appendChild(appEl);
const bodyEl = new El("body");
docEl.appendChild(bodyEl);
const headEl = new El("head");
docEl.appendChild(headEl);

const storage = new Map();
globalThis.localStorage = {
  getItem: (k) => (storage.has(k) ? storage.get(k) : null),
  setItem: (k, v) => storage.set(k, String(v)),
  removeItem: (k) => storage.delete(k),
};
let canvasCreated = 0;
globalThis.document = Object.assign(docEl, {
  body: bodyEl,
  head: headEl,
  title: "",
  createElement: (tag) => {
    const el = new El(tag);
    if (tag === "canvas") {
      canvasCreated += 1;
      el.getContext = () => new Proxy({}, {
        get: (t, prop) => {
          if (prop === "createLinearGradient") return () => ({ addColorStop: () => {} });
          if (prop === "measureText") return () => ({ width: 10 });
