const skinModule = await import(pathToFileURL(join(ROOT, "deploy-ready", "themes", "cat-personas", "skin.js")).href);
globalThis.__MYTHIC_SKINS__ = { "cat-personas": skinModule.default };

const appSource = readFileSync(join(ROOT, "deploy-ready", "app.js"), "utf8");
new Function("module", "exports", appSource)({ exports: {} }, {});
await sleep(80);

const skinCss = readFileSync(join(ROOT, "deploy-ready", "themes", "cat-personas", "skin.css"), "utf8");

/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the cat entrance skin, not the default gate", () => {
  assert(appEl.querySelector(".cp-title"), "cat gate title missing");
  assert(appEl.querySelector(".cp-gate-form"), "gate form missing");
