  assert(bodyEl.attributes["data-skin"] === "cat-personas", "body data-skin not set");
  assert(globalThis.document.title === "你是哪一种猫咪？", `skin title wrong: ${globalThis.document.title}`);
  return "entrance";
});

await check("a valid code unlocks the cover with the 8-color cast row", async () => {
  const input = appEl.querySelector("#cp-gate-code");
  const submit = appEl.querySelector("#cp-gate-submit");
