  assert(appEl.querySelector(".cp-cover .cp-title").textContent.includes("猫咪"), "cover title wrong");
  assert(appEl.querySelectorAll(".cp-cast-dot").length === 8, "cast row must show 8 personas");
  assert(appEl.querySelector("#cp-start"), "start button missing");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1") || "null");
  assert(stored && stored.secret === SECRET, "license not persisted");
