});

await check("starting shows question 1 of 16 with three options and a progress bar", async () => {
  appEl.querySelector("#cp-start").click();
  await sleep(80);
  assert(appEl.querySelector(".cp-q-count").textContent.includes("第 1 题"), `expected Q1, got ${appEl.querySelector(".cp-q-count")?.textContent}`);
  assert(appEl.querySelectorAll(".cp-option").length === 3, "three options expected");
  assert(appEl.querySelector(".cp-progress i"), "progress bar missing");
  assert(appEl.querySelector(".cp-top").textContent.includes("1 / 16"), "topbar counter wrong");
  return "Q1";
});

await check("picking an option colors it and advances", async () => {
  appEl.querySelectorAll(".cp-option")[1].click();
  await sleep(60);
  assert(appEl.querySelectorAll(".cp-option")[1].classList.contains("picked"), "option must be picked before advancing");
  await sleep(340);
  assert(appEl.querySelector(".cp-q-count").textContent.includes("第 2 题"), "did not advance to Q2");
  appEl.querySelector("#cp-prev").click();
