  assert(name, "result name missing");
  assert(appEl.querySelector(".cp-name-en"), "english name missing");
  const quote = appEl.querySelector(".cp-quote");
  assert(quote && quote.textContent.trim().length > 4, "original short line missing");
  assert(!quote.textContent.includes("「"), "original line must not wear quotation marks");
  assert(appEl.querySelector(".cp-quote-source").textContent.includes("原创"), "original line must be labelled 原创");
  assert(appEl.querySelector(".cp-blurb").textContent.trim().length > 10, "blurb missing");
  assert(appEl.querySelector("#cp-share"), "save button missing");
  for (const id of ["#cp-copy", "#cp-again", "#cp-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  assert(!appEl.querySelector(".cp-more"), "no long report section allowed");
  return `角色：${name.textContent}`;
});

await check("result page carries the persona accent color and artwork slot", () => {
  const section = appEl.querySelector(".cp-result");
  assert(section.attributes.style && section.attributes.style.includes("--cp-accent"), "accent color not set on result");
