    [...js.matchAll(/class="([^"]*)"/g)].flatMap((m) => m[1].split(/\s+/))
      .flatMap((c) => c.match(/cp-[a-z0-9-]+/g) || [])
  );
  const hooks = new Set(["cp-top-right", "cp-option-text", "cp-q"]);
  const defined = new Set([...skinCss.matchAll(/\.(cp-[a-z0-9-]+)/g)].map((m) => m[1]));
  const missing = [...used].filter((c) => !defined.has(c) && !hooks.has(c));
  assert(missing.length === 0, `classes without CSS: ${missing.join(", ")}`);
  return `${used.size} classes covered`;
});

check("the skin carries no scoring, network or content-file logic", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "cat-personas", "skin.js"), "utf8");
  for (const banned of ["normalization_bounds", "selectWinner", "quiz_content_upgrade", "cat_personas.json", "disney_princess", "fetch("]) {
