//
// Run: node tools/build-cat-content.mjs
import { writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { selectWinner } from "../server/scoring.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

/* ------------------------------------------------------------- 结果 ---- */
const results = [
  {
    id: "british", name: "英国短毛猫", color: "#7C93AE",
    subtitle: "高冷围观：什么都看见了，但懒得搭理",
    quote: "看见了。不想动。",
    supplement: "你可以继续忙，我在这里监督。",
    character_basis: "拟人化角色设定，非真实品种性格的科学结论。",
    visual_direction: "简练手绘线条，蓝灰色块，蹲在桌沿居高临下，眯眼，大量留白",
  },
  {
    id: "ragdoll", name: "布偶猫", color: "#A8B8CC",
    subtitle: "贴贴黏人：人去哪儿跟去哪儿",
    quote: "你去哪儿，我去哪儿。",
    supplement: "包括洗手间，别想把我关在外面。",
    character_basis: "拟人化角色设定，非真实品种性格的科学结论。",
    visual_direction: "简练手绘线条，浅蓝灰色块，跟在人类脚后，歪头，大量留白",
  },
  {
    id: "siamese", name: "暹罗猫", color: "#C9A886",
    subtitle: "话多爱回应：什么事都要喵两句",
    quote: "喵，喵喵，喵喵喵。",
    supplement: "翻译过来就是：都听见了，而且我有意见。",
    character_basis: "拟人化角色设定，非真实品种性格的科学结论。",
    visual_direction: "简练手绘线条，奶油底重点色块，张嘴发声，尾巴翘起，大量留白",
  },
  {
    id: "maine", name: "缅因猫", color: "#8A6D4E",
    subtitle: "大只呆萌：块头很大，小事也能愣住",
    quote: "……嗯？",
    supplement: "块头是别人的三倍，反应慢三拍，气势全开。",
    character_basis: "拟人化角色设定，非真实品种性格的科学结论。",
    visual_direction: "简练手绘线条，棕灰色块，大猫卡在门缝，一脸茫然，大量留白",
  },
  {
    id: "american", name: "美国短毛猫", color: "#9AA5B1",
    subtitle: "好奇巡逻：每个袋子角落都检查",
    quote: "这个袋子我还没检查过。",
    supplement: "家里每个角落都逃不过巡逻，包括你的行李箱。",
    character_basis: "拟人化角色设定，非真实品种性格的科学结论。",
    visual_direction: "简练手绘线条，银灰色块，头埋进纸袋只剩尾巴，大量留白",
  },
  {
    id: "bengal", name: "孟加拉猫", color: "#D98E4A",
    subtitle: "精力过剩：把家当跑酷场",
    quote: "走廊？那是跑道。",
    supplement: "沙发是起跳台，你的床是着陆区。",
    character_basis: "拟人化角色设定，非真实品种性格的科学结论。",
    visual_direction: "简练手绘线条，金棕色块，飞身跳跃，动态线，大量留白",
  },
  {
    id: "persian", name: "波斯猫", color: "#E8D9C5",
    subtitle: "躺平享受：只想占住最舒服的位置",
    quote: "那个位置，是我的。",
    supplement: "全屋最舒服的地方自动归我，你去坐硬的那把。",
    character_basis: "拟人化角色设定，非真实品种性格的科学结论。",
    visual_direction: "简练手绘线条，奶油色块，摊平占据坐垫，眼缝微开，大量留白",
  },
  {
    id: "abyssinian", name: "阿比西尼亚猫", color: "#C97A3D",
    subtitle: "手欠机灵：越不让碰越想试试",
    quote: "不让碰？那我更得碰碰。",
    supplement: "刚收拾好的桌面，正好需要一只猫来整理。",
    character_basis: "拟人化角色设定，非真实品种性格的科学结论。",
    visual_direction: "简练手绘线条，砖红色块，一爪把杯子推向桌沿，坏笑，大量留白",
  },
];

/* ------------------------------------------------------------- 题目 ---- */
function q(n, question, options, note) {
  return {
    id: `cat-${String(n).padStart(2, "0")}`,
    question,
    options: options.map(([text, scores]) => ({ text, scores: Object.fromEntries(scores) })),
    editor_note: note,
  };
}

const questions = [
  q(1, "桌边有个杯子，你会——", [
    ["一爪子推下去看看。", [["abyssinian", 3], ["bengal", 1]]],
    ["盯着它，但不动。", [["british", 3], ["maine", 1]]],
    ["蹭人类的胳膊喵喵提醒。", [["siamese", 3], ["ragdoll", 1]]],
  ], "手欠 vs 高冷 vs 话多。"),
  q(2, "人类把门关上了。你——", [
    ["在门外喵到开门为止。", [["siamese", 3], ["ragdoll", 1]]],
    ["贴着门缝一起进去。", [["ragdoll", 3], ["siamese", 1]]],
    ["无所谓，正好在这儿睡。", [["persian", 3], ["british", 1]]],
  ], "话多抗议 vs 黏人跟进 vs 就地躺平。"),
  q(3, "家里来了一个新纸箱。你——", [
    ["先把每个角都检查一遍。", [["american", 3], ["siamese", 1]]],
    ["直接当新床，验收合格。", [["persian", 3], ["maine", 1]]],
    ["从三米外助跑，跳进去。", [["bengal", 3], ["abyssinian", 1]]],
  ], "巡逻检查 vs 占位验收 vs 助跑入场。"),
  q(4, "凌晨三点，你突然醒了。你——", [
    ["在走廊来回狂奔。", [["bengal", 3], ["american", 1]]],
    ["把桌上的小东西一样样拨到地上。", [["abyssinian", 3], ["bengal", 1]]],
    ["看了一眼，继续睡。", [["british", 3], ["persian", 1]]],
  ], "跑酷 vs 手欠 vs 高冷。"),
  q(5, "人类在吃饭。你——", [
    ["在每把椅子下面轮流巡逻。", [["american", 3], ["bengal", 1]]],
    ["直接上桌，踩进盘子里。", [["abyssinian", 3], ["siamese", 1]]],
    ["卧在人类腿上，陪吃到完。", [["ragdoll", 3], ["maine", 1]]],
  ], "巡逻 vs 手欠 vs 黏人。"),
  q(6, "逗猫棒出现了。你——", [
    ["暴冲十连跳。", [["bengal", 3], ["abyssinian", 1]]],
    ["眼睛动了动，身体没动。", [["british", 3], ["persian", 1]]],
    ["喵喵指挥人类甩得认真一点。", [["siamese", 3], ["ragdoll", 1]]],
  ], "狂热 vs 高冷 vs 指挥。"),
  q(7, "人类拎包出门上班。你——", [
    ["跟到门口，喵喵送别。", [["siamese", 3], ["ragdoll", 1]]],
    ["跟到门口——然后跟出去。", [["ragdoll", 3], ["siamese", 1]]],
    ["目送，翻个身继续睡。", [["persian", 3], ["british", 1]]],
  ], "送别发言 vs 跟踪到底 vs 翻身再睡。"),
  q(8, "家里来了客人。你——", [
    ["上最高的柜子，围观全场。", [["british", 3], ["maine", 1]]],
    ["逐个检查客人的包和口袋。", [["american", 3], ["abyssinian", 1]]],
    ["躺客厅正中间，展示自己。", [["ragdoll", 3], ["siamese", 1]]],
  ], "高处围观 vs 查包巡逻 vs 中央展示。"),
  q(9, "人类在忙工作。你——", [
    ["趴在键盘上，不许动。", [["ragdoll", 3], ["persian", 1]]],
    ["跟鼠标线决斗。", [["abyssinian", 3], ["bengal", 1]]],
    ["整只猫压住人类的手臂。", [["maine", 3], ["british", 1]]],
  ], "贴贴压制 vs 决斗手欠 vs 大只压迫。"),
  q(10, "发现一个没见过的袋子。你——", [
    ["头先钻进去。", [["american", 3], ["siamese", 1]]],
    ["先拍两下，再钻。", [["abyssinian", 3], ["bengal", 1]]],
    ["用眼神检查，就够了。", [["british", 3], ["maine", 1]]],
  ], "直接钻 vs 试探钻 vs 眼神钻。"),
  q(11, "人类想抱你。你——", [
    ["顺势瘫成一滩。", [["ragdoll", 3], ["persian", 1]]],
    ["挣扎中顺便发表意见，喵喵喵。", [["siamese", 3], ["bengal", 1]]],
    ["勉强配合，但压得人类喘不过气。", [["maine", 3], ["american", 1]]],
  ], "瘫平 vs 发表意见 vs 重量级配合。"),
  q(12, "阳光正好，光斑落在地上。你——", [
    ["占住正中间，一趴一下午。", [["persian", 3], ["fluffy", 1]]],
    ["在光斑里翻滚追逐，当它是猎物。", [["bengal", 3], ["abyssinian", 1]]],
    ["蹲在窗台看鸟，顺便晒。", [["american", 3], ["british", 1]]],
  ], "占位 vs 玩光 vs 窗台巡逻。"),
  q(13, "你饿了。你——", [
    ["坐碗边喵喵催，催到开饭。", [["siamese", 3], ["ragdoll", 1]]],
    ["把碗扒拉得哐哐响。", [["abyssinian", 3], ["bengal", 1]]],
    ["直接坐在人类胸口，等他醒。", [["maine", 3], ["british", 1]]],
  ], "催单 vs 扒碗 vs 体重闹钟。"),
  q(14, "窗外落了一只鸟。你——", [
    ["咔咔咔咔咔。", [["maine", 3], ["american", 1]]],
    ["全速冲刺，撞上玻璃。", [["bengal", 3], ["abyssinian", 1]]],
    ["尾巴在摇，身体纹丝不动。", [["british", 3], ["persian", 1]]],
  ], "呆萌咔咔 vs 冲撞 vs 定身围观。"),
  q(15, "人类买了新家具。你——", [
    ["先抓两道，留个纪念。", [["abyssinian", 3], ["bengal", 1]]],
    ["绕着闻一圈，登记入库。", [["american", 3], ["ragdoll", 1]]],
    ["第一时间坐上去，测软硬。", [["persian", 3], ["british", 1]]],
  ], "留念 vs 登记 vs 验收软硬。"),
  q(16, "回顾今天这只猫的一天——", [
    ["查完全屋，一切正常。", [["american", 3], ["siamese", 1]]],
    ["跑了一天，瘫成一张毯。", [["bengal", 3], ["maine", 1]]],
    ["最舒服的位置，从头占到期末。", [["persian", 3], ["ragdoll", 1]]],
  ], "回望呼应：巡逻 / 跑酷 / 躺平。"),
];

/* 清理历史占位 id（旧版残留的 0 分角色键），再校验白名单。 */
const IDS = results.map((r) => r.id);
for (const question of questions) {
  for (const option of question.options) {
    for (const key of Object.keys(option.scores)) {
      if (option.scores[key] === 0) { delete option.scores[key]; continue; }
      if (!IDS.includes(key)) throw new Error(`unknown breed id in scores: ${key}`);
    }
  }
}

/* --------------------------------------------------- 边界与可达性 ---- */
const bounds = {};
for (const id of IDS) {
  let min = 0;
  let max = 0;
  for (const question of questions) {
    const vals = question.options.map((o) => o.scores[id] || 0);
    min += Math.min(...vals);
    max += Math.max(...vals);
  }
  if (max === min) throw new Error(`breed ${id} is unreachable: max === min`);
  bounds[id] = { minimum: min, maximum: max };
}

const theme = {
  id: "cat-personas",
  catalog_label: "猫咪角色",
  title: "假如你是一只猫，会是哪一种？",
  subtitle: "接下来，假设你就是一只猫——16 个情境，认领你的品种。",
  disclaimer: "这是原创的轻松娱乐游戏：品种只是拟人化角色设定，不代表真实品种性格，也不是人格测评。",
  source_status: "original",
  theme_basis: "全部角色、题目、文案均为原创拟人化设定，仅供娱乐。",
  results,
  questions,
  scoring: {
    method: "range_normalized_sum",
    answer_requirement: "每题恰选一项，全部题目完成后才计算；不把漏答视为0分。",
    points_per_option: 4,
    component_values: [0, 1, 3],
    missing_result_score: 0,
    formula: "每个结果先累加所选选项中的分数；归一化分 = 100 × (累计分 - minimum) / (maximum - minimum)。",
    normalization_bounds: bounds,
    result_order: IDS,
  },
};

function simulateReachability(runs = 600, leaningShare = 0.8, seedBase = 20261002) {
  const failures = [];
  for (const id of IDS) {
    let wins = 0;
    for (let run = 0; run < runs; run += 1) {
      let seed = seedBase + run * 131 + id.length * 977;
      const rand = () => {
        seed = (seed * 1103515245 + 12345) & 0x7fffffff;
        return seed / 0x7fffffff;
      };
      const answers = questions.map((question) => {
        const best = question.options
          .map((o, i) => ({ i, s: o.scores[id] || 0 }))
          .sort((a, b) => b.s - a.s);
        const topScore = best[0].s;
        const topOptions = best.filter((b) => b.s === topScore).map((b) => b.i);
        if (rand() < leaningShare) return topOptions[Math.floor(rand() * topOptions.length)];
        return Math.floor(rand() * question.options.length);
      });
      const { winnerId } = selectWinner(theme, answers);
      if (winnerId === id) wins += 1;
    }
    const rate = wins / runs;
    const verdict = rate >= 0.85 ? "OK" : "LOW";
    console.log(`  ${verdict}  ${id.padEnd(12)} win-rate ${(rate * 100).toFixed(1)}%`);
    if (rate < 0.85) failures.push(`${id}: ${(rate * 100).toFixed(1)}%`);
  }
  return failures;
}

console.log("[build] normalization bounds:");
for (const id of IDS) console.log(`  ${id.padEnd(12)} min=${bounds[id].minimum} max=${bounds[id].maximum}`);
console.log("[build] reachability (600 leaning runs per breed):");
const failures = simulateReachability();
if (failures.length) {
  console.error("[build] FAILURES:\n  " + failures.join("\n  "));
  process.exit(1);
}

const out = join(ROOT, "server", "content", "cat_personas.json");
writeFileSync(out, JSON.stringify({ themes: [theme] }, null, 1) + "\n", "utf8");
console.log(`[build] wrote ${out}`);
console.log(`[build] ${results.length} results, ${questions.length} questions`);

