    ["查完全屋，一切正常。", [["american", 3], ["siamese", 1]]],
    ["跑了一天，瘫成一张毯。", [["bengal", 3], ["maine", 1]]],
    ["最舒服的位置，从头占到期末。", [["persian", 3], ["ragdoll", 1]]],
  ], "回望呼应：巡逻 / 跑酷 / 躺平。"),
];

/* 清理历史占位 id（旧版残留的 0 分角色键），再校验白名单。 */
const IDS = results.map((r) => r.id);
for (const question of questions) {
  for (const option of question.options) {
    for (const key of Object.keys(option.scores)) {
      if (option.scores[key] === 0) { delete option.scores[key]; continue; }
      if (!IDS.includes(key)) throw new Error(`unknown breed id in scores: ${key}`);
    }
  }
}

/* --------------------------------------------------- 边界与可达性 ---- */
const bounds = {};
for (const id of IDS) {
  let min = 0;
  let max = 0;
  for (const question of questions) {
    const vals = question.options.map((o) => o.scores[id] || 0);
    min += Math.min(...vals);
    max += Math.max(...vals);
  }
  if (max === min) throw new Error(`breed ${id} is unreachable: max === min`);
  bounds[id] = { minimum: min, maximum: max };
}

const theme = {
  id: "cat-personas",
  catalog_label: "猫咪角色",
  title: "假如你是一只猫，会是哪一种？",
  subtitle: "接下来，假设你就是一只猫——16 个情境，认领你的品种。",
  disclaimer: "这是原创的轻松娱乐游戏：品种只是拟人化角色设定，不代表真实品种性格，也不是人格测评。",
  source_status: "original",
  theme_basis: "全部角色、题目、文案均为原创拟人化设定，仅供娱乐。",
  results,
  questions,
  scoring: {
    method: "range_normalized_sum",
    answer_requirement: "每题恰选一项，全部题目完成后才计算；不把漏答视为0分。",
    points_per_option: 4,
    component_values: [0, 1, 3],
    missing_result_score: 0,
    formula: "每个结果先累加所选选项中的分数；归一化分 = 100 × (累计分 - minimum) / (maximum - minimum)。",
    normalization_bounds: bounds,
    result_order: IDS,
  },
};

function simulateReachability(runs = 600, leaningShare = 0.8, seedBase = 20261002) {
  const failures = [];
  for (const id of IDS) {
    let wins = 0;
    for (let run = 0; run < runs; run += 1) {
      let seed = seedBase + run * 131 + id.length * 977;
      const rand = () => {
        seed = (seed * 1103515245 + 12345) & 0x7fffffff;
        return seed / 0x7fffffff;
      };
      const answers = questions.map((question) => {
        const best = question.options
          .map((o, i) => ({ i, s: o.scores[id] || 0 }))
          .sort((a, b) => b.s - a.s);
        const topScore = best[0].s;
        const topOptions = best.filter((b) => b.s === topScore).map((b) => b.i);
        if (rand() < leaningShare) return topOptions[Math.floor(rand() * topOptions.length)];
        return Math.floor(rand() * question.options.length);
      });
      const { winnerId } = selectWinner(theme, answers);
      if (winnerId === id) wins += 1;
    }
    const rate = wins / runs;
    const verdict = rate >= 0.85 ? "OK" : "LOW";
    console.log(`  ${verdict}  ${id.padEnd(12)} win-rate ${(rate * 100).toFixed(1)}%`);
    if (rate < 0.85) failures.push(`${id}: ${(rate * 100).toFixed(1)}%`);
  }
  return failures;
}

console.log("[build] normalization bounds:");
for (const id of IDS) console.log(`  ${id.padEnd(12)} min=${bounds[id].minimum} max=${bounds[id].maximum}`);
console.log("[build] reachability (600 leaning runs per breed):");
const failures = simulateReachability();
if (failures.length) {
  console.error("[build] FAILURES:\n  " + failures.join("\n  "));
  process.exit(1);
}

const out = join(ROOT, "server", "content", "cat_personas.json");
writeFileSync(out, JSON.stringify({ themes: [theme] }, null, 1) + "\n", "utf8");
console.log(`[build] wrote ${out}`);
console.log(`[build] ${results.length} results, ${questions.length} questions`);

/* 你是哪一种猫咪？—— 产品视觉层（product skin）
 *
 * 世界观：窗台贴纸。暖奶油底、白色圆角贴纸卡配硬偏移阴影（不是公主的
 * 柔光渐变，也不是文学测试的信纸线框）；橘色强调，每只猫有签名色。
 * 结果页结构：立绘 → 名字 → 原创角色短句（无引号，小字标注）→
 * 两句解释 → 保存结果图。功能全部来自公共引擎。
 */

const SKIN_ID = "cat-personas";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

const CAST = [
  { id: "british", name: "英国短毛猫", color: "#7C93AE" },
  { id: "ragdoll", name: "布偶猫", color: "#A8B8CC" },
  { id: "siamese", name: "暹罗猫", color: "#C9A886" },
  { id: "maine", name: "缅因猫", color: "#8A6D4E" },
  { id: "american", name: "美国短毛猫", color: "#9AA5B1" },
  { id: "bengal", name: "孟加拉猫", color: "#D98E4A" },
  { id: "persian", name: "波斯猫", color: "#E8D9C5" },
  { id: "abyssinian", name: "阿比西尼亚猫", color: "#C97A3D" },
];

const colorOf = (result) => {
  const cast = CAST.find((c) => c.id === (result && result.id));
  return (result && result.color) || (cast && cast.color) || "#E8913C";
};

function pageShell(inner) {
  return `<div class="cp">${inner}</div>`;
}

function brandBar(right) {
  return `<header class="cp-top"><span class="cp-brand">你是哪一种猫咪？</span><span class="cp-top-right">${right}</span></header>`;
}

function pawRow() {
  return `<div class="cp-paws" aria-hidden="true">${CAST.map((c) => `<i style="background:${c.color}"></i>`).join("")}</div>`;
}

function resultImage(resultId, name, accent) {
  const src = `/assets/cat-personas/${encodeURIComponent(resultId)}-front.webp`;
  return `
    <figure class="cp-portrait" style="--cp-accent:${accent}">
      <img src="${src}" alt="${esc(name || resultId || "猫咪")}的故事书立绘" loading="eager" decoding="async"
           onerror="this.closest('figure').classList.add('cp-no-art'); this.remove();">
      <span class="cp-fallback" aria-hidden="true">≈^..^≈</span>
    </figure>`;
}

/* ----------------------------------------------------------- 回执 ---- */
const GATE_ERRORS = {
  empty: "先输入兑换码喵。",
  already_bound: "这个码已在别的浏览器激活。换设备请联系卖家重置绑定。",
  rate_limited: "尝试太频繁了，让爪子歇一分钟。",
  invalid: "兑换码无效，检查一下再试。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("猫窝")}
    <section class="cp-card cp-gate">
      ${pawRow()}
      <h1 class="cp-title">凭码入窝</h1>
      <p class="cp-lead">输入兑换码开始。激活后与当前浏览器绑定，之后随时回来。</p>
      <div class="cp-gate-form">
        <input id="cp-gate-code" class="cp-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="cp-btn" id="cp-gate-submit">入窝</button>
      </div>
      <p class="cp-gate-error" id="cp-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="cp-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#cp-gate-code");
    const submit = root.querySelector("#cp-gate-submit");
    const error = root.querySelector("#cp-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`这个码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，检查一下再试。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("猫窝")}
    <section class="cp-card cp-cover">
      <figure class="cp-cover-art" aria-hidden="true">
        <svg viewBox="0 0 320 130">
          <g fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">
            <path d="M96 108V64l14-12 14 12 14-12 14 12v44"/>
            <path d="M104 44c2-8 8-12 12-6M154 44c-2-8-8-12-12-6"/>
            <path d="M168 108V72c0-8 6-12 14-12s14 4 14 12v36"/>
            <path d="M204 78c8-2 14 2 16 8M204 92c8 2 12 6 12 12"/>
            <path d="M46 108h228"/>
            <circle cx="252" cy="52" r="14"/>
            <path d="M244 42l-3-5M260 42l3-5M252 38v-5" stroke-width="2"/>
          </g>
        </svg>
      </figure>
      <h1 class="cp-title">你是哪一种<br>猫咪？</h1>
      <p class="cp-lead">${esc(ctx.theme.subtitle)}</p>
      <div class="cp-cast" aria-label="八种猫咪">
        ${CAST.map((c) => `<span class="cp-cast-dot" style="background:${c.color}" title="${esc(c.name)}"></span>`).join("")}
      </div>
      <div class="cp-cover-actions">
        <button class="cp-btn cp-btn-big" id="cp-start">开始</button>
      </div>
      <p class="cp-foot">16 个日常情境 · 约五分钟 · 原创娱乐测试，不测宠物也不要求养猫，更不是科学人格测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#cp-start").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 答题 ---- */
function questionView(ctx) {
  const buttons = ctx.options.map((text, i) => `
    <button class="cp-option${ctx.selected === i ? " picked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="cp-option-key" aria-hidden="true">${"ABC"[i] || "•"}</span>
      <span class="cp-option-text">${esc(text)}</span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`${ctx.index + 1} / ${ctx.total}`)}
    <div class="cp-progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${ctx.total}" aria-valuenow="${ctx.index + 1}">
      <i style="width:${Math.round(((ctx.index + 1) / ctx.total) * 100)}%"></i>
    </div>
    <section class="cp-q">
      <p class="cp-q-count">第 ${ctx.index + 1} 题 · 共 ${ctx.total} 题</p>
      <h2 class="cp-q-text">${esc(ctx.question)}</h2>
      <div class="cp-options">${buttons}</div>
      <div class="cp-q-nav">
        <button class="cp-link" id="cp-prev" ${ctx.index === 0 ? "disabled" : ""}>← 上一题</button>
        <button class="cp-link" id="cp-exit">先不答了</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".cp-option").forEach((option) => {
      option.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        option.classList.add("picked");
        option.setAttribute("aria-pressed", "true");
        window.setTimeout(() => ctx.select(Number(option.dataset.i)), 260);
      });
    });
    const prev = root.querySelector("#cp-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#cp-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

/* --------------------------------------------------------- 等待 ---- */
function resultLoadingView() {
  const html = pageShell(`
    ${brandBar("翻牌子")}
    <section class="cp-card cp-loading">
      <div class="cp-yarn" aria-hidden="true">
        <svg viewBox="0 0 120 120">
          <circle cx="60" cy="60" r="34" fill="none" stroke="currentColor" stroke-width="5"/>
          <path d="M32 50c18-10 38-10 56 0M30 66c18 10 42 10 60-2M44 34c-8 18-8 36 2 54M78 32c8 18 8 38-2 56"
                fill="none" stroke="currentColor" stroke-width="3" opacity=".6"/>
        </svg>
      </div>
      <p class="cp-loading-text">猫毛正在对答案……</p>
      <p class="cp-foot">判定在服务端完成。</p>
    </section>`);
  return { html };
}

/* ----------------------------------------------------------- 结果 ---- */
function verdictView(ctx) {
  const result = ctx.result || {};
  const accent = colorOf(result);
  const html = pageShell(`
    ${brandBar("翻牌结果")}
    <section class="cp-result" style="--cp-accent:${accent}">
      ${resultImage(result.id, result.name, accent)}
      <div class="cp-name-row">
        <h2 class="cp-name">${esc(result.name || "")}</h2>
        <span class="cp-name-en">${esc(result.english_name || "")}</span>
      </div>
      ${result.quote && result.quote.text ? `
      <p class="cp-quote">${esc(result.quote.text)}</p>
      <p class="cp-quote-source">原创角色短句</p>` : ""}
      <p class="cp-blurb">${esc(result.blurb || result.subtitle || "")}</p>

      <div class="cp-save">
        <button class="cp-btn" id="cp-share">保存结果图</button>
        <div class="cp-minor">
          <button class="cp-link" id="cp-copy">复制文案</button>
          <button class="cp-link" id="cp-again">再测一次</button>
          <button class="cp-link" id="cp-home">回封面</button>
        </div>
      </div>
    </section>`);

  const bind = (root) => {
    const copy = root.querySelector("#cp-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已复制 ✓";
      window.setTimeout(() => { copy.textContent = "复制文案"; }, 1800);
    });
    root.querySelector("#cp-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#cp-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#cp-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享结果图 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const ctx2d = canvas.getContext("2d");
  const accent = colorOf(result);

  const grad = ctx2d.createLinearGradient(0, 0, 0, 1200);
  grad.addColorStop(0, mixHex(accent, "#FFF8EC", 0.62));
  grad.addColorStop(1, "#FFF9EE");
  ctx2d.fillStyle = grad;
  ctx2d.fillRect(0, 0, 900, 1200);

  const center = (text, y, font, color) => {
    ctx2d.font = font;
    ctx2d.fillStyle = color;
    ctx2d.textAlign = "center";
    ctx2d.fillText(text, 450, y);
  };

  center("你是哪一种猫咪？ · 原创娱乐测试", 90, "600 30px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#33302B");

  const img = new Image();
  img.onload = () => {
    const w = 480;
    const h = (img.height / img.width) * w;
    const x = (900 - w) / 2;
    const y = 150;
    ctx2d.save();
    roundRect(ctx2d, x, y, w, h, 36);
    ctx2d.clip();
    ctx2d.drawImage(img, x, y, w, h);
    ctx2d.restore();
    ctx2d.strokeStyle = "#33302B";
    ctx2d.lineWidth = 7;
    roundRect(ctx2d, x + 6, y + 8, w, h, 36);
    ctx2d.stroke();
    ctx2d.strokeStyle = accent;
    ctx2d.lineWidth = 7;
    roundRect(ctx2d, x, y, w, h, 36);
    ctx2d.stroke();
    finish(y + h + 100);
  };
  img.onerror = () => finish(700);

  function finish(top) {
    center(result.name || "", top, "800 74px 'PingFang SC', 'Microsoft YaHei', sans-serif", accent);
    if (result.quote && result.quote.text) {
      ctx2d.font = "600 34px 'PingFang SC', 'Microsoft YaHei', sans-serif";
      ctx2d.fillStyle = "#33302B";
      ctx2d.textAlign = "center";
      const rows = wrap(ctx2d, result.quote.text, 660);
      rows.forEach((rowText, i) => ctx2d.fillText(rowText, 450, top + 70 + i * 48));
      center("原创角色短句", top + 70 + rows.length * 48 + 6, "300 22px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#6B6A72");
      top = top + 70 + rows.length * 48 + 40;
    }
    ctx2d.font = "400 28px 'PingFang SC', 'Microsoft YaHei', sans-serif";
    ctx2d.fillStyle = "#33302B";
    ctx2d.textAlign = "center";
    let by = top + 74;
    wrap(ctx2d, result.blurb || "", 640).forEach((rowText) => { ctx2d.fillText(rowText, 450, by); by += 44; });

    CAST.forEach((c, i) => {
      ctx2d.fillStyle = c.color;
      ctx2d.beginPath();
      ctx2d.arc(450 - (CAST.length - 1) * 11 + i * 22, 1120, 6, 0, Math.PI * 2);
      ctx2d.fill();
    });
    center("结果由答题选择生成 · 与任何现实猫咪无关", 1170, "300 22px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#9A98A0");

    canvas.toBlob((blob) => {
      if (!blob) return;
      const link = document.createElement("a");
      link.download = `cat-personas-${result.id || "result"}.png`;
      link.href = URL.createObjectURL(blob);
      link.click();
      window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    }, "image/png");
  }
}

function wrap(ctx2d, text, maxWidth) {
  const rows = [];
  let current = "";
  for (const ch of String(text || "")) {
    if (ctx2d.measureText(current + ch).width > maxWidth) { rows.push(current); current = ch; }
    else current += ch;
  }
  if (current) rows.push(current);
  return rows;
}

function roundRect(c, x, y, w, h, r) {
  c.beginPath();
  c.moveTo(x + r, y);
  c.arcTo(x + w, y, x + w, y + h, r);
  c.arcTo(x + w, y + h, x, y + h, r);
  c.arcTo(x, y + h, x, y, r);
  c.arcTo(x, y, x + w, y, r);
  c.closePath();
}

function mixHex(a, b, t) {
  const pa = [1, 3, 5].map((i) => parseInt(a.slice(i, i + 2), 16));
  const pb = [1, 3, 5].map((i) => parseInt(b.slice(i, i + 2), 16));
  return "#" + pa.map((v, i) => Math.round(v + (pb[i] - v) * t).toString(16).padStart(2, "0")).join("");
}

export default {
  id: SKIN_ID,
  title: "你是哪一种猫咪？",
  copyText(result) {
    return `${result.name || ""}\n${(result.quote && result.quote.text) || ""}（原创角色短句）\n${result.blurb || ""}\n\n来自「你是哪一种猫咪？」原创娱乐测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
};

