/* 你是哪一种猫咪？—— 产品视觉层样式
 *
 * 作用域：全部规则挂在 body[data-skin="cat-personas"] 下，与其他四个产品
 * 和默认模板完全隔离。
 *
 * 世界观：窗台贴纸。暖奶油底、白色圆角贴纸卡配硬偏移阴影（贴纸感），
 * 橘色强调；与公主的柔光渐变、文学测试的信纸线框明确区分。
 * 布局沿用手机纵向目标：一题一屏、结果立绘 38dvh、dvh + 安全区。
 */

body[data-skin="cat-personas"] {
  --cp-accent: #E8913C;
  --cp-ink: #33302B;
  --cp-soft: #6B6A72;
  --cp-card: #FFFFFF;
  --cp-line: #E8DFCE;
  --cp-sans: -apple-system, BlinkMacSystemFont, "PingFang SC", "Segoe UI", "Microsoft YaHei", sans-serif;

  margin: 0;
  color: var(--cp-ink);
  font-family: var(--cp-sans);
  background-color: #FBF3E4;
  background-image:
    radial-gradient(560px 340px at 88% -6%, rgba(232, 145, 60, .18), transparent 62%),
    radial-gradient(420px 300px at 4% 16%, rgba(201, 168, 107, .16), transparent 60%),
    radial-gradient(620px 420px at 50% 112%, rgba(142, 154, 175, .14), transparent 64%);
}

body[data-skin="cat-personas"] .cp {
  max-width: 640px;
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: 14px 16px calc(28px + env(safe-area-inset-bottom, 0px));
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="cat-personas"] .cp-top {
