      </div>
      ${result.quote ? `<p class="cp-quote">「${esc(result.quote)}」</p>` : ""}

      <div class="cp-save">
        <button class="cp-btn" id="cp-share">保存结果图</button>
        <div class="cp-minor">
          <button class="cp-link" id="cp-copy">复制文案</button>
          <button class="cp-link" id="cp-again">再测一次</button>
          <button class="cp-link" id="cp-home">回封面</button>
        </div>
      </div>
    </section>`);

  const bind = (root) => {
    const copy = root.querySelector("#cp-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已复制 ✓";
      window.setTimeout(() => { copy.textContent = "复制文案"; }, 1800);
    });
    root.querySelector("#cp-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#cp-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#cp-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享结果图 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const ctx2d = canvas.getContext("2d");
  const accent = colorOf(result);

  const grad = ctx2d.createLinearGradient(0, 0, 0, 1200);
  grad.addColorStop(0, mixHex(accent, "#FFF8EC", 0.62));
  grad.addColorStop(1, "#FFF9EE");
  ctx2d.fillStyle = grad;
  ctx2d.fillRect(0, 0, 900, 1200);

  const center = (text, y, font, color) => {
    ctx2d.font = font;
    ctx2d.fillStyle = color;
    ctx2d.textAlign = "center";
    ctx2d.fillText(text, 450, y);
  };

  center("假如你是一只猫，会是哪一种？", 90, "600 30px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#33302B");

  const img = new Image();
  img.onload = () => {
    const w = 480;
    const h = (img.height / img.width) * w;
    const x = (900 - w) / 2;
    const y = 150;
    ctx2d.save();
    roundRect(ctx2d, x, y, w, h, 36);
    ctx2d.clip();
    ctx2d.drawImage(img, x, y, w, h);
    ctx2d.restore();
    ctx2d.strokeStyle = "#33302B";
    ctx2d.lineWidth = 7;
    roundRect(ctx2d, x + 6, y + 8, w, h, 36);
    ctx2d.stroke();
    ctx2d.strokeStyle = accent;
    ctx2d.lineWidth = 7;
    roundRect(ctx2d, x, y, w, h, 36);
    ctx2d.stroke();
    finish(y + h + 110);
  };
  img.onerror = () => finish(700);

  function finish(top) {
    center(result.name || "", top, "800 78px 'PingFang SC', 'Microsoft YaHei', sans-serif", accent);
    const quoteText = result.quote ? `「${result.quote}」` : "";
    center(quoteText, top + 84, "700 40px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#33302B");
    center(result.supplement || "", top + 148, "400 28px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#6B6A72");

    CAST.forEach((c, i) => {
      ctx2d.fillStyle = c.color;
      ctx2d.beginPath();
      ctx2d.arc(450 - (CAST.length - 1) * 11 + i * 22, 1120, 6, 0, Math.PI * 2);
      ctx2d.fill();
    });
    center("结果由答题选择生成 · 品种为拟人化角色设定", 1170, "300 22px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#9A98A0");

    canvas.toBlob((blob) => {
      if (!blob) return;
      const link = document.createElement("a");
      link.download = `cat-personas-${result.id || "result"}.png`;
      link.href = URL.createObjectURL(blob);
      link.click();
      window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    }, "image/png");
  }
}

function wrap(ctx2d, text, maxWidth) {
  const rows = [];
  let current = "";
  for (const ch of String(text || "")) {
    if (ctx2d.measureText(current + ch).width > maxWidth) { rows.push(current); current = ch; }
    else current += ch;
  }
  if (current) rows.push(current);
  return rows;
}

function roundRect(c, x, y, w, h, r) {
  c.beginPath();
  c.moveTo(x + r, y);
  c.arcTo(x + w, y, x + w, y + h, r);
  c.arcTo(x + w, y + h, x, y + h, r);
  c.arcTo(x, y + h, x, y, r);
  c.arcTo(x, y, x + w, y, r);
  c.closePath();
}

function mixHex(a, b, t) {
  const pa = [1, 3, 5].map((i) => parseInt(a.slice(i, i + 2), 16));
  const pb = [1, 3, 5].map((i) => parseInt(b.slice(i, i + 2), 16));
  return "#" + pa.map((v, i) => Math.round(v + (pb[i] - v) * t).toString(16).padStart(2, "0")).join("");
}

export default {
  id: SKIN_ID,
  title: "假如你是一只猫，会是哪一种？",
  copyText(result) {
    return `${result.name || ""}\n「${result.quote || ""}」\n\n来自「假如你是一只猫，会是哪一种？」原创娱乐游戏`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
};

