  transform: rotate(-14deg);
  animation: cp-wiggle 2.4s ease-in-out infinite;
}

body[data-skin="cat-personas"] .cp-paws i:nth-child(2n) { animation-delay: .4s; }
body[data-skin="cat-personas"] .cp-paws i:nth-child(3n) { animation-delay: .8s; }

@keyframes cp-wiggle {
  0%, 100% { transform: rotate(-14deg) scale(1); }
  50% { transform: rotate(-4deg) scale(.9); }
}

body[data-skin="cat-personas"] .cp-gate .cp-title { font-size: clamp(30px, 8vw, 40px); }
body[data-skin="cat-personas"] .cp-gate-lead { margin: 0 0 22px; }

body[data-skin="cat-personas"] .cp-gate-form { display: flex; gap: 10px; }

body[data-skin="cat-personas"] .cp-gate-input {
  flex: 1;
  min-width: 0;
  padding: 13px 16px;
  border: 2.5px solid var(--cp-ink);
