  background: #FFF;
  color: var(--cp-ink);
  font: 600 14px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .06em;
}

body[data-skin="cat-personas"] .cp-gate-input:focus-visible {
  outline: 0;
  border-color: var(--cp-accent, #E8913C);
}

body[data-skin="cat-personas"] .cp-gate .cp-btn { padding: 13px 28px; }

body[data-skin="cat-personas"] .cp-gate-error {
  min-height: 20px;
  margin: 12px 0 0;
  color: #C24E6A;
  font-size: 13px;
}

/* ---------------------------------------------------------------- 封面 ---- */
body[data-skin="cat-personas"] .cp-cover {
  margin-top: 4vh;
  text-align: center;
}

body[data-skin="cat-personas"] .cp-cover-art {
  width: min(72%, 280px);
  margin: 0 auto 4px;
  color: var(--cp-ink);
}

body[data-skin="cat-personas"] .cp-cover-art svg { display: block; width: 100%; height: auto; }

body[data-skin="cat-personas"] .cp-cover .cp-title { font-size: clamp(34px, 9vw, 48px); }

body[data-skin="cat-personas"] .cp-cast-dot {
  width: 20px;
  height: 20px;
  border-radius: 50% 50% 50% 5px;
  transform: rotate(-14deg);
  border: 2.5px solid #FFF;
  box-shadow: 2px 3px 0 rgba(51, 48, 43, .35);
  transition: transform .16s ease;
}

body[data-skin="cat-personas"] .cp-cast-dot:hover { transform: rotate(0) scale(1.22); }
body[data-skin="cat-personas"] .cp-cover-actions { margin: 22px 0 0; }

/* ---------------------------------------------------------------- 答题 ---- */
body[data-skin="cat-personas"] .cp-progress {
  height: 10px;
  margin: 2px 2px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .8);
  border: 2px solid var(--cp-ink);
  overflow: hidden;
}

body[data-skin="cat-personas"] .cp-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: repeating-linear-gradient(135deg, #E8913C 0 10px, #F3A95C 10px 20px);
  transition: width .3s ease;
}

body[data-skin="cat-personas"] .cp-q-count {
  margin: 0 0 6px;
  color: #B8673C;
  font: 800 13px/1 var(--cp-sans);
  letter-spacing: .2em;
}

body[data-skin="cat-personas"] .cp-q-text {
  margin: 0 0 12px;
  padding: 15px 18px;
  border: 2.5px solid var(--cp-ink);
  border-radius: 18px;
  background: var(--cp-card);
  box-shadow: 4px 5px 0 rgba(51, 48, 43, .14);
  font-size: clamp(20px, 5.4vw, 26px);
  font-weight: 700;
  line-height: 1.6;
}

body[data-skin="cat-personas"] .cp-options { display: grid; gap: 9px; }

body[data-skin="cat-personas"] .cp-option {
  display: flex;
  gap: 11px;
  align-items: center;
  padding: 12px 15px;
  border: 2.5px solid rgba(51, 48, 43, .85);
  border-radius: 16px;
  background: var(--cp-card);
  box-shadow: 3px 4px 0 rgba(51, 48, 43, .16);
  color: var(--cp-ink);
  font: 400 15px/1.65 var(--cp-sans);
  text-align: left;
  cursor: pointer;
  transition: transform .14s ease, box-shadow .14s ease, background-color .14s ease;
  animation: cp-rise .4s cubic-bezier(.2, .7, .2, 1) both;
}

body[data-skin="cat-personas"] .cp-option:nth-child(2) { animation-delay: .06s; }
body[data-skin="cat-personas"] .cp-option:nth-child(3) { animation-delay: .12s; }

body[data-skin="cat-personas"] .cp-option:hover { transform: translate(-1px, -1px); box-shadow: 5px 6px 0 rgba(51, 48, 43, .2); }

body[data-skin="cat-personas"] .cp-option-key {
  display: grid;
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 9px;
  border: 2px solid rgba(51, 48, 43, .8);
  background: #FFF;
  color: var(--cp-ink);
  font-weight: 800;
  font-size: 13px;
}

body[data-skin="cat-personas"] .cp-option.picked {
  background: var(--cp-accent, #E8913C);
  border-color: var(--cp-ink);
  color: #FFF;
  transform: translate(2px, 3px);
  box-shadow: 1px 1px 0 rgba(51, 48, 43, .9);
  animation: cp-press .26s ease;
}

body[data-skin="cat-personas"] .cp-option.picked .cp-option-key { border-color: #FFF; background: rgba(255, 255, 255, .25); color: #FFF; }

@keyframes cp-press {
  0% { transform: translate(0, 0) scale(1.02); }
  100% { transform: translate(2px, 3px) scale(1); }
}

@keyframes cp-rise {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="cat-personas"] .cp-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="cat-personas"] .cp-loading { margin-top: 10vh; text-align: center; }

body[data-skin="cat-personas"] .cp-yarn {
  width: 92px;
  height: 92px;
  margin: 0 auto;
  color: #B8673C;
  animation: cp-roll 1.6s ease-in-out infinite;
}

body[data-skin="cat-personas"] .cp-yarn svg { width: 100%; height: 100%; }

@keyframes cp-roll {
  0% { transform: translateX(-14px) rotate(0); }
  100% { transform: translateX(14px) rotate(180deg); }
}

body[data-skin="cat-personas"] .cp-loading-text {
  margin: 18px 0 4px;
  font-weight: 800;
  font-size: 16px;
  letter-spacing: .14em;
}

/* ---------------------------------------------------------------- 结果 ---- */
body[data-skin="cat-personas"] .cp-result { margin-top: 1vh; }

body[data-skin="cat-personas"] .cp-portrait {
  height: min(52vh, 620px);
  height: min(52dvh, 620px);
  aspect-ratio: 4 / 5;
  width: auto;
  max-width: 100%;
  margin: 0 auto;
  border-radius: 22px;
  border: 2.5px solid var(--cp-ink);
  box-shadow: 6px 7px 0 rgba(51, 48, 43, .3);
  overflow: hidden;
  background: color-mix(in srgb, var(--cp-accent, #E8913C) 20%, #FFF);
}

body[data-skin="cat-personas"] .cp-portrait img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

body[data-skin="cat-personas"] .cp-portrait.cp-no-art { display: grid; place-items: center; }
body[data-skin="cat-personas"] .cp-fallback { display: none; font-size: 44px; color: var(--cp-accent); }
body[data-skin="cat-personas"] .cp-portrait.cp-no-art .cp-fallback { display: block; }

body[data-skin="cat-personas"] .cp-name-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 10px;
  margin: 12px 0 0;
}

body[data-skin="cat-personas"] .cp-name {
  margin: 0;
  font-size: clamp(28px, 8vw, 42px);
  font-weight: 800;
  color: var(--cp-accent);
  letter-spacing: .02em;
}

body[data-skin="cat-personas"] .cp-quote {
  margin: 12px auto 0;
  max-width: 26em;
  text-align: center;
  font-size: clamp(18px, 5vw, 22px);
  font-weight: 800;
  line-height: 1.6;
  letter-spacing: .04em;
}

body[data-skin="cat-personas"] .cp-supplement {
  margin: 6px auto 0;
  max-width: 27em;
  color: var(--cp-soft);
  font-size: 14.5px;
  line-height: 1.8;
  text-align: center;
}

/* 保存按钮区 */
body[data-skin="cat-personas"] .cp-save {
  margin: 14px 0 0;
  text-align: center;
}

body[data-skin="cat-personas"] .cp-save .cp-btn { padding: 13px 42px; font-size: 15px; }

body[data-skin="cat-personas"] .cp-minor {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 8px;
}

/* ---------------------------------------------------------------- 窄屏 ---- */
@media (max-width: 420px) {
  body[data-skin="cat-personas"] .cp { padding: 14px 13px 34px; }
  body[data-skin="cat-personas"] .cp-card { padding: 26px 18px; }
  body[data-skin="cat-personas"] .cp-gate-form { flex-direction: column; }
}

/* ---------------------------------------------------------------- 动效偏好 ---- */
@media (prefers-reduced-motion: reduce) {
  body[data-skin="cat-personas"] .cp-paws i,
  body[data-skin="cat-personas"] .cp-yarn,
  body[data-skin="cat-personas"] .cp-option { animation: none; }
  body[data-skin="cat-personas"] .cp-btn,
  body[data-skin="cat-personas"] .cp-option,
  body[data-skin="cat-personas"] .cp-cast-dot { transition: none; }
}

