const browserPluginRoot =
  process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { join } = await import("node:path");
const { pathToFileURL } = await import("node:url");
const { setupBrowserRuntime } = await import(
  pathToFileURL(join(browserPluginRoot, "scripts", "browser-client.mjs")).href
);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.getForUrl("http://127.0.0.1:8790/t/cat-personas");
const info = (await browser.tabs.list())[0];
const tab = await browser.tabs.get(info.id);
await tab.reload();
await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
await tab.playwright.waitForTimeout(1200);
const seq = [1,2,0,2,0,1,2,0,2,2,0,2,2,2,2,0];
for (let i = 0; i < 20; i += 1) {
  const state = await tab.playwright.evaluate((s) => {
    const name = document.querySelector(".cp-name");
    if (name) return { done: true, name: name.textContent };
    const start = document.querySelector("#cp-start");
    if (start) { start.click(); return { done: false, stage: "start" }; }
    const count = document.querySelector(".cp-q-count");
    const m = count ? count.textContent.match(/第 (\d+) 题/) : null;
    if (!m) return { done: false, stage: "wait" };
    const qNum = Number(m[1]);
    const want = s[qNum - 1] ?? 0;
    const option = document.querySelector(`.cp-option[data-i="${want}"]`);
    if (option && !option.classList.contains("picked")) { option.click(); return { done: false, q: qNum }; }
    return { done: false, q: qNum, picked: true };
  }, seq);
  if (state.done) { nodeRepl.write("结果: " + state.name); break; }
  await tab.playwright.waitForTimeout(520);
}
"finished";

