// Build server/content/little_women.json — 独立内容包（题目与评分原样取自
// 共享题库的 little-women 主题；结果记录加 quote/supplement 供皮肤展示）。
// 引文来源核实记录见 docs/little-women-quotes.md。
//
// Run: node tools/build-little-women-content.mjs
import { writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { selectWinner } from "../server/scoring.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

const SHARED = JSON.parse(readShared());
function readShared() {
  const { readFileSync } = require("node:fs");
  return readFileSync(join(ROOT, "server", "content", "quiz_content_upgrade.json"), "utf8");
}

const theme = JSON.parse(JSON.stringify(SHARED.themes.find((t) => t.id === "little-women")));
if (!theme) throw new Error("little-women theme missing from shared content");

/* 引文（先来源后选句）与补充句。kind: novel=原著 / film=2019 电影 / original=原创。
   来源核实记录：docs/little-women-quotes.md */
const QUOTES = {
  jo: {
    kind: "novel",
    text: "我想做一件了不起的事——一件我死后也不会被遗忘的大事。",
    source_short: "原著《小妇人》· 第 13 章 · 译文",
    scene: "Jo 在『空中楼阁』一章谈自己的梦想（Part 1, Ch.13）",
  },
  meg: {
    kind: "original",
    text: "把普通的日子过好，也是一种了不起。",
    source_short: "原创角色短句",
  },
  beth: {
    kind: "original",
    text: "我说得很轻，但你听见了。",
    source_short: "原创角色短句",
  },
  amy: {
    kind: "film",
    text: "这个世界对有野心的女孩很苛刻。",
    source_short: "电影《小妇人》(2019) · 台词 · 译文",
    scene: "Amy 的台词（葛韦格导演版；原著中无此句）",
  },
  sister: {
    kind: "original",
    text: "各自向前，也随时回头，就有人应。",
    source_short: "原创角色短句",
  },
};

const SUPPLEMENTS = {
  jo: "你的稿纸上永远有下一行要写。",
  meg: "你把日子过成了一件件做好的小东西。",
  beth: "屋子因为你在，才安下来。",
  amy: "你向着大世界走，眼光一直是自己的。",
  sister: "你让人各自长大，也让彼此有地方回话。",
};

theme.results = theme.results.map((r) => ({
  ...r,
  quote: QUOTES[r.id] || null,
  supplement: SUPPLEMENTS[r.id] || null,
}));

/* --------------------------------------------------- 可达性确认 ---- */
for (let run = 0; run < 1; run += 1) {
  for (const id of theme.results.map((r) => r.id)) {
    const full = theme.questions.map((question) =>
      question.options
        .map((o, i) => ({ i, s: o.scores[id] || 0 }))
        .sort((a, b) => b.s - a.s)[0].i);
    const { winnerId, scores } = selectWinner(theme, full);
    if (winnerId !== id) throw new Error(`full-leaning run elects ${winnerId} for ${id}`);
    const bounds = theme.scoring.normalization_bounds;
    const norm = (raw, id2) => (100 * (raw[id2] - bounds[id2].minimum)) / (bounds[id2].maximum - bounds[id2].minimum);
    const mine = norm(scores, id);
    const bestOther = Math.max(...theme.results.map((x) => x.id).filter((x) => x !== id).map((x) => norm(scores, x)));
    console.log(`  OK  ${id.padEnd(8)} margin ${((mine - bestOther)).toFixed(1)} pts`);
  }
}

const out = join(ROOT, "server", "content", "little_women.json");
writeFileSync(out, JSON.stringify({ themes: [theme] }, null, 1) + "\n", "utf8");
console.log(`[build] wrote ${out}`);
console.log(`[build] ${theme.results.length} results, ${theme.questions.length} questions (scoring untouched)`);

