/* 小妇人成长测试 —— 产品视觉层（product skin）
 *
 * 世界观：缝纫手记。暖麦纸底、深松绿缝线虚线边框（针脚感）、砖红点缀；
 * 与傲偏的象牙双细线信纸、公主的粉紫柔光、猫的奶油贴纸都不同。
 * 结果页（减字定稿）：立绘 → 名字 → 引用/原创短句 → 补充 → 保存按钮。
 * 引文来源核实：docs/little-women-quotes.md（原著/2019 电影/原创，如实标注）。
 */

const SKIN_ID = "little-women";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

const CAST = [
  { id: "jo", name: "不愿被定义的创作者", color: "#45586B" },
  { id: "meg", name: "认真生活的建设者", color: "#B06A5C" },
  { id: "beth", name: "安静的连接者", color: "#9A8FA8" },
  { id: "amy", name: "有审美的远行者", color: "#7493A8" },
  { id: "sister", name: "把爱变成力量的人", color: "#3E5A47" },
];

const colorOf = (result) => {
  const cast = CAST.find((c) => c.id === (result && result.id));
  return (result && result.color) || (cast && cast.color) || "#3E5A47";
};

function pageShell(inner) {
  return `<div class="lw">${inner}</div>`;
}

function brandBar(right) {
  return `<header class="lw-top"><span class="lw-brand">小妇人成长测试</span><span class="lw-top-right">${right}</span></header>`;
}

function resultImage(resultId, name, accent) {
  const src = `/assets/little-women/${encodeURIComponent(resultId)}-front.webp`;
  return `
    <figure class="lw-portrait" style="--lw-accent:${accent}">
      <img src="${src}" alt="${esc(name || resultId || "角色")}的故事书立绘" loading="eager" decoding="async"
           onerror="this.closest('figure').classList.add('lw-no-art'); this.remove();">
      <span class="lw-fallback" aria-hidden="true">❋</span>
    </figure>`;
}

/* ----------------------------------------------------------- 回执 ---- */
const GATE_ERRORS = {
  empty: "先输入兑换码。",
  already_bound: "这个码已在别的浏览器激活。换设备请联系卖家重置绑定。",
  rate_limited: "尝试太频繁了，稍等一分钟再来。",
  invalid: "兑换码无效，检查一下再试。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("手记")}
    <section class="lw-card lw-gate">
      <p class="lw-eyebrow">Little Women</p>
      <h1 class="lw-title">写下你的名字</h1>
      <p class="lw-lead">输入兑换码开始。激活后与当前浏览器绑定，之后随时回来。</p>
      <div class="lw-gate-form">
        <input id="lw-gate-code" class="lw-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="lw-btn" id="lw-gate-submit">开始</button>
      </div>
      <p class="lw-gate-error" id="lw-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="lw-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#lw-gate-code");
    const submit = root.querySelector("#lw-gate-submit");
    const error = root.querySelector("#lw-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`这个码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，检查一下再试。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("手记")}
    <section class="lw-card lw-cover">
      <p class="lw-eyebrow">Little Women · 成长测试</p>
      <h1 class="lw-title">在《小妇人》的回声里，<br>你怎样长大？</h1>
      <p class="lw-lead">${esc(ctx.theme.subtitle)}</p>
      <div class="lw-cast" aria-label="五种结果">
        ${CAST.map((c) => `<span class="lw-cast-dot" style="background:${c.color}" title="${esc(c.name)}"></span>`).join("")}
      </div>
      <div class="lw-cover-actions">
        <button class="lw-btn lw-btn-big" id="lw-start">翻开手记</button>
      </div>
      <p class="lw-foot">18 个生活片刻 · 约六分钟 · 原创娱乐测试，不是科学人格测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#lw-start").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 答题 ---- */
function questionView(ctx) {
  const buttons = ctx.options.map((text, i) => `
    <button class="lw-option${ctx.selected === i ? " picked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="lw-option-key" aria-hidden="true">${"ABC"[i] || "•"}</span>
      <span class="lw-option-text">${esc(text)}</span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`${ctx.index + 1} / ${ctx.total}`)}
    <div class="lw-progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${ctx.total}" aria-valuenow="${ctx.index + 1}">
      <i style="width:${Math.round(((ctx.index + 1) / ctx.total) * 100)}%"></i>
    </div>
    <section class="lw-q">
      <p class="lw-q-count">第 ${ctx.index + 1} 页 · 共 ${ctx.total} 页</p>
      <h2 class="lw-q-text">${esc(ctx.question)}</h2>
      <div class="lw-options">${buttons}</div>
      <div class="lw-q-nav">
        <button class="lw-link" id="lw-prev" ${ctx.index === 0 ? "disabled" : ""}>← 上一页</button>
        <button class="lw-link" id="lw-exit">先放下</button>
      </div>
