  title: "在《小妇人》的回声里，你怎样长大？",
  copyText(result) {
    const q = result.quote || {};
    const quoted = q.kind === "novel" || q.kind === "film";
    const quoteLine = q.text ? (quoted ? `「${q.text}」——${q.source_short || ""}` : `${q.text}（${q.source_short || "原创角色短句"}）`) : "";
    return `${result.name || ""}\n${quoteLine}\n${result.supplement || ""}\n\n来自「小妇人成长测试」原创娱乐测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
};

input.content:
/* 小妇人成长测试 —— 产品视觉层样式
 *
 * 作用域：全部规则挂在 body[data-skin="little-women"] 下，与其他五个产品
 * 和默认模板完全隔离。
 *
 * 世界观：缝纫手记。暖麦纸底、深松绿缝线虚线边框（针脚感）、砖红点缀、
 * 白卡硬偏移阴影；与傲偏象牙双细线、公主柔光渐变、猫贴纸风区分。
 * 布局沿用手机纵向目标：一页一屏、结果立绘 38dvh、dvh + 安全区。
 */

body[data-skin="little-women"] {
  --lw-accent: #3E5A47;
  --lw-ink: #33352F;
  --lw-soft: #6E7268;
  --lw-card: #FBF6EA;
  --lw-line: #CFC4A8;
  --lw-brick: #B4553E;
  --lw-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;

  margin: 0;
  color: var(--lw-ink);
  font-family: var(--lw-serif);
  background-color: #F1EAD8;
  background-image:
    radial-gradient(620px 380px at 90% -8%, rgba(62, 90, 71, .12), transparent 62%),
    radial-gradient(520px 340px at 0% 18%, rgba(180, 85, 62, .10), transparent 60%),
    repeating-linear-gradient(0deg, transparent 0 26px, rgba(62, 90, 71, .035) 26px 27px);
}

body[data-skin="little-women"] .lw {
  max-width: 640px;
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: 14px 16px calc(28px + env(safe-area-inset-bottom, 0px));
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="little-women"] .lw-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 14px;
  color: var(--lw-soft);
  font-size: 12px;
  letter-spacing: .1em;
}

body[data-skin="little-women"] .lw-brand {
  color: var(--lw-ink);
  font-weight: 700;
  letter-spacing: .08em;
}

body[data-skin="little-women"] .lw-eyebrow {
  margin: 0 0 10px;
  color: var(--lw-brick);
  font: 400 11px/1 Georgia, serif;
  letter-spacing: .3em;
  text-transform: uppercase;
}

body[data-skin="little-women"] .lw-title {
  margin: 6px 0 12px;
  font-size: clamp(28px, 7.6vw, 42px);
  font-weight: 700;
  line-height: 1.5;
  letter-spacing: .02em;
}

body[data-skin="little-women"] .lw-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--lw-soft);
  font-size: 14.5px;
  line-height: 1.95;
}

body[data-skin="little-women"] .lw-foot {
  margin: 24px 0 0;
  color: #8B8778;
  font-size: 11.5px;
  line-height: 1.8;
}

/* ---------------------------------------------------------------- 卡片 ---- */
body[data-skin="little-women"] .lw-card {
  max-width: 460px;
  margin: 0 auto;
  padding: 30px 26px;
  border: 1.5px dashed color-mix(in srgb, var(--lw-accent, #3E5A47) 65%, transparent);
  border-radius: 8px; /* 手作纸感：近方角 */
  background: var(--lw-card);
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="little-women"] .lw-btn {
  padding: 13px 44px;
  border: 1.5px solid var(--lw-accent, #3E5A47);
  border-radius: 6px;
  background: var(--lw-accent, #3E5A47);
  color: #F6F1E3;
  font: 700 15.5px/1 var(--lw-serif);
  letter-spacing: .22em;
  text-indent: .22em;
  cursor: pointer;
  transition: background-color .18s ease, border-color .18s ease;
}

body[data-skin="little-women"] .lw-btn:hover { background: #33493C; border-color: #33493C; }
body[data-skin="little-women"] .lw-btn-big { padding: 14px 50px; font-size: 16px; }

body[data-skin="little-women"] .lw-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1.5px solid rgba(51, 53, 47, .3);
  background: transparent;
  color: var(--lw-soft);
  font: 500 13px/1.5 var(--lw-serif);
  letter-spacing: .1em;
  cursor: pointer;
}

body[data-skin="little-women"] .lw-link:hover { color: var(--lw-brick); border-color: var(--lw-brick); }
body[data-skin="little-women"] .lw-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 入场 ---- */
body[data-skin="little-women"] .lw-gate { margin-top: 7vh; text-align: center; }

body[data-skin="little-women"] .lw-gate-lead { margin: 0 0 22px; }

body[data-skin="little-women"] .lw-gate-form { display: flex; gap: 10px; }

body[data-skin="little-women"] .lw-gate-input {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border: 1.5px dashed color-mix(in srgb, var(--lw-ink) 55%, transparent);
  border-radius: 6px;
  background: #FFF;
  color: var(--lw-ink);
  font: 600 14px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .06em;
}

body[data-skin="little-women"] .lw-gate-input:focus-visible {
  outline: 0;
  border: 2px solid var(--lw-brick);
}

body[data-skin="little-women"] .lw-gate .lw-btn { padding: 13px 30px; }

body[data-skin="little-women"] .lw-gate-error {
  min-height: 20px;
  margin: 12px 0 0;
  color: var(--lw-brick);
  font-size: 13px;
}

/* ---------------------------------------------------------------- 封面 ---- */
body[data-skin="little-women"] .lw-cover { margin-top: 4vh; text-align: center; }

body[data-skin="little-women"] .lw-cast {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 16px 0 4px;
}

body[data-skin="little-women"] .lw-cast-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 2px dashed rgba(51, 53, 47, .35);
  transition: transform .16s ease;
}

body[data-skin="little-women"] .lw-cast-dot:hover { transform: scale(1.22); border-style: solid; }
body[data-skin="little-women"] .lw-cover-actions { margin: 22px 0 0; }

/* ---------------------------------------------------------------- 答题 ---- */
body[data-skin="little-women"] .lw-progress {
  height: 6px;
  margin: 2px 2px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .7);
  overflow: hidden;
}

body[data-skin="little-women"] .lw-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: repeating-linear-gradient(90deg, var(--lw-accent, #3E5A47) 0 10px, transparent 10px 16px);
  transition: width .3s ease;
}

body[data-skin="little-women"] .lw-q-count {
  margin: 0 0 6px;
  color: var(--lw-brick);
  font: 700 13px/1 var(--lw-serif);
  letter-spacing: .2em;
}

body[data-skin="little-women"] .lw-q-text {
  margin: 0 0 12px;
  padding: 15px 18px;
  border: 1.5px dashed color-mix(in srgb, var(--lw-accent, #3E5A47) 55%, transparent);
  border-radius: 8px;
  background: var(--lw-card);
  font-size: clamp(20px, 5.4vw, 26px);
  font-weight: 700;
  line-height: 1.62;
}

body[data-skin="little-women"] .lw-options { display: grid; gap: 9px; }

body[data-skin="little-women"] .lw-option {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px 15px;
  border: 1.5px dashed color-mix(in srgb, var(--lw-ink) 40%, transparent);
  border-radius: 8px;
  background: var(--lw-card);
  color: var(--lw-ink);
  font: 400 15px/1.68 var(--lw-serif);
  text-align: left;
  cursor: pointer;
  transition: border-color .16s ease, background-color .16s ease;
  animation: lw-rise .4s cubic-bezier(.2, .7, .2, 1) both;
}

body[data-skin="little-women"] .lw-option:nth-child(2) { animation-delay: .06s; }
body[data-skin="little-women"] .lw-option:nth-child(3) { animation-delay: .12s; }

body[data-skin="little-women"] .lw-option:hover {
  border-color: var(--lw-accent, #3E5A47);
  border-style: solid;
}

body[data-skin="little-women"] .lw-option-key {
  display: grid;
  flex: 0 0 28px;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1.5px solid color-mix(in srgb, var(--lw-ink) 55%, transparent);
  border-radius: 50%;
  color: var(--lw-soft);
  font-weight: 700;
  font-size: 12.5px;
}

body[data-skin="little-women"] .lw-option.picked {
  border: 1.5px solid var(--lw-accent, #3E5A47);
  border-style: solid;
  background: color-mix(in srgb, var(--lw-accent, #3E5A47) 9%, var(--lw-card));
}

body[data-skin="little-women"] .lw-option.picked .lw-option-key {
  border-color: var(--lw-accent, #3E5A47);
  background: var(--lw-accent, #3E5A47);
  color: #F6F1E3;
}

@keyframes lw-rise {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="little-women"] .lw-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="little-women"] .lw-loading { margin-top: 10vh; text-align: center; }

body[data-skin="little-women"] .lw-loading-text {
  margin: 8px 0 4px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: .16em;
}

/* ---------------------------------------------------------------- 结果 ---- */
body[data-skin="little-women"] .lw-result { margin-top: 1vh; }

body[data-skin="little-women"] .lw-portrait {
  height: min(38vh, 500px);
  height: min(38dvh, 500px);
  aspect-ratio: 4 / 5;
  width: auto;
  max-width: 100%;
  margin: 0 auto;
  border-radius: 6px;
  border: 1.5px dashed color-mix(in srgb, var(--lw-accent, #3E5A47) 70%, transparent);
  overflow: hidden;
  background: color-mix(in srgb, var(--lw-accent, #3E5A47) 16%, var(--lw-card));
}

body[data-skin="little-women"] .lw-portrait img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

body[data-skin="little-women"] .lw-portrait.lw-no-art { display: grid; place-items: center; }
body[data-skin="little-women"] .lw-fallback { display: none; font-size: 44px; color: var(--lw-accent); }
body[data-skin="little-women"] .lw-portrait.lw-no-art .lw-fallback { display: block; }

body[data-skin="little-women"] .lw-name-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  margin: 14px 0 0;
}

body[data-skin="little-women"] .lw-name {
  margin: 0;
  font-size: clamp(26px, 7.4vw, 38px);
  font-weight: 700;
  color: var(--lw-accent);
  letter-spacing: .04em;
}

body[data-skin="little-women"] .lw-quote {
  margin: 12px auto 0;
  max-width: 26em;
  text-align: center;
  font-size: clamp(18px, 5vw, 22px);
  font-weight: 700;
  line-height: 1.65;
  letter-spacing: .04em;
}

body[data-skin="little-women"] .lw-quote-source {
  margin: 5px 0 0;
  color: var(--lw-soft);
  font-size: 12px;
  letter-spacing: .14em;
  text-align: center;
}

body[data-skin="little-women"] .lw-supplement {
  margin: 10px auto 0;
  max-width: 27em;
  color: var(--lw-ink);
  font-size: 15px;
  line-height: 1.9;
  text-align: center;
}

/* 保存按钮区 */
body[data-skin="little-women"] .lw-save {
  margin: 16px 0 0;
  text-align: center;
}

body[data-skin="little-women"] .lw-save .lw-btn { padding: 13px 42px; font-size: 15px; }

body[data-skin="little-women"] .lw-minor {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 8px;
}

/* ---------------------------------------------------------------- 窄屏 ---- */
@media (max-width: 420px) {
  body[data-skin="little-women"] .lw { padding: 14px 13px 34px; }
  body[data-skin="little-women"] .lw-card { padding: 24px 18px; }
  body[data-skin="little-women"] .lw-gate-form { flex-direction: column; }
}

/* ---------------------------------------------------------------- 动效偏好 ---- */
@media (prefers-reduced-motion: reduce) {
  body[data-skin="little-women"] .lw-option { animation: none; }
  body[data-skin="little-women"] .lw-option,
  body[data-skin="little-women"] .lw-cast-dot,
  body[data-skin="little-women"] .lw-progress i { transition: none; }
}

