  border-color: var(--lw-accent, #3E5A47);
  border-style: solid;
}

body[data-skin="little-women"] .lw-option-key {
  display: grid;
  flex: 0 0 28px;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1.5px solid color-mix(in srgb, var(--lw-ink) 55%, transparent);
  border-radius: 50%;
  color: var(--lw-soft);
  font-weight: 700;
  font-size: 12.5px;
}

body[data-skin="little-women"] .lw-option.picked {
  border: 1.5px solid var(--lw-accent, #3E5A47);
  border-style: solid;
  background: color-mix(in srgb, var(--lw-accent, #3E5A47) 9%, var(--lw-card));
}

body[data-skin="little-women"] .lw-option.picked .lw-option-key {
  border-color: var(--lw-accent, #3E5A47);
  background: var(--lw-accent, #3E5A47);
  color: #F6F1E3;
}

@keyframes lw-rise {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="little-women"] .lw-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="little-women"] .lw-loading { margin-top: 10vh; text-align: center; }

body[data-skin="little-women"] .lw-loading-text {
  margin: 8px 0 4px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: .16em;
}

/* ---------------------------------------------------------------- 结果 ---- */
body[data-skin="little-women"] .lw-result { margin-top: 1vh; }

body[data-skin="little-women"] .lw-portrait {
  height: min(38vh, 500px);
  height: min(38dvh, 500px);
  aspect-ratio: 4 / 5;
  width: auto;
  max-width: 100%;
  margin: 0 auto;
  border-radius: 6px;
  border: 1.5px dashed color-mix(in srgb, var(--lw-accent, #3E5A47) 70%, transparent);
  overflow: hidden;
  background: color-mix(in srgb, var(--lw-accent, #3E5A47) 16%, var(--lw-card));
}

body[data-skin="little-women"] .lw-portrait img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

body[data-skin="little-women"] .lw-portrait.lw-no-art { display: grid; place-items: center; }
body[data-skin="little-women"] .lw-fallback { display: none; font-size: 44px; color: var(--lw-accent); }
body[data-skin="little-women"] .lw-portrait.lw-no-art .lw-fallback { display: block; }

body[data-skin="little-women"] .lw-name-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  margin: 14px 0 0;
}

body[data-skin="little-women"] .lw-name {
  margin: 0;
  font-size: clamp(26px, 7.4vw, 38px);
  font-weight: 700;
  color: var(--lw-accent);
  letter-spacing: .04em;
}

body[data-skin="little-women"] .lw-quote {
  margin: 12px auto 0;
  max-width: 26em;
  text-align: center;
  font-size: clamp(18px, 5vw, 22px);
  font-weight: 700;
  line-height: 1.65;
  letter-spacing: .04em;
}

body[data-skin="little-women"] .lw-quote-source {
  margin: 5px 0 0;
  color: var(--lw-soft);
  font-size: 12px;
  letter-spacing: .14em;
  text-align: center;
}

body[data-skin="little-women"] .lw-supplement {
  margin: 10px auto 0;
  max-width: 27em;
  color: var(--lw-ink);
  font-size: 15px;
  line-height: 1.9;
  text-align: center;
}

/* 保存按钮区 */
body[data-skin="little-women"] .lw-save {
  margin: 16px 0 0;
  text-align: center;
}

body[data-skin="little-women"] .lw-save .lw-btn { padding: 13px 42px; font-size: 15px; }

body[data-skin="little-women"] .lw-minor {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 8px;
}

/* ---------------------------------------------------------------- 窄屏 ---- */
@media (max-width: 420px) {
  body[data-skin="little-women"] .lw { padding: 14px 13px 34px; }
  body[data-skin="little-women"] .lw-card { padding: 24px 18px; }
  body[data-skin="little-women"] .lw-gate-form { flex-direction: column; }
}

/* ---------------------------------------------------------------- 动效偏好 ---- */
@media (prefers-reduced-motion: reduce) {
  body[data-skin="little-women"] .lw-option { animation: none; }
  body[data-skin="little-women"] .lw-option,
  body[data-skin="little-women"] .lw-cast-dot,
  body[data-skin="little-women"] .lw-progress i { transition: none; }
}

